window.ENAMED_LOCAL_QUESTION_BANK["12"] = {"block":12,"count":134,"questions":[{"id":"b12-bradiarritmias-sincope-q01","number":1,"collectionBlock":12,"documentBlock":13,"area":"Clínica Médica","topic":"Bradiarritmias e Síncope","stem":"Um homem de 63 anos, recebendo medicação para dor epigástrica na sala de observação do pronto atendimento, apresenta um colapso ao levantar-se da poltrona. Qual é a conduta imediata mais adequada nesse caso?","options":{"A":"Realizar um eletrocardiograma de 12 derivações.","B":"Checar a responsividade.","C":"Aplicar 1mg de epinefrina EV.","D":"Iniciar compressões torácicas.","E":"Solicitar avaliação da cardiologia."},"answer":"B","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (1).pdf","sourceLabel":"Bradiarritmias e Síncope","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Diante de colapso súbito, a sequência inicial é verificar segurança, responsividade e respiração/pulso rapidamente; só depois se define RCP ou outra intervenção.\nPor que as outras estão erradas:\nA: ECG vem após avaliação inicial e estabilização.\nC: Epinefrina só é indicada após confirmar parada e iniciar RCP conforme algoritmo.\nD: Compressões começam se a pessoa estiver irresponsiva, sem respiração normal e sem pulso; isso ainda não foi checado.\nE: Avaliação especializada não precede o ABC inicial.\nPonto de prova: Primeiro passo na avaliação de colapso.\nFlashcard sugerido:\nPergunta: Qual é a primeira ação diante de uma pessoa que colapsa?\nResposta: Checar responsividade e respiração/pulso rapidamente.\n\nPérola:\nAntes de tratar uma parada, confirme a parada.\n\nArmadilha:\nPular diretamente para compressões ou medicação sem avaliação inicial.\n\n--------------------------------------------------------------------------------","tags":["Clínica Médica","Medicina Interna","Conduta Terapêutica","Urgência e Emergência","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags.txt","globalNumber":18},{"id":"b12-bradiarritmias-sincope-q02","number":2,"collectionBlock":12,"documentBlock":13,"area":"Clínica Médica","topic":"Bradiarritmias e Síncope","stem":"Um paciente de 64 anos foi levado por familiares à unidade de emergência logo após ter apresentado episódio de síncope. Segundo o paciente, ele já tinha apresentado 2 outros episódios nos últimos 3 meses, sempre precedidos por sensação de “tonteiras”, e, eventualmente, tem sentido a impressão de fraqueza, “escurecimento da visão” e sensação de queda iminente. Não há dados relevantes de história patológica pregressa do paciente, que não faz uso de nenhum fármaco regularmente. No exame físico, o paciente apresentava-se bradicárdico (42 batimentos por minuto), normotenso, com ritmo cardíaco regular em 3 tempos (B4), sem sopros. Seu pulso venoso jugular revelou a presença de intermitentes ondas “a em canhão”. Foi realizado um eletrocardiograma, que revelou padrão similar ao ilustrado na figura abaixo. O emergencista que atende esse paciente deverá explicar-lhe que será necessária a realização de:","options":{"A":"Cardioversão elétrica.","B":"Ablação de via anômala.","C":"Implante de marca-passo definitivo.","D":"Isolamento elétrico das vias pulmonares."},"answer":"C","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (1).pdf","sourceLabel":"Bradiarritmias e Síncope","images":["data:image/webp;base64,"],"comment":"Análise:\nCorreta: C.\nPor que está certa: Bradicardia importante, síncopes recorrentes, dissociação atrioventricular sugerida por ondas a em canhão e ECG compatível com bloqueio AV avançado indicam marcapasso definitivo.\nPor que as outras estão erradas:\nA: Cardioversão trata taquiarritmias, não bloqueio AV crônico.\nB: Ablação de via anômala trata síndromes de pré-excitação ou circuitos reentrantes.\nD: Isolamento de veias pulmonares é estratégia para fibrilação atrial.\nPonto de prova: Indicação de marcapasso em bloqueio AV sintomático.\nFlashcard sugerido:\nPergunta: Qual tratamento para bloqueio AV avançado com síncope?\nResposta: Implante de marcapasso definitivo.\n\nPérola:\nOnda a em canhão sugere dissociação AV.\n\nArmadilha:\nTratar bradicardia estrutural como taquiarritmia.\n\n--------------------------------------------------------------------------------","tags":["Cirurgia","Trauma","Eletrocardiograma","Interpretação de Exames","Urgência e Emergência","Avaliação Clínica"],"tagSource":"Tags.txt","globalNumber":29},{"id":"b12-bradiarritmias-sincope-q03","number":3,"collectionBlock":12,"documentBlock":13,"area":"Clínica Médica","topic":"Bradiarritmias e Síncope","stem":"A síncope corresponde a mais de 3% de todas as consultas ao departamento de emergência. Em relação a esse tema, assinale a alternativa correta.","options":{"A":"Síncope é definida pela perda transitória de consciência, ocasionada pela hipoperfusão cerebral global e caracterizada por rápido início, curta duração, recuperação completa e espontânea.","B":"Sempre há sintomas prodrômicos, que incluem náuseas, sudorese e turvação visual.","C":"A síncope não tem relação com causas cardiovasculares. Dessa forma, não possui implicações mais graves, como risco de morte.","D":"São tipos de síncope: transtorno psiquiátrico, doenças metabólicas, crise epiléptica e ataque isquêmico transitório vertebrobasilar.","E":"A causa mais comum de síncope é a cardiovascular (bradicardias, taquicardias e doenças cardíacas estruturais)."},"answer":"A","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (1).pdf","sourceLabel":"Bradiarritmias e Síncope","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: Síncope é perda transitória de consciência por hipoperfusão cerebral global, com início rápido, curta duração e recuperação espontânea completa.\nPor que as outras estão erradas:\nB: Pródromos podem faltar, especialmente em síncope arrítmica.\nC: Causas cardíacas existem e associam-se a maior mortalidade.\nD: Crise epiléptica, distúrbios metabólicos e transtornos psicogênicos são mimetizadores, não subtipos de síncope verdadeira.\nE: A causa mais comum é reflexa/vasovagal, não cardiovascular.\nPonto de prova: Definição e classificação da síncope.\nFlashcard sugerido:\nPergunta: Como se define síncope?\nResposta: Perda transitória de consciência por hipoperfusão cerebral global, com recuperação espontânea.\n\nPérola:\nSíncope é mecanismo hemodinâmico; convulsão é diagnóstico diferencial.\n\nArmadilha:\nChamar toda perda de consciência de síncope.\n\n--------------------------------------------------------------------------------","tags":["Clínica Médica","Medicina Interna","Conhecimento Conceitual","Urgência e Emergência","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags.txt","globalNumber":34},{"id":"b12-bradiarritmias-sincope-q04","number":4,"collectionBlock":12,"documentBlock":13,"area":"Clínica Médica","topic":"Bradiarritmias e Síncope","stem":"Paciente feminina, 55 anos, é admitida em pronto-socorro, devido à queixa de tontura e sudorese. Ao exame físico, PA 94/52, FC 24 bpm, FR 18, SpO2 95% em ar ambiente. O médico solicita um eletrocardiograma. De acordo com o eletrocardiograma a seguir, qual ritmo cardíaco é possível identificar?","options":{"A":"Bloqueio atrioventricular total.","B":"Bradicardia sinusal.","C":"Taquicardia sinusal.","D":"Taquicardia supraventricular.","E":"Fibrilação atrial."},"answer":"A","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (1).pdf","sourceLabel":"Bradiarritmias e Síncope","images":["data:image/webp;base64,"],"comment":"Análise:\nCorreta: A.\nPor que está certa: FC de 24 bpm e ECG compatível com dissociação entre ondas P e QRS indicam bloqueio atrioventricular total.\nPor que as outras estão erradas:\nB: Na bradicardia sinusal há relação 1:1 entre P e QRS, apenas com frequência baixa.\nC: A frequência não é taquicárdica.\nD: TSV é rápida e geralmente de QRS estreito.\nE: FA é irregularmente irregular e não apresenta ondas P organizadas.\nPonto de prova: Reconhecimento do bloqueio AV total no ECG.\nFlashcard sugerido:\nPergunta: Qual achado define BAV total?\nResposta: Dissociação atrioventricular completa entre ondas P e complexos QRS.\n\nPérola:\nP e QRS independentes = BAV total.\n\nArmadilha:\nInterpretar apenas a frequência e não a relação atrioventricular.\n\n--------------------------------------------------------------------------------","tags":["Clínica Médica","Cardiologia","Eletrocardiograma","Interpretação de Exames","Urgência e Emergência","Avaliação Clínica"],"tagSource":"Tags.txt","globalNumber":35},{"id":"b12-bradiarritmias-sincope-q05","number":5,"collectionBlock":12,"documentBlock":13,"area":"Clínica Médica","topic":"Bradiarritmias e Síncope","stem":"Para qual destas situações há indicação CLASSE I de implante de marcapasso definitivo?","options":{"A":"Doença do nó sinusal em pacientes em uso de amiodarona.","B":"Bloqueio atrioventricular de segundo grau Mobitz I (Wenckebach) durante o sono.","C":"Síncope recorrente, > 40 anos de idade e documentação de pausa sintomática espontânea maior que 6 segundos.","D":"Pacientes com miocardiopatia hipertrófica forma obstrutiva, mesmo com gradiente de via de saída de ventrículo esquerdo baixo."},"answer":"C","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (1).pdf","sourceLabel":"Bradiarritmias e Síncope","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Síncope recorrente em pessoa com mais de 40 anos e pausa espontânea documentada prolongada indica cardioinibição clinicamente relevante; o marcapasso pode reduzir recorrências quando há correlação sintoma-bradicardia.\nPor que as outras estão erradas:\nA: Uso de amiodarona exige primeiro avaliar reversibilidade e necessidade do fármaco; não define sozinho indicação classe I.\nB: Wenckebach durante o sono pode ser vagal e fisiológico, sem indicação de marcapasso.\nD: Marcapasso não é indicação rotineira em miocardiopatia hipertrófica com baixo gradiente.\nPonto de prova: Indicações formais de marcapasso em síncope reflexa/bradiarritmia.\nFlashcard sugerido:\nPergunta: Quando a pausa documentada em síncope recorrente pode indicar marcapasso?\nResposta: Quando é prolongada, espontânea e correlacionada aos sintomas, especialmente em >40 anos.\n\nPérola:\nMarcapasso exige correlação clínica, não apenas um ECG alterado.\n\nArmadilha:\nImplantar dispositivo em bloqueio vagal noturno assintomático.\n\n--------------------------------------------------------------------------------","tags":["Clínica Médica","Medicina Interna","Conhecimento Conceitual","Paciente Adulto","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags.txt","globalNumber":47},{"id":"b12-bradiarritmias-sincope-q06","number":6,"collectionBlock":12,"documentBlock":13,"area":"Clínica Médica","topic":"Bradiarritmias e Síncope","stem":"Paciente, do sexo feminino, 42 anos de idade, tem hipotireoidismo e diabetes melito do tipo 2. Faz uso de levotiroxina 100 μg/ dia e metformina 850 mg duas vezes ao dia. Comparece no departamento de emergência por desmaio. A anamnese realizada com a paciente e sua esposa identificou que houve sudorese e sensação intensa de calor 5 minutos após o término do treino na academia, quando, em seguida, avisou que estava se sentindo mal e perdeu consciência com queda amparada pela esposa. Retornou à consciência após cerca de um minuto, dialogando normalmente e com sensação de cansaço. Ao exame físico, apresentou PA de 106 × 64 mmHg, FC de 58 bpm, FR de 19 ipm, saturação de oxigênio 97%; exame cardiopulmonar e abdome sem alterações; extremidades sem edema e com perfusão adequada. Foi realizado o seguinte eletrocardiograma: Com base nas informações apresentadas, assinale a alternativa que indica o diagnóstico correto:","options":{"A":"Hipoglicemia.","B":"Crise epiléptica.","C":"Síncope vasovagal.","D":"Síndrome de Wolff-Parkinson-White."},"answer":"C","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (1).pdf","sourceLabel":"Bradiarritmias e Síncope","images":["data:image/webp;base64,"],"comment":"Análise:\nCorreta: C.\nPor que está certa: Pródromos autonômicos, desencadeante pós-exercício, palidez, perda breve de consciência e recuperação rápida sem confusão são típicos de síncope vasovagal.\nPor que as outras estão erradas:\nA: Metformina isolada raramente causa hipoglicemia; não há glicemia baixa documentada.\nB: Crise epiléptica costuma ter fase tônica/clônica sustentada, mordedura lateral de língua e confusão pós-ictal.\nD: WPW depende de pré-excitação no ECG e costuma causar taquicardia, não o padrão clínico reflexo descrito.\nPonto de prova: Características clínicas da síncope vasovagal.\nFlashcard sugerido:\nPergunta: Quais pródromos sugerem síncope vasovagal?\nResposta: Calor, sudorese, náusea, turvação visual e sensação de desmaio.\n\nPérola:\nPródromo autonômico + recuperação rápida = vasovagal.\n\nArmadilha:\nTomar qualquer perda de consciência em diabético como hipoglicemia.\n\n--------------------------------------------------------------------------------","tags":["Cirurgia","Trauma","Hipotireoidismo","Diabetes Mellitus","Raciocínio Diagnóstico","Urgência e Emergência"],"tagSource":"Tags.txt","globalNumber":64},{"id":"b12-bradiarritmias-sincope-q07","number":7,"collectionBlock":12,"documentBlock":13,"area":"Clínica Médica","topic":"Bradiarritmias e Síncope","stem":"Um paciente de 34 anos procurou um ambulatório para realização de um check up médico. Negou quaisquer sintomas ou doenças prévias. Ao exame, a pressão arterial era de 132 por 82 mmHg e a frequência cardíaca, de 68 batimentos por minutos. Foi observada uma irregularidade no ritmo cardíaco, sugerindo a presença de aproximadamente 4 extrassístoles por minuto. O restante do exame físico foi sem alterações. Foi solicitado eletrocardiograma, em que foi evidenciada a presença de alguns extrassístoles ventriculares. Essas alterações foram confirmadas em Holter de 24 horas, em que foi observada uma baixa incidência de extrassístoles ventriculares, sem arritmia supraventricular. O paciente realizou, também, um ecocardiograma, que estava dentro da normalidade, mas ficou preocupado ao terem sido detectadas essas alterações no ritmo cardíaco apesar de estar assintomático. A orientação mais adequada nesse caso é:","options":{"A":"Indicar uma avaliação especializada, visando à realização de um estudo eletrofisiológico.","B":"Tranquilizar o paciente e sugerir que evite um consumo elevado de estimulantes como cafeína.","C":"Solicitar ressonância magnética cardíaca para investigação de causas para arritmia ventricular.","D":"Solicitar cintilografia miocárdica visando a afastar isquemia miocárdica como causadora do quadro do paciente.","E":"Iniciar o verapamil em dose plena e solicitar novo Holter de 24 horas após dois meses de tratamento com essa medicação."},"answer":"B","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (1).pdf","sourceLabel":"Bradiarritmias e Síncope","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Extrassístoles ventriculares infrequentes em paciente assintomático, com ecocardiograma normal e sem arritmia complexa, têm prognóstico benigno. Orienta-se tranquilização e redução de estimulantes.\nPor que as outras estão erradas:\nA: Estudo eletrofisiológico não é indicado em ectopia ventricular de baixa carga e coração estruturalmente normal.\nC: RM é reservada quando há suspeita de cardiopatia estrutural oculta ou arritmia complexa.\nD: Cintilografia não é necessária sem sintomas ou risco isquêmico relevante.\nE: Tratamento farmacológico não é indicado em assintomático; verapamil não é terapia padrão indiscriminada.\nPonto de prova: Manejo de extrassístoles ventriculares benignas.\nFlashcard sugerido:\nPergunta: Como conduzir extrassístoles ventriculares infrequentes em coração normal?\nResposta: Reassegurar, evitar estimulantes e acompanhar conforme clínica.\n\nPérola:\nBaixa carga + sem sintomas + coração normal = geralmente benigno.\n\nArmadilha:\nMedicalizar achado incidental benigno.\n\n--------------------------------------------------------------------------------","tags":["Clínica Médica","Cardiologia","Epidemiologia","Arritmias","Interpretação de Exames","Paciente Adulto"],"tagSource":"Tags.txt","globalNumber":69},{"id":"b12-bradiarritmias-sincope-q08","number":8,"collectionBlock":12,"documentBlock":13,"area":"Clínica Médica","topic":"Bradiarritmias e Síncope","stem":"Uma estudante universitária de 23 anos marcou avaliação clínica pois vinha apresentando episódios recorrentes de perda de consciência desde a adolescência, geralmente em situações de estresse emocional intenso ou durante prolongada permanência em pé em ambientes quentes. Ela descreveu que, momentos antes de perder a consciência, sentia tontura, visão turva, suor frio e náuseas. Em um dos episódios mais recentes, enquanto estava em pé em uma fila, começou a sentir esses sintomas e desmaiou, recuperando a consciência em menos de 2 minutos. Negou doenças prévias e afirmou que se sentia saudável. Durante a consulta médica, não foram encontradas alterações no exame físico. A paciente levou Holter de 24 horas, eletrocardiograma e ecocardiograma, que estavam dentro da normalidade. A paciente queria saber o que fazer ao ter a sensação de desmaio. Nesse contexto de um quadro sugestivo de síncope vasovagal, além de sugerir que ela deite no chão ou outro tipo de superfície quando sentir os pródromos de síncope, o médico deve orientá-la a:","options":{"A":"Balançar-se alternando o peso de um pé para o outro.","B":"Ficar o máximo de tempo com os braços cruzados, respirando fundo e soltando o ar.","C":"Ingerir rapidamente uma bebida energética ou um alimento que seja fonte de carboidrato.","D":"Elevar os braços acima da cabeça e mantê-los nessa posição até que os sintomas melhorem.","E":"Fazer manobras de contrapressão isométricas, como apertar as mãos e cruzar as pernas fazendo contração bilateralmente."},"answer":"E","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (1).pdf","sourceLabel":"Bradiarritmias e Síncope","images":[],"comment":"Análise:\nCorreta: E.\nPor que está certa: Manobras de contrapressão isométrica aumentam retorno venoso e resistência vascular, podendo abortar síncope reflexa quando iniciadas nos pródromos.\nPor que as outras estão erradas:\nA: Balançar o peso é menos eficaz e pode aumentar risco de queda.\nB: Cruzar braços sem contração muscular direcionada não oferece a mesma resposta hemodinâmica.\nC: Bebida energética não age rapidamente e pode piorar palpitações.\nD: Elevar braços pode reduzir retorno venoso e não é recomendação padrão.\nPonto de prova: Medidas físicas na síncope vasovagal.\nFlashcard sugerido:\nPergunta: Quais manobras podem abortar síncope vasovagal iminente?\nResposta: Cruzar e contrair as pernas, agachar ou apertar as mãos/braços isometricamente.\n\nPérola:\nContrair grandes grupos musculares eleva pressão arterial.\n\nArmadilha:\nOrientar a pessoa a permanecer em pé durante os pródromos.\n\n--------------------------------------------------------------------------------","tags":["Clínica Médica","Cardiologia","Eletrocardiograma","Interpretação de Exames","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags.txt","globalNumber":70},{"id":"b12-bradiarritmias-sincope-q09","number":9,"collectionBlock":12,"documentBlock":13,"area":"Clínica Médica","topic":"Bradiarritmias e Síncope","stem":"Homem de 62 anos vai a uma unidade de pronto atendimento (UPA) referindo cansaço e tontura ao se levantar há 2 semanas. Nega outras queixas, comorbidades ou cirurgias prévias, assim como o uso de medicamentos. Ao exame físico, apresenta-se corado, hidratado, lúcido e orientado em tempo e espaço; pressão arterial de 120 × 70 mmHg; frequência cardíaca de 45 bpm; saturação de O2 de 96% em ar ambiente; ritmo cardíaco regular, sem turgência jugular; murmúrio vesicular fisiológico, sem ruídos acessórios; e enchimento capilar de 2 segundos. Diante disso, o médico solicita um eletrocardiograma de 12 derivações: A partir desse quadro clínico e da interpretação do eletrocardiograma, a conduta adequada consiste em:","options":{"A":"Conceder alta médica e encaminhar o paciente ao ambulatório especializado de cardiologia.","B":"Monitorizar o paciente, solicitar marcapasso transcutâneo e aguardar avaliação do cardiologista.","C":"Monitorizar o paciente, administrar atropina 1 mg (IV) e implantar marcapasso transcutâneo.","D":"Monitorizar o paciente, administrar atropina 1 mg (IV) e iniciar uso de dopamina 5 mcg/kg/min."},"answer":"B","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (1).pdf","sourceLabel":"Bradiarritmias e Síncope","images":["data:image/webp;base64,"],"comment":"Análise:\nCorreta: B.\nPor que está certa: Bradicardia sintomática por provável bloqueio de alto grau exige monitorização e disponibilidade imediata de estimulação transcutânea; atropina pode ser pouco eficaz em bloqueios infranodais. A banca priorizou preparar o marcapasso e avaliação especializada.\nPor que as outras estão erradas:\nA: Alta é inadequada diante de sintomas e FC 45 com alteração de condução.\nC: Atropina pode ser tentada se houver instabilidade, mas implante transcutâneo não deve ser descrito como definitivo; a alternativa combina intervenções sem necessidade evidente de atropina imediata.\nD: Dopamina é reservada a bradicardia com comprometimento hemodinâmico quando atropina falha ou pacing não está disponível.\nPonto de prova: Abordagem de bloqueio AV de alto grau em paciente sintomático.\nFlashcard sugerido:\nPergunta: Qual medida deve estar prontamente disponível no bloqueio AV sintomático?\nResposta: Marcapasso transcutâneo e monitorização.\n\nPérola:\nBloqueio infranodal responde mal à atropina.\n\nArmadilha:\nDar alta porque a pressão está normal no momento.\n\n--------------------------------------------------------------------------------","tags":["Clínica Médica","Cardiologia","Eletrocardiograma","Conduta Terapêutica","Urgência e Emergência","Avaliação Clínica"],"tagSource":"Tags.txt","globalNumber":80},{"id":"b12-bradiarritmias-sincope-q10","number":10,"collectionBlock":12,"documentBlock":13,"area":"Clínica Médica","topic":"Bradiarritmias e Síncope","stem":"Mulher, 19 anos de idade, procurou atendimento por ter apresentado perda súbita de consciência. Refere ter sentido tontura antes da perda de consciência e que ficou desacordada poucos segundos. Nega liberação esfincteriana e paralisias. Testemunha nega que tenha havido movimentos involuntários durante o período de perda de consciência. Ausência de sequelas motoras ao exame físico. Marque a principal hipótese diagnóstica para esse quadro entre as listadas a seguir:","options":{"A":"Vertigem.","B":"Epilepsia.","C":"Neurocardiogênica.","D":"Isquemia cerebral."},"answer":"C","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (1).pdf","sourceLabel":"Bradiarritmias e Síncope","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Perda breve de consciência, com tontura prévia, ausência de movimentos tônico-clônicos, déficit focal ou fase pós-ictal, é compatível com síncope neurocardiogênica/reflexa.\nPor que as outras estão erradas:\nA: Vertigem é ilusão de movimento e não causa tipicamente perda completa de consciência.\nB: Epilepsia costuma apresentar manifestações motoras ou pós-ictais, embora nem sempre; o quadro descrito favorece síncope.\nD: Isquemia cerebral focal raramente causa perda isolada de consciência e deixaria sinais neurológicos ou contexto vascular.\nPonto de prova: Diferenciação entre síncope, vertigem e crise epiléptica.\nFlashcard sugerido:\nPergunta: Qual diagnóstico é sugerido por perda breve de consciência com recuperação completa e sem pós-ictal?\nResposta: Síncope neurocardiogênica.\n\nPérola:\nSíncope recupera rápido; crise costuma deixar pós-ictal.\n\nArmadilha:\nChamar tontura com desmaio de vertigem.\n\n--------------------------------------------------------------------------------","tags":["Clínica Médica","Medicina Interna","Raciocínio Diagnóstico","Paciente Adulto","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags.txt","globalNumber":82},{"id":"b12-bradiarritmias-sincope-q11","number":11,"collectionBlock":12,"documentBlock":13,"area":"Clínica Médica","topic":"Bradiarritmias e Síncope","stem":"Um paciente idoso de 78 anos, em uso de enalapril 20 mg/dia, anlodipino 10 mg/dia e hidroclorotiazida 25mg/dia, apresenta um episódio súbito de síncope enquanto estava sentado, precedido de palpitações e sem reflexos de defesa, resultando em queda ao solo com fratura facial. O exame físico e neurológico não revela alterações significativas. Qual deve ser a conduta adequada?","options":{"A":"A hipótese principal é de síncope convulsiva e a conduta deve ser iniciar tratamento com anticonvulsivantes.","B":"A hipótese principal é de síncope neuromediada e a conduta deve ser indicar tilt test.","C":"A hipótese principal é de síncope por hipovolemia e a conduta deve ser retirar diuréticos e orientar ingestão hídrica adequada.","D":"A hipótese principal é de síncope cardiogênica e a conduta deve ser internar o paciente para investigação."},"answer":"D","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (1).pdf","sourceLabel":"Bradiarritmias e Síncope","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Há dois miomas sintomáticos com desejo de preservação uterina: FIGO 1, acessível por histeroscopia, e híbrido FIGO 2-5, de grande volume, melhor abordado por laparoscopia.\nPor que as outras estão erradas:\nA: Histerectomia elimina fertilidade e é inadequada em mulher jovem sem menção de prole definida.\nC: Histerectomia subtotal também elimina fertilidade.\nD: Contraceptivos podem reduzir sangramento, mas não tratam adequadamente o efeito de massa nem o mioma grande com impacto urinário.\nPonto de prova: Escolha da via de miomectomia conforme classificação FIGO.\nFlashcard sugerido:\nPergunta: Como tratar miomas FIGO 1 e FIGO 2-5 sintomáticos em mulher que deseja preservar o útero?\nResposta: Miomectomia histeroscópica e laparoscópica, respectivamente.\n\nPérola:\nA localização do mioma determina a via cirúrgica.\n\nArmadilha:\nEscolher uma única via para miomas em compartimentos anatômicos distintos.\n\n--------------------------------------------------------------------------------"},{"id":"b12-bradiarritmias-sincope-q12","number":12,"collectionBlock":12,"documentBlock":13,"area":"Clínica Médica","topic":"Bradiarritmias e Síncope","stem":"Mulher, de 32 anos de idade, iniciou quadro de dispneia súbita seguida de síncope, que ocorreu enquanto estava em casa cozinhando há cerca de 30 minutos. No momento, refere manter dispneia em repouso e palpitação. É previamente hígida e não usa medicações contínuas. No exame físico apresentava pressão arterial de 112 × 78 mmHg, frequência cardíaca de 126 bpm, temperatura axilar de 35,3ºC, frequência respiratória de 34irpm e saturação de oxigênio inicial de 86% em ar ambiente, que subiu para 95% após administração de oxigênio 3 L/min, via cateter nasal. Foi feita uma angiotomografia de tórax, que evidenciou um trombo na artéria pulmonar direita. Também foi feito um a ecocardiograma point-of-care, que mostrou sobrecarga ventricular direita e dosagem de troponina ultrassensível de 1567 ng/L. Qual é a classificação de risco e a conduta inicial que deve ser adotada neste momento?","options":{"A":"Baixo risco. Anticoagulação com enoxaparina.","B":"Intermediário a alto risco. Anticoagulação com apixabana.","C":"Alto risco. Trombólise intravenosa.","D":"Muito alto risco. Trombólise intravenosa."},"answer":"B","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (1).pdf","sourceLabel":"Bradiarritmias e Síncope","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: Mioma totalmente intracavitário e pediculado é FIGO 0. A miomectomia histeroscópica é o tratamento conservador de escolha, sobretudo com sangramento e infertilidade.\nPor que as outras estão erradas:\nB: Histerectomia é desproporcional e elimina fertilidade.\nC: FIGO 8 corresponde a localizações não usuais, como cervical ou parasitária, não a mioma intracavitário.\nD: Embora a via histeroscópica seja correta, a classificação FIGO 8 está errada.\nPonto de prova: Classificação FIGO dos miomas submucosos.\nFlashcard sugerido:\nPergunta: Como se classifica e trata um mioma totalmente intracavitário pediculado?\nResposta: FIGO 0; miomectomia histeroscópica.\n\nPérola:\nFIGO 0 flutua na cavidade, preso apenas por pedículo.\n\nArmadilha:\nConfundir FIGO 0 com FIGO 8.\n\n--------------------------------------------------------------------------------"},{"id":"b12-bradiarritmias-sincope-q13","number":13,"collectionBlock":12,"documentBlock":13,"area":"Clínica Médica","topic":"Bradiarritmias e Síncope","stem":"Homem de 68 anos, previamente hipertenso, comparece ao pronto socorro após episódio de perda súbita da consciência durante caminhada. O evento ocorreu sem pródromos, com recuperação espontânea em menos de 1 minuto. A esposa nega movimentos tônico-clônicos, mordedura de língua ou incontinência esfincteriana. Exame físico: PA: 112/70 mmHg FC: 56 bpm Ausculta cardíaca: sopro sistólico em foco aórtico irradiado para carótidas ECG: bloqueio de ramo esquerdo. Diante desse quadro, qual deve ser a conduta mais adequada?","options":{"A":"Acompanhamento ambulatorial com cardiologia, visto que o paciente já se encontra estável após o episódio e apresenta recuperação rápida da consciência.","B":"Internação hospitalar para investigação, considerando o risco elevado pela ausência de pródromos e achados compatíveis com cardiopatia estrutural.","C":"Realização de tilt test em momento oportuno, uma vez que causas reflexas são a principal etiologia para o quadro em pacientes idosos.","D":"Observação clínica em pronto-socorro e liberação posterior, caso não ocorram novos episódios ou instabilidade hemodinâmica","E":"Início de tratamento farmacológico para controle de sintomas, interpretando o episódio como de provável origem psicogênica."},"answer":"B","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (1).pdf","sourceLabel":"Bradiarritmias e Síncope","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: A supressão do ciclo e a indução de amenorreia com progestagênios, contraceptivos combinados contínuos ou outras terapias hormonais reduzem estímulo estrogênico e dor da endometriose.\nPor que as outras estão erradas:\nA: O diagnóstico pode ser clínico e por imagem; laparoscopia não é obrigatória, e RM não é padrão-ouro universal.\nB: A intensidade da dor não se correlaciona diretamente com número ou extensão das lesões.\nC: CA-125 não mede gravidade nem é teste diagnóstico específico.\nE: Endometrioma não constitui indicação cirúrgica absoluta; a decisão depende de tamanho, sintomas, fertilidade e suspeita de malignidade.\nPonto de prova: Princípios de tratamento clínico da endometriose.\nFlashcard sugerido:\nPergunta: Qual é o objetivo da terapia hormonal na endometriose?\nResposta: Suprimir ovulação/menstruação e induzir amenorreia para controlar sintomas.\n\nPérola:\nA extensão da endometriose não prediz a intensidade da dor.\n\nArmadilha:\nTratar todo endometrioma cirurgicamente.\n\n--------------------------------------------------------------------------------"},{"id":"b12-bradiarritmias-sincope-q14","number":14,"collectionBlock":12,"documentBlock":13,"area":"Clínica Médica","topic":"Bradiarritmias e Síncope","stem":"Homem de 46 anos apresenta episódios de perda de consciência. Após suspeita clínica de síncope, assinale a alternativa que contém o fator associado ao quadro que levaria à conclusão de tratar-se de síncope de alto risco:","options":{"A":"Ser desencadeado por estresse emocional.","B":"Ocorrer após tosse ou espirros.","C":"Ocorrer na posição supina.","D":"Ocorrer conjuntamente com defecação."},"answer":"C","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (1).pdf","sourceLabel":"Bradiarritmias e Síncope","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: A taquicardia atrial geralmente apresenta QRS estreito e ritmo regular, salvo condução AV variável.\nPor que as outras estão erradas:\nA: Fibrilação atrial é irregularmente irregular.\nB: Torsades é taquicardia ventricular polimórfica de QRS largo.\nD: Taquicardia antidrômica conduz pelo feixe acessório no sentido anterógrado e costuma ter QRS largo.\nE: Flutter com bloqueio AV variável produz resposta ventricular irregular.\nPonto de prova: Classificação de taquiarritmias por largura do QRS e regularidade.\nFlashcard sugerido:\nPergunta: Qual taquiarritmia é tipicamente regular e de QRS estreito?\nResposta: Taquicardia atrial.\n\nPérola:\nQRS estreito sugere origem supraventricular, mas a regularidade diferencia os ritmos.\n\nArmadilha:\nConfundir flutter com condução fixa e flutter com bloqueio variável.\n\n--------------------------------------------------------------------------------"},{"id":"b12-bradiarritmias-sincope-q15","number":15,"collectionBlock":12,"documentBlock":13,"area":"Clínica Médica","topic":"Bradiarritmias e Síncope","stem":"Mulher, 56a, é admitida com história de dor precordial persistente há 1 hora. Relata episódio de síncope ocorrido há aproximadamente 15 minutos. No momento, refere mal-estar geral e sudorese difusa. Antecedentes: diabetes melito e hipertensão. Medicamentos em uso: valsartana, metformina e rosuvastatina. Exame físico: consciente, orientada, taquipneica, PA = 78 × 47 mmHg. Realizado ECG: EM RELAÇÃO A ESTE CASO, É CORRETO AFIRMAR:","options":{"A":"O tratamento indicado é aspirina, clopidogrel, trombólise e nitrato.","B":"O uso de atropina está contraindicado.","C":"O tratamento de escolha é heparina, aspirina e clopidogrel.","D":"A necessidade de implante de marcapasso definitivo é pouco frequente."},"answer":"D","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (1).pdf","sourceLabel":"Bradiarritmias e Síncope","images":["data:image/webp;base64,"],"comment":"Análise:\nCorreta: C.\nPor que está certa: Abertura controlada do trato gastrointestinal em cirurgia eletiva, sem contaminação anormal, classifica a operação como potencialmente contaminada ou limpa-contaminada.\nPor que as outras estão erradas:\nA: Cirurgia limpa não entra em tratos respiratório, digestivo, genital ou urinário.\nB: Contaminada envolve falha importante de técnica, extravasamento grosseiro ou inflamação aguda não purulenta.\nD: Suja pressupõe infecção estabelecida, víscera perfurada ou tecido desvitalizado.\nE: Infectada equivale à categoria suja/infectada e não se aplica ao acesso controlado.\nPonto de prova: Classificação das feridas operatórias por grau de contaminação.\nFlashcard sugerido:\nPergunta: Como classificar cirurgia gástrica eletiva com abertura controlada do estômago?\nResposta: Potencialmente contaminada/limpa-contaminada.\n\nPérola:\nEntrada controlada em víscera colonizada não torna a cirurgia contaminada.\n\nArmadilha:\nAssociar qualquer abertura gastrointestinal a cirurgia contaminada.\n\n--------------------------------------------------------------------------------"},{"id":"b12-bradiarritmias-sincope-q16","number":16,"collectionBlock":12,"documentBlock":13,"area":"Clínica Médica","topic":"Bradiarritmias e Síncope","stem":"Paciente feminina, 80 anos, com histórico de diabetes mellitus e hipertensão, dá entrada no pronto-socorro apresentando início há 4 horas de sudorese difusa acompanhada de confusão mental. Ao exame apresenta pressão arterial de 70/60 mmHg. Frequência cardíaca de 40 bpm; frequência respiratória de 18 irm e saturação periférica de oxigênio de 94% em ar ambiente. Eletrocardiograma da admissão: Como deve ser realizado o manejo inicial desse paciente?","options":{"A":"Utilizar imediatamente o marcapasso transcutâneo por se tratar de um bloqueio atrioventricular de segundo grau.","B":"Considerar apenas a administração de atropina na dose total de 3 mg endovenosa.","C":"Administrar atropina na dose inicial de 0,5 mg endovenosa e instalar marcapasso transcutâneo.","D":"Considerar inicialmente apenas a infusão contínua endovenosa de dopamina."},"answer":"C","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (1).pdf","sourceLabel":"Bradiarritmias e Síncope","images":["data:image/webp;base64,"],"comment":"Análise:\nCorreta: E.\nPor que está certa: Taquiarritmia associada a hipotensão grave e dor torácica caracteriza instabilidade hemodinâmica. A conduta imediata é cardioversão elétrica sincronizada, independentemente do mecanismo específico do ritmo.\nPor que as outras estão erradas:\nA: Manobras vagais são reservadas a taquicardia supraventricular regular e estável.\nB: Adenosina pode ser usada em taquicardia regular de QRS estreito estável; não deve atrasar cardioversão no instável.\nC: Amiodarona é opção em alguns ritmos estáveis ou após cardioversão, mas tem início mais lento.\nD: Deslanosídeo não é terapia de emergência para taquiarritmia instável.\nPonto de prova: Reconhecimento de instabilidade em taquiarritmias.\nFlashcard sugerido:\nPergunta: Qual a conduta na taquiarritmia com hipotensão e dor torácica?\nResposta: Cardioversão elétrica sincronizada.\n\nPérola:\nInstabilidade manda mais que o nome da arritmia.\n\nArmadilha:\nTentar tratamento farmacológico enquanto o paciente está em choque.\n\n--------------------------------------------------------------------------------"},{"id":"b12-bradiarritmias-sincope-q17","number":17,"collectionBlock":12,"documentBlock":13,"area":"Clínica Médica","topic":"Bradiarritmias e Síncope","stem":"Um morador de rua de 66 anos é levado ao setor de emergência após queda num lago gelado. Ele tem história de etilismo. Sua PA é de 80 × 48 mmHg, FC de 46 BPM, FR de 10 IRMP e temperatura de 32° C. ECG revela bradicardia sinusal e presença de onda J. Assinale a alternativa que contém o conjunto de medidas recomendadas para esse caso:","options":{"A":"Marca-passo transcutâneo, infusão de salina isotônica aquecida e tiamina.","B":"Marca-passo transvenoso, infusão de salina isotônica aquecida e tiamina","C":"Infusão de salina isotônica aquecida, tiamina e monitorização eletrocardiográfica contínua.","D":"Marca-passo transvenoso e infusão de salina isotônica aquecida e monitorização eletrocardiográfica contínua.","E":"Marca-passo transvenoso, infusão de salina isotônica aquecida, tiamina e bicarbonato de sódio a 8,4%"},"answer":"C","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (1).pdf","sourceLabel":"Bradiarritmias e Síncope","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: Estenose ureteral, hidronefrose, endometrioma volumoso e dor refratária configuram doença profunda com comprometimento orgânico e indicação cirúrgica terapêutica por equipe experiente.\nPor que as outras estão erradas:\nB: Biópsia isolada não resolve obstrução ureteral nem a dor e não é o objetivo da laparoscopia nesse contexto.\nC: Fertilização in vitro não corrige a hidronefrose nem o risco de dano renal.\nD: Inseminação intrauterina não trata doença profunda nem obstrução urinária.\nPonto de prova: Indicações de cirurgia na endometriose profunda.\nFlashcard sugerido:\nPergunta: Quando a endometriose profunda exige cirurgia?\nResposta: Quando há obstrução de órgão, hidronefrose, massa relevante ou dor refratária.\n\nPérola:\nEndometriose com hidronefrose é doença com risco funcional.\n\nArmadilha:\nPriorizar fertilidade sem tratar ameaça ao ureter e ao rim.\n\n--------------------------------------------------------------------------------"},{"id":"b12-bradiarritmias-sincope-q18","number":18,"collectionBlock":12,"documentBlock":13,"area":"Clínica Médica","topic":"Bradiarritmias e Síncope","stem":"Paciente feminina, 39 anos, com cirrose de etiologia alcoólica Child-Pugh A5 e transtorno de ansiedade generalizada, chega ao pronto-socorro após episódio de desmaio em sua casa. A anamnese realizada em conjunto com sua filha identificou que a paciente referia batedeira no peito e que perdeu a consciência após subir as escadas, sendo amparada imediatamente pela filha, sem apresentar qualquer trauma. Apresentou incontinência urinária e alguns breves movimentos mioclônicos nos braços e pernas, permanecendo nesse período flácida, pálida, de olhos abertos, com desvio do olhar para cima. Retornou à consciência após cerca de 20 segundos, dialogando normalmente e com sensação de cansaço e mal-estar generalizado. Relata libação alcoólica nos últimos dois dias do final de semana. Nega episódios semelhantes no passado. Nega dor torácica ou dispneia no momento. Exame físico: regular estado geral, consciente e orientada, PA = 130/90 mmHg, FC = 120 bpm, FR = 20 irpm, oximetria de pulso = 96% em ar ambiente. Ausculta cardíaca duas bulhas arrítmicas normofonéticas. Ausculta pulmonar sem alterações. Exame neurológico sem alterações evidentes. Eletrocardiograma realizado na admissão está na figura a seguir. Qual o diagnóstico correto mais provável: Fonte: https://litfl.com/","options":{"A":"Crise convulsiva.","B":"Crise não epiléptica psicogênica.","C":"Síncope vasovagal.","D":"Síncope cardiogênica."},"answer":"D","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (1).pdf","sourceLabel":"Bradiarritmias e Síncope","images":["data:image/webp;base64,"],"comment":"Análise:\nCorreta: D.\nPor que está certa: Palpitações antes do evento, esforço como gatilho, ritmo arrítmico, perda abrupta, palidez e recuperação rápida favorecem síncope cardiogênica. Mioclonias breves e incontinência podem ocorrer em síncope por hipóxia cerebral.\nPor que as outras estão erradas:\nA: Movimentos breves não definem epilepsia; ausência de pós-ictal e recuperação em segundos são contra crise convulsiva.\nB: Não há elementos de evento psicogênico prolongado ou semiologia inconsistente.\nC: Vasovagal costuma ter pródromos autonômicos mais claros e gatilhos típicos; aqui há palpitação e arritmia.\nPonto de prova: Diferenciação entre síncope convulsiva e epilepsia.\nFlashcard sugerido:\nPergunta: Mioclonias breves podem ocorrer na síncope?\nResposta: Sim, por hipoperfusão cerebral, sem significar epilepsia.\n\nPérola:\nPalpitação antes do desmaio é alerta para causa cardíaca.\n\nArmadilha:\nUsar incontinência urinária como prova de epilepsia.\n\n--------------------------------------------------------------------------------","tags":["Clínica Médica","Gastroenterologia","Cirrose","Ansiedade","Raciocínio Diagnóstico","Urgência e Emergência"],"tagSource":"Tags.txt","globalNumber":98},{"id":"b12-taquiarritmias-acl-bls-q01","number":1,"collectionBlock":12,"documentBlock":13,"area":"Clínica Médica","topic":"Taquiarritmias e ACL/BLS","stem":"Torsades de pointes configura uma taquicardia ventricular polimórfica em pacientes com intervalo QT longo. Os complexos QRS parecem se contorcer na linha de base do ECG. Qual eletrólito deve ser reposto na parada cardiorespiratória em que se suspeita de torsades de pointes?","options":{"A":"Cálcio.","B":"Sódio.","C":"Magnésio.","D":"Fósforo.","E":"Potássio."},"answer":"C","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (2).pdf","sourceLabel":"Taquiarritmias e ACL/BLS","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: O sulfato de magnésio é o tratamento de escolha para torsades de pointes, inclusive quando a magnesemia é normal, pois estabiliza a repolarização e reduz pós-despolarizações precoces.\nPor que as outras estão erradas:\nA: Cálcio é indicado em hipercalemia com alteração eletrocardiográfica, hipocalcemia grave e intoxicação por bloqueador de canal de cálcio.\nB: Sódio, geralmente como bicarbonato, é usado em situações específicas, como toxicidade por tricíclicos.\nD: Fósforo não trata torsades.\nE: Potássio deve ser corrigido se baixo, mas o fármaco imediato clássico é magnésio.\nPonto de prova: Tratamento específico da torsades de pointes.\nFlashcard sugerido:\nPergunta: Qual eletrólito deve ser administrado na torsades de pointes?\nResposta: Magnésio.\n\nPérola:\nTorsades = QT longo + magnésio.\n\nArmadilha:\nEscolher potássio apenas porque hipocalemia também prolonga o QT.\n\n--------------------------------------------------------------------------------","tags":["Clínica Médica","Cardiologia","Torsades de Pointes","Parada Cardiorrespiratória","Interpretação de Exames","Paciente Adulto"],"tagSource":"Tags.txt","globalNumber":6},{"id":"b12-taquiarritmias-acl-bls-q02","number":2,"collectionBlock":12,"documentBlock":13,"area":"Clínica Médica","topic":"Taquiarritmias e ACL/BLS","stem":"Qual das seguintes taquiarritmias apresenta complexo QRS estreito e regular?","options":{"A":"Fibrilação atrial.","B":"Torsades de Pointes.","C":"Taquicardia atrial.","D":"Taquicardia de movimento circular antidrômica.","E":"Flutter atrial com bloqueio AV variado."},"answer":"C","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (2).pdf","sourceLabel":"Taquiarritmias e ACL/BLS","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: A taquicardia atrial geralmente apresenta QRS estreito e ritmo regular, salvo condução AV variável.\nPor que as outras estão erradas:\nA: Fibrilação atrial é irregularmente irregular.\nB: Torsades é taquicardia ventricular polimórfica de QRS largo.\nD: Taquicardia antidrômica conduz pelo feixe acessório no sentido anterógrado e costuma ter QRS largo.\nE: Flutter com bloqueio AV variável produz resposta ventricular irregular.\nPonto de prova: Classificação de taquiarritmias por largura do QRS e regularidade.\nFlashcard sugerido:\nPergunta: Qual taquiarritmia é tipicamente regular e de QRS estreito?\nResposta: Taquicardia atrial.\n\nPérola:\nQRS estreito sugere origem supraventricular, mas a regularidade diferencia os ritmos.\n\nArmadilha:\nConfundir flutter com condução fixa e flutter com bloqueio variável.\n\n--------------------------------------------------------------------------------","tags":["Clínica Médica","Medicina Interna","Conhecimento Conceitual","Paciente Adulto","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags.txt","globalNumber":14},{"id":"b12-taquiarritmias-acl-bls-q03","number":3,"collectionBlock":12,"documentBlock":13,"area":"Clínica Médica","topic":"Taquiarritmias e ACL/BLS","stem":"Um homem de 57 anos procura atendimento médico com queixa de palpitações e dor torácica tipo aperto, de início há 30 minutos. Apresenta hipotensão (PA 60 × 40mmHg). Após avaliar o ritmo mostrado a seguir, qual é a conduta mais adequada?","options":{"A":"Manobra vagal.","B":"Adenosina 6mg EV em bólus.","C":"Amiodarona 150mg EV em 30 minutos.","D":"Deslanosídeo 0,8mg EV em bólus.","E":"Cardioversão elétrica sincronizada."},"answer":"E","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (2).pdf","sourceLabel":"Taquiarritmias e ACL/BLS","images":[],"comment":"Análise:\nCorreta: E.\nPor que está certa: Taquiarritmia associada a hipotensão grave e dor torácica caracteriza instabilidade hemodinâmica. A conduta imediata é cardioversão elétrica sincronizada, independentemente do mecanismo específico do ritmo.\nPor que as outras estão erradas:\nA: Manobras vagais são reservadas a taquicardia supraventricular regular e estável.\nB: Adenosina pode ser usada em taquicardia regular de QRS estreito estável; não deve atrasar cardioversão no instável.\nC: Amiodarona é opção em alguns ritmos estáveis ou após cardioversão, mas tem início mais lento.\nD: Deslanosídeo não é terapia de emergência para taquiarritmia instável.\nPonto de prova: Reconhecimento de instabilidade em taquiarritmias.\nFlashcard sugerido:\nPergunta: Qual a conduta na taquiarritmia com hipotensão e dor torácica?\nResposta: Cardioversão elétrica sincronizada.\n\nPérola:\nInstabilidade manda mais que o nome da arritmia.\n\nArmadilha:\nTentar tratamento farmacológico enquanto o paciente está em choque.\n\n--------------------------------------------------------------------------------","tags":["Clínica Médica","Medicina Interna","Dor Torácica","Conduta Terapêutica","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags.txt","globalNumber":16},{"id":"b12-taquiarritmias-acl-bls-q04","number":4,"collectionBlock":12,"documentBlock":13,"area":"Clínica Médica","topic":"Taquiarritmias e ACL/BLS","stem":"Paciente de 32 anos, sexo feminino, deu entrada no pronto-socorro com quadro de taquicardia sem sinais de instabilidade. Estava normotensa, bem perfundida em periferia e eupneica. O ritmo no eletrocardiograma mostrava taquicardia regular com QRS estreito. Na suspeita de taquicardia supraventricular, qual medicamento/dose deve ser feito primeiro?","options":{"A":"Adenosina 6 mg.","B":"Adenosina 12 mg.","C":"Amiodarona 100 mg.","D":"Metoprolol 2 mg.","E":"Não há necessidade de medicamentos, apenas observar."},"answer":"A","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (2).pdf","sourceLabel":"Taquiarritmias e ACL/BLS","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: Na taquicardia supraventricular regular de QRS estreito e paciente estável, após manobras vagais, a primeira dose de adenosina é 6 mg EV em bólus rápido, seguida de flush.\nPor que as outras estão erradas:\nB: 12 mg é a segunda dose se 6 mg falhar.\nC: Amiodarona não é primeira escolha para TSV regular estreita.\nD: Metoprolol pode ser alternativa em casos selecionados, mas não é a sequência inicial clássica.\nE: Taquicardia sustentada sintomática requer intervenção, não observação isolada.\nPonto de prova: Algoritmo da taquicardia supraventricular estável.\nFlashcard sugerido:\nPergunta: Qual a primeira dose de adenosina na TSV regular de QRS estreito?\nResposta: 6 mg EV em bólus rápido.\n\nPérola:\nTSV estável: vagal, depois adenosina 6 mg.\n\nArmadilha:\nComeçar diretamente com 12 mg.\n\n--------------------------------------------------------------------------------","tags":["Clínica Médica","Cardiologia","Eletrocardiograma","Interpretação de Exames","Urgência e Emergência","Avaliação Clínica"],"tagSource":"Tags.txt","globalNumber":20},{"id":"b12-taquiarritmias-acl-bls-q05","number":5,"collectionBlock":12,"documentBlock":13,"area":"Clínica Médica","topic":"Taquiarritmias e ACL/BLS","stem":"Um paciente com 54 anos, em acompanhamento há 4 meses em função de cardiopatia isquêmica dilatada, foi admitido na unidade de emergência com queixas de súbitas palpitações e dispneia há cerca de 3 horas. O paciente nega dor precordial, informando ser portador, de longa data, de hipertensão arterial sistêmica e diabetes melito, em uso de carvedilol, enalapril, furosemida, espironolactona, dapagliflozina e insulina NPH (dose apenas noturna). Ao exame físico, o paciente se encontra em moderado desconforto respiratório, sudorese presente, pressão arterial de 80 × 62 mmHg, frequência cardíaca de 120 batimentos por minuto, com ritmo cardíaco irregular e com estertoração bolhosa bibasal. É realizado umeletrocardiograma (ECG) que evidencia padrão irregular, com existência de ondas f, sendo caracterizada fibrilação atrial paroxística com elevada resposta ventricular; fora a presença de ondas Q patológicas na parede anterior, não há distúrbios de ST-T no ECG. A médica que o atende opta por realizar um procedimento que exige prévia aplicação de sedação e analgesia ao paciente, passando a explicar- lhe o que será realizado em seguida. Diante da situação apresentada, o procedimento que será realizado no paciente é:","options":{"A":"Cineangiocoronariografia com angioplastia coronária.","B":"Cateterismo cardíaco com estudo eletrofisiológico.","C":"Implante de marca-passo provisório transvenoso.","D":"Aplicação de cardioversão elétrica."},"answer":"D","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (2).pdf","sourceLabel":"Taquiarritmias e ACL/BLS","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: Fibrilação atrial com hipotensão, congestão pulmonar e desconforto respiratório é instável; requer cardioversão elétrica sincronizada, com sedação se não houver atraso crítico.\nPor que as outras estão erradas:\nA: Não há evidência de síndrome coronariana aguda com indicação imediata de angioplastia.\nB: Estudo eletrofisiológico não é a intervenção aguda para FA instável.\nC: Marcapasso é para bradiarritmias, não FA com resposta ventricular rápida.\nPonto de prova: Conduta na fibrilação atrial hemodinamicamente instável.\nFlashcard sugerido:\nPergunta: Como tratar FA com hipotensão e edema pulmonar?\nResposta: Cardioversão elétrica sincronizada.\n\nPérola:\nFA instável não espera controle farmacológico de frequência.\n\nArmadilha:\nFocar no tempo de início da FA e esquecer a instabilidade.\n\n--------------------------------------------------------------------------------","tags":["Clínica Médica","Endocrinologia","Fibrilação Atrial","Insulina","Interpretação de Exames","Urgência e Emergência"],"tagSource":"Tags.txt","globalNumber":30},{"id":"b12-taquiarritmias-acl-bls-q06","number":6,"collectionBlock":12,"documentBlock":13,"area":"Clínica Médica","topic":"Taquiarritmias e ACL/BLS","stem":"Uma mulher de 58 anos apresentou-se à sala de emergência com palpitações intensas, dor torácica e dispneia. Ela relatou que as palpitações começaram repentinamente enquanto estava em repouso em casa. Não havia histórico prévio de arritmias. A seguir está o eletrocardiograma realizado: Sinais vitais: frequência cardíaca estimada em cerca de 150 bpm; pressão arterial: 80/50 mmHg. Assinale a alternativa que apresenta o diagnóstico e a conduta adequada para esse caso:","options":{"A":"Taquicardia supraventricular / Sedação leve e cardioversão química.","B":"Fibrilação atrial / Sedação leve e cardioversão elétrica.","C":"Flutter atrial / Desfibrilação.","D":"Taquicardia sinusal / Conduta expectante.","E":"Fibrilação atrial / Sedação leve e cardioversão química."},"answer":"B","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (2).pdf","sourceLabel":"Taquiarritmias e ACL/BLS","images":["data:image/webp;base64,"],"comment":"Análise:\nCorreta: B.\nPor que está certa: O ECG foi interpretado como fibrilação atrial e a paciente apresenta hipotensão, dor torácica e dispneia, configurando instabilidade. A conduta é cardioversão elétrica sincronizada, com sedação leve se possível.\nPor que as outras estão erradas:\nA: Cardioversão química não é adequada diante de instabilidade.\nC: Desfibrilação não sincronizada é para FV/TV sem pulso ou TV polimórfica, não flutter com pulso.\nD: Taquicardia sinusal é resposta fisiológica e não costuma iniciar abruptamente com ritmo descrito.\nE: FA instável não deve ser tratada apenas com fármacos.\nPonto de prova: Conduta elétrica em taquiarritmia instável.\nFlashcard sugerido:\nPergunta: Qual a conduta para FA com PA 80/50 mmHg?\nResposta: Cardioversão elétrica sincronizada.\n\nPérola:\nPulso presente + taquiarritmia instável = sincronizar.\n\nArmadilha:\nUsar desfibrilação não sincronizada em paciente com pulso.\n\n--------------------------------------------------------------------------------","tags":["Clínica Médica","Cardiologia","Dor Torácica","Dispneia","Conduta Terapêutica","Urgência e Emergência"],"tagSource":"Tags.txt","globalNumber":38},{"id":"b12-taquiarritmias-acl-bls-q07","number":7,"collectionBlock":12,"documentBlock":13,"area":"Clínica Médica","topic":"Taquiarritmias e ACL/BLS","stem":"Diante de um atendimento a um paciente em parada cardiorrespiratória, o líder precisa conduzir a equipe que está realizando a Reanimação Cardiopulmonar (RCP). Qual é a maneira de comunicação mais apropriada entre o líder e a equipe nessa situação?","options":{"A":"Apenas o líder da equipe possui a competência necessária para verbalizar informações, devendo o restante da equipe permanecer em silêncio durante todo o atendimento.","B":"O líder deve transmitir mensagens simultâneas a cada membro da equipe para que sejam evitados atos de procrastinação e a situação possa ser revertida o mais rápido possível.","C":"O líder deve transmitir uma mensagem, ordem ou atribuição a um membro da equipe; solicitar uma resposta clara e contato visual do membro da equipe para garantir que tenha entendido a mensagem; confirmar que o membro da equipe concluiu a tarefa, antes de lhe atribuir outra tarefa.","D":"O líder deve elevar o tom de voz ao perceber que um dos membros da equipe não compreendeu a ordem dada, a fim de que tal atitude não se repita.","E":"É necessário que o líder reconheça sua equipe com elogios, como forma de incentivá-la quando o atendimento é bem- sucedido, bem como repreender em alto tom de voz ao perceber quaisquer falhas durante o atendimento."},"answer":"C","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (2).pdf","sourceLabel":"Taquiarritmias e ACL/BLS","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: A comunicação em alça fechada exige ordem dirigida a uma pessoa, confirmação verbal de entendimento e verificação de conclusão, reduzindo omissões e duplicidade durante a RCP.\nPor que as outras estão erradas:\nA: Toda a equipe deve comunicar dados relevantes; silêncio absoluto é inseguro.\nB: Ordens simultâneas geram confusão e perda de rastreabilidade.\nD: Elevar o tom não garante compreensão e prejudica o desempenho.\nE: Repreensão durante a ressuscitação é inadequada; debriefing ocorre depois.\nPonto de prova: Comunicação em alça fechada na ressuscitação.\nFlashcard sugerido:\nPergunta: O que é comunicação em alça fechada?\nResposta: Ordem individualizada, repetição/confirmação e verificação da execução.\n\nPérola:\nNa RCP, a ordem só termina quando foi confirmada e executada.\n\nArmadilha:\nConfundir liderança com autoritarismo.\n\n--------------------------------------------------------------------------------","tags":["Clínica Médica","Medicina Interna","Parada Cardiorrespiratória","Conhecimento Conceitual","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags.txt","globalNumber":40},{"id":"b12-taquiarritmias-acl-bls-q08","number":8,"collectionBlock":12,"documentBlock":13,"area":"Clínica Médica","topic":"Taquiarritmias e ACL/BLS","stem":"Um profissional de saúde observou à sua frente, durante uma caminhada, que uma senhora subitamente parou de andar, agachou-se, bastante pálida e sudorética, e desfaleceu. Em posse de sua máscara para ventilação boca-máscara, ele iniciou o primeiro atendimento à paciente. Ela estava inconsciente, não apresentava movimentos torácicos nem pulso carotídeo palpável. Solicita, então, que alguém de passagem chame o Serviço de atendimento médico de urgência (SAMU) e que outra pessoa providencie um desfibrilador externo automático (DEA). Considerando a situacãoa presentada, a conduta desse profissional deve ser iniciar imediatamente.","options":{"A":"Compressões torácicas de forma contínua, realizando concomitantemente uma ventilação a cada 2 ou 3 segundos, caso haja dois socorristas.","B":"Compressões torácicas, após a abertura das vias aéreas e ventilação, mantendo a relação de duas ventilacõess eguidas por 30 compressões.","C":"Compressões torácicas de forma contínua, interrompendo o procedimento a cada 5 minutos para checar o pulso, revezando com outro socorrista, se possível.","D":"Compressões torácicas de pelo menos 5 centímetros de profundidade, com frequência de 100 a 120 por minuto, seguidas de abertura das vias aéreas e ventilação."},"answer":"D","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (2).pdf","sourceLabel":"Taquiarritmias e ACL/BLS","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: Adulto sem respiração e sem pulso deve receber RCP em sequência C-A-B: compressões de 100–120/min, profundidade de pelo menos 5 cm, permitindo retorno completo do tórax, seguidas de abertura de via aérea e ventilação em ciclos 30:2.\nPor que as outras estão erradas:\nA: Ventilação a cada 2–3 s com compressões contínuas só se aplica após via aérea avançada.\nB: A sequência atual começa por compressões, não por abertura de via aérea e ventilação.\nC: Pulso/ritmo é checado aproximadamente a cada 2 minutos, não a cada 5.\nPonto de prova: Qualidade e sequência da RCP em adulto.\nFlashcard sugerido:\nPergunta: Quais são frequência e profundidade das compressões em adulto?\nResposta: 100–120/min e pelo menos 5 cm, sem exceder cerca de 6 cm.\n\nPérola:\nRCP do adulto começa por C: compressões.\n\nArmadilha:\nUsar ventilação contínua antes de via aérea avançada.\n\n--------------------------------------------------------------------------------","tags":["Clínica Médica","Medicina Interna","Conduta Terapêutica","Urgência e Emergência","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags.txt","globalNumber":52},{"id":"b12-taquiarritmias-acl-bls-q09","number":9,"collectionBlock":12,"documentBlock":13,"area":"Clínica Médica","topic":"Taquiarritmias e ACL/BLS","stem":"Um homem com 26 anos é levado por amigos para o pronto-socorro devido a palpitações, tonturas e mal-estar. Relata que a sintomatologia iniciou abruptamente há 2 horas. Os amigos contam que estavam com ele em uma festa e confirmam consumo de bebida alcoólica, mas negam consumo de drogas ilícitas. O paciente nega episódios prévios ou comorbidades. Ao exame físico, apresenta-se com pulso irregular, com frequência cardíaca em torno de 123 bpm. A pressão arterial é de 118 × 68 mmHg e, à ausculta cardíaca, não apresenta sopros, mas verifica-se ritmo irregular, não se constatando outras alteracõesn esse exame. O eletrocardiograma mostra linha de base serrilhada, presencad e onda F, intervalo RR irregular e frequenciad e 125 bpm. Nesse contexto, a abordagem desse paciente deve incluir:","options":{"A":"Uso de betabloqueador.","B":"Desfibrilação ventricular.","C":"Massagem de seio carotídeo","D":"Administração de lidocaína endovenosa."},"answer":"A","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (2).pdf","sourceLabel":"Taquiarritmias e ACL/BLS","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: O traçado descrito é flutter atrial com condução variável e paciente estável. O controle da resposta ventricular com betabloqueador é apropriado, após avaliar contraindicações.\nPor que as outras estão erradas:\nB: Desfibrilação é para FV/TV sem pulso, não flutter estável.\nC: Massagem do seio carotídeo pode aumentar bloqueio AV e revelar ondas F, mas não é tratamento definitivo e tem contraindicações.\nD: Lidocaína trata arritmias ventriculares, não flutter atrial.\nPonto de prova: Controle de frequência no flutter atrial estável.\nFlashcard sugerido:\nPergunta: Como tratar inicialmente flutter atrial estável com resposta ventricular elevada?\nResposta: Controle de frequência com betabloqueador ou bloqueador de canal de cálcio não diidropiridínico.\n\nPérola:\nFlutter é supraventricular; lidocaína não resolve.\n\nArmadilha:\nConfundir ritmo serrilhado com taquicardia ventricular.\n\n--------------------------------------------------------------------------------","tags":["Clínica Médica","Cardiologia","Eletrocardiograma","Interpretação de Exames","Urgência e Emergência","Avaliação Clínica"],"tagSource":"Tags.txt","globalNumber":53},{"id":"b12-taquiarritmias-acl-bls-q10","number":10,"collectionBlock":12,"documentBlock":13,"area":"Clínica Médica","topic":"Taquiarritmias e ACL/BLS","stem":"Um paciente de 27 anos, com história de cirurgia cardíaca bem-sucedida para correção de comunicação interventricular há 10 anos, procura uma unidade de pronto-atendimento referindo palpitações de início súbito há 3 horas. Conta que foi a uma festa no dia anterior e que ingeriu bebida alcoólica em grande quantidade, vomitando durante a madrugada. Acordou com cefaleia e sede. O paciente está pálido, desidratado (1+/4+), taquipneico e apresenta cicatriz de esternotomia mediana. Apresenta pressão sistólica de 70 mmHg, a frequência cardíaca, conforme visto no monitor, está oscilando e a frequência cardíaca média está em 170 batimentos por minuto. A ausculta cardíaca revela um ritmo irregularmente irregular, com variação de intensidade da primeira bulha entre os batimentos: Nesse caso, a conduta adequada é a:","options":{"A":"Realização de cardioversão elétrica.","B":"Realização de ressuscitação volêmica.","C":"Administração de metoprolol endovenoso.","D":"Administração de amiodarona endovenosa."},"answer":"A","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (2).pdf","sourceLabel":"Taquiarritmias e ACL/BLS","images":["data:image/webp;base64,"],"comment":"Análise:\nCorreta: A.\nPor que está certa: Ritmo irregularmente irregular, taquicardia intensa e hipotensão grave indicam fibrilação atrial com resposta ventricular rápida e instabilidade; a intervenção imediata é cardioversão elétrica sincronizada.\nPor que as outras estão erradas:\nB: Volume pode ser adjuvante se houver desidratação, mas não deve atrasar a correção da arritmia instável.\nC: Metoprolol pode agravar hipotensão.\nD: Amiodarona tem início mais lento e não substitui cardioversão no choque.\nPonto de prova: Tratamento da FA instável.\nFlashcard sugerido:\nPergunta: Qual a conduta na FA rápida com PAS de 70 mmHg?\nResposta: Cardioversão elétrica sincronizada.\n\nPérola:\nChoque por taquiarritmia pede eletricidade.\n\nArmadilha:\nAtribuir toda hipotensão à desidratação e ignorar a arritmia.\n\n--------------------------------------------------------------------------------","tags":["Clínica Médica","Neurologia","Cefaleia","Conduta Terapêutica","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags.txt","globalNumber":59},{"id":"b12-taquiarritmias-acl-bls-q11","number":11,"collectionBlock":12,"documentBlock":13,"area":"Clínica Médica","topic":"Taquiarritmias e ACL/BLS","stem":"Um homem de 68 anos, portador de enfisema pulmonar e de fibrilação atrial (FA) permanente, encontra-se internado na sala vermelha de uma unidade de pronto-atendimento em razão de exacerbação aguda de doença pulmonar obstrutiva crônica. Subitamente, ele apresenta dessaturação e apneia. A equipe observa que o paciente encontra-se em parada cardiorrespiratória, a despeito de manter o ritmo de FA — agora em alta resposta ventricular. Iniciados os procedimentos de reanimação cardiopulmonar, é constatada turgência jugular e ausência de expansibilidade em hemitórax direito, mesmo com a ventilação com bolsa-máscara; além disso, a percussão local revela timpanismo. Já foi administrada uma dose de 1 mg de epinefrina intravenosa. Diante do quadro desse paciente, a conduta indicada é:","options":{"A":"Proceder à imediata cardioversão elétrica da fibrilação atrial.","B":"Realizar toracocentese imediata no 5º espaço intercostal direito.","C":"Substituir as próximas doses de adrenalina por amiodarona.","D":"Providenciar esternotomia imediata para massagem cardíaca interna."},"answer":"B","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (2).pdf","sourceLabel":"Taquiarritmias e ACL/BLS","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Parada em AESP com turgência jugular, ausência de expansão unilateral e timpanismo indica pneumotórax hipertensivo, uma causa reversível. Deve-se realizar descompressão torácica imediata, preferencialmente no 4º/5º espaço intercostal em linha axilar anterior/média, seguida de drenagem.\nPor que as outras estão erradas:\nA: A fibrilação atrial observada é atividade elétrica sem pulso e não deve ser cardiovertida; o problema é mecânico obstrutivo.\nC: Amiodarona não trata AESP nem pneumotórax hipertensivo.\nD: Esternotomia e massagem interna não são indicadas nesse contexto.\nPonto de prova: Reconhecimento e tratamento das causas reversíveis da AESP.\nFlashcard sugerido:\nPergunta: Qual causa reversível da PCR cursa com turgência jugular, hemitórax sem expansão e timpanismo?\nResposta: Pneumotórax hipertensivo; realizar descompressão imediata.\n\nPérola:\nEm AESP, procure os 5H e 5T.\n\nArmadilha:\nTratar o ritmo do monitor e ignorar a causa mecânica da parada.\n\n--------------------------------------------------------------------------------","tags":["Clínica Médica","Pneumologia","Fibrilação Atrial","DPOC","Conduta Terapêutica","Pessoa Idosa"],"tagSource":"Tags.txt","globalNumber":61},{"id":"b12-taquiarritmias-acl-bls-q12","number":12,"collectionBlock":12,"documentBlock":13,"area":"Clínica Médica","topic":"Taquiarritmias e ACL/BLS","stem":"Mulher, 76 anos de idade, antecedentes de hipertensão arterial sistêmica, diabetes mellitus tipo 2 e osteoporose. Em uso de Enalapril 20 mg 2x/dia, HCTZ 25 mg/dia, Metformina 850 mg 3x/dia, Alendronato 70 mg/semana e vitamina D 1.000 UI/dia. Relata palpitações esporádicas há 8 meses e nessa semana com 2 episódios de desmaio sem sintomas prodrômicos. Chega ao PS sem dor precordial ou dispneia, PA = 112 × 68 mmHg, lúcida e orientada. Ausculta cardíaca sem sopros e exames laboratoriais com troponina-us inferior a 0,4 ng/L, Hb = 12,1 g/dL e TSH = 3,2 mUI/L (ref < 4,5 mUI/L). Eletrocardiograma a seguir. Qual a conduta em relação à internação? Fonte: Unicamp","options":{"A":"Cardioversão elétrica sincronizada (CVES).","B":"Cardioversão química com amiodarona.","C":"Indicar marcapasso + anticoagulação.","D":"Metoprolol 50 mg + Ecocardiograma transesofágico."},"answer":"C","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (2).pdf","sourceLabel":"Taquiarritmias e ACL/BLS","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: O ECG e a história sugerem bradiarritmia/pausas associadas a síncope, além de fibrilação atrial com indicação de prevenção tromboembólica. A internação deve viabilizar avaliação para marcapasso e anticoagulação.\nPor que as outras estão erradas:\nA: Cardioversão não corrige doença de condução com pausas e não é indicada se a paciente está estável.\nB: Amiodarona pode agravar bradicardia e não resolve a causa da síncope.\nD: Metoprolol também pode piorar bradicardia; ecocardiograma transesofágico não é prioridade.\nPonto de prova: Síndrome bradi-taqui e indicação de marcapasso/anticoagulação.\nFlashcard sugerido:\nPergunta: Como manejar FA associada a síncope por bradiarritmia?\nResposta: Avaliar marcapasso e indicar anticoagulação conforme risco tromboembólico.\n\nPérola:\nAntes de frear a FA, verifique se o nó sinusal já está falhando.\n\nArmadilha:\nDar bloqueador nodal a paciente com pausas e síncope.\n\n--------------------------------------------------------------------------------","tags":["Clínica Médica","Endocrinologia","Diabetes Mellitus Tipo 2","Hipertensão Arterial","Conduta Terapêutica","Pessoa Idosa"],"tagSource":"Tags.txt","globalNumber":79},{"id":"b12-taquiarritmias-acl-bls-q13","number":13,"collectionBlock":12,"documentBlock":13,"area":"Clínica Médica","topic":"Taquiarritmias e ACL/BLS","stem":"Uma mulher de 54 anos, sem antecedentes cardiovasculares, procura o pronto-socorro com queixa de palpitações há 18 horas acompanhadas de ortopneia e dispneia aos pequenos esforços. Apresenta pulso rápido e irregular, PA: 90 × 68 mmHg e estertores nas bases pulmonares. Antes de se tentar a reversão, elétrica ou medicamentosa da arritmia, é indicada a administração de:","options":{"A":"Enoxaparina dose profilática.","B":"Clopidogrel.","C":"Rivaroxabana.","D":"AAS.","E":"Clopidogrel + AAS."},"answer":"C","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (2).pdf","sourceLabel":"Taquiarritmias e ACL/BLS","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: A supressão do ciclo e a indução de amenorreia com progestagênios, contraceptivos combinados contínuos ou outras terapias hormonais reduzem estímulo estrogênico e dor da endometriose.\nPor que as outras estão erradas:\nA: O diagnóstico pode ser clínico e por imagem; laparoscopia não é obrigatória, e RM não é padrão-ouro universal.\nB: A intensidade da dor não se correlaciona diretamente com número ou extensão das lesões.\nC: CA-125 não mede gravidade nem é teste diagnóstico específico.\nE: Endometrioma não constitui indicação cirúrgica absoluta; a decisão depende de tamanho, sintomas, fertilidade e suspeita de malignidade.\nPonto de prova: Princípios de tratamento clínico da endometriose.\nFlashcard sugerido:\nPergunta: Qual é o objetivo da terapia hormonal na endometriose?\nResposta: Suprimir ovulação/menstruação e induzir amenorreia para controlar sintomas.\n\nPérola:\nA extensão da endometriose não prediz a intensidade da dor.\n\nArmadilha:\nTratar todo endometrioma cirurgicamente.\n\n--------------------------------------------------------------------------------"},{"id":"b12-taquiarritmias-acl-bls-q14","number":14,"collectionBlock":12,"documentBlock":13,"area":"Clínica Médica","topic":"Taquiarritmias e ACL/BLS","stem":"Um paciente de 20 anos é atendido com quadro de palpitação paroxística. Realizado Holter de 24 horas evidenciou-se períodos de fibrilação atrial com alta resposta ventricular. Sua função tireoidiana é normal. ECG em ritmo sinusal com Intervalo PR de 100 ms, QRS 0,16 segundos e deflexão ascendente e lenta da porção inicial do complexo QRS. Assinale a alternativa que contém a conduta mais recomendada para esse paciente:","options":{"A":"Amiodarona.","B":"Sotalol.","C":"Digoxina.","D":"Estudo eletrofisiológico com ablação por cateter.","E":"Cardioversão elétrica sincronizada."},"answer":"D","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (2).pdf","sourceLabel":"Taquiarritmias e ACL/BLS","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: A taquicardia atrial geralmente apresenta QRS estreito e ritmo regular, salvo condução AV variável.\nPor que as outras estão erradas:\nA: Fibrilação atrial é irregularmente irregular.\nB: Torsades é taquicardia ventricular polimórfica de QRS largo.\nD: Taquicardia antidrômica conduz pelo feixe acessório no sentido anterógrado e costuma ter QRS largo.\nE: Flutter com bloqueio AV variável produz resposta ventricular irregular.\nPonto de prova: Classificação de taquiarritmias por largura do QRS e regularidade.\nFlashcard sugerido:\nPergunta: Qual taquiarritmia é tipicamente regular e de QRS estreito?\nResposta: Taquicardia atrial.\n\nPérola:\nQRS estreito sugere origem supraventricular, mas a regularidade diferencia os ritmos.\n\nArmadilha:\nConfundir flutter com condução fixa e flutter com bloqueio variável.\n\n--------------------------------------------------------------------------------"},{"id":"b12-taquiarritmias-acl-bls-q15","number":15,"collectionBlock":12,"documentBlock":13,"area":"Clínica Médica","topic":"Taquiarritmias e ACL/BLS","stem":"Um paciente de 72 anos de idade, hipertenso e diabético procurou atendimento na UPA queixando-se de início súbito de palpitações há 8 horas, associado d leve dispneia e mal-estar. Ao exame físico, apresentava PA = 138 × 86 mmHg, FC = 132 bpm (irregular), FR = 20 irpm, SatO= 96%. Foi realizado o eletrocardiograma, que apresentou o resultado evidenciado na imagem: Qual é a conduta inicial mais adequada para esse paciente?","options":{"A":"Controlar a frequência cardíaca com betabloqueador ou bloqueador de canal de cálcio.","B":"Realizar cardioversão-elétrica imediatamente para todos os casos.","C":"Utilizar anticoagulação plena por três semanas antes de qualquer intervenção.","D":"Administrar adenosina para reversão."},"answer":"A","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (2).pdf","sourceLabel":"Taquiarritmias e ACL/BLS","images":["data:image/webp;base64,"],"comment":"Análise:\nCorreta: C.\nPor que está certa: Abertura controlada do trato gastrointestinal em cirurgia eletiva, sem contaminação anormal, classifica a operação como potencialmente contaminada ou limpa-contaminada.\nPor que as outras estão erradas:\nA: Cirurgia limpa não entra em tratos respiratório, digestivo, genital ou urinário.\nB: Contaminada envolve falha importante de técnica, extravasamento grosseiro ou inflamação aguda não purulenta.\nD: Suja pressupõe infecção estabelecida, víscera perfurada ou tecido desvitalizado.\nE: Infectada equivale à categoria suja/infectada e não se aplica ao acesso controlado.\nPonto de prova: Classificação das feridas operatórias por grau de contaminação.\nFlashcard sugerido:\nPergunta: Como classificar cirurgia gástrica eletiva com abertura controlada do estômago?\nResposta: Potencialmente contaminada/limpa-contaminada.\n\nPérola:\nEntrada controlada em víscera colonizada não torna a cirurgia contaminada.\n\nArmadilha:\nAssociar qualquer abertura gastrointestinal a cirurgia contaminada.\n\n--------------------------------------------------------------------------------"},{"id":"b12-taquiarritmias-acl-bls-q16","number":16,"collectionBlock":12,"documentBlock":13,"area":"Clínica Médica","topic":"Taquiarritmias e ACL/BLS","stem":"Paciente masculino, de 68 anos, com antecedente de hipertensão arterial e infarto agudo do miocárdio há 5 anos, na época submetido à angioplastia com implante de stent farmacológico na artéria circunflexa, mantém-se desde então estável, sem novos episódios de angina ou internações. Ele fez uso inicialmente de aspirina e clopidogrel durante um ano e atualmente faz uso contínuo de aspirina 100 mg/dia, além de rosuvastatina 20 mg/dia e enalapril 20 mg/dia. Durante um exame de rotina recente, foi detectado um ritmo cardíaco irregular pelo médico, sendo diagnosticado com fibrilação atrial. Atualmente o paciente está assintomático, sem quaisquer queixas. No exame físico, apresenta pressão arterial de 135/85 mmHg, frequência cardíaca de 78 bpm (ritmo irregular), sem sinais de congestão pulmonar ou edema periférico. Com base no diagnóstico recente e no histórico do paciente, qual seria a estratégia antitrombótica mais adequada a ser adotada neste momento?","options":{"A":"Continuar apenas com aspirina 100 mg/dia.","B":"Substituir aspirina por rivaroxabana 20 mg uma vez ao dia.","C":"Manter aspirina 100 mg/dia e associar rivaroxabana 15 mg uma vez ao dia.","D":"Associar clopidogrel 75 mg/dia à aspirina 100 mg/dia."},"answer":"B","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (2).pdf","sourceLabel":"Taquiarritmias e ACL/BLS","images":["data:image/webp;base64,"],"comment":"Análise:\nCorreta: B.\nPor que está certa: Em FA não valvar com CHA₂DS₂-VASc elevado e doença coronariana estável há mais de 1 ano da PCI, recomenda-se anticoagulação oral isolada. Rivaroxabana substitui o AAS.\nPor que as outras estão erradas:\nA: AAS não previne adequadamente AVC cardioembólico da FA.\nC: Associar AAS aumenta sangramento sem benefício rotineiro na coronariopatia estável; 15 mg só se justificaria por função renal/estratégia específica.\nD: Dupla antiagregação não substitui anticoagulação na FA.\nPonto de prova: Antitrombose na FA com coronariopatia estável.\nFlashcard sugerido:\nPergunta: Como tratar FA em paciente com stent implantado há mais de 1 ano e sem eventos recentes?\nResposta: Anticoagulante oral isolado.\n\nPérola:\nDepois de 1 ano de PCI estável, FA costuma ficar só com anticoagulante.\n\nArmadilha:\nManter AAS por inércia apesar do aumento de sangramento.\n\n--------------------------------------------------------------------------------","tags":["Clínica Médica","Cardiologia","Infarto Agudo do Miocárdio","Hipertensão Arterial","Raciocínio Diagnóstico","Pessoa Idosa"],"tagSource":"Tags.txt","globalNumber":94},{"id":"b12-taquiarritmias-acl-bls-q17","number":17,"collectionBlock":12,"documentBlock":13,"area":"Clínica Médica","topic":"Taquiarritmias e ACL/BLS","stem":"1 - São elementos de uma reanimação cardiopulmonar de qualidade: I - Compressões torácicas na frequência de 100-120/minuto. II - Compressões torácicas com pelo menos 5cm de profundidade. III - Uma relação de 15 compressões/2 ventilações, devendo o ritmo cardíaco ser reavaliado a cada 2 minutos.","options":{"A":"Apenas a afirmativa I está correta.","B":"Apenas as afirmativas I e II estão corretas.","C":"Apenas as afirmativas II e III estão corretas.","D":"Todas as afirmativas estão corretas."},"answer":"B","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (2).pdf","sourceLabel":"Taquiarritmias e ACL/BLS","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: Estenose ureteral, hidronefrose, endometrioma volumoso e dor refratária configuram doença profunda com comprometimento orgânico e indicação cirúrgica terapêutica por equipe experiente.\nPor que as outras estão erradas:\nB: Biópsia isolada não resolve obstrução ureteral nem a dor e não é o objetivo da laparoscopia nesse contexto.\nC: Fertilização in vitro não corrige a hidronefrose nem o risco de dano renal.\nD: Inseminação intrauterina não trata doença profunda nem obstrução urinária.\nPonto de prova: Indicações de cirurgia na endometriose profunda.\nFlashcard sugerido:\nPergunta: Quando a endometriose profunda exige cirurgia?\nResposta: Quando há obstrução de órgão, hidronefrose, massa relevante ou dor refratária.\n\nPérola:\nEndometriose com hidronefrose é doença com risco funcional.\n\nArmadilha:\nPriorizar fertilidade sem tratar ameaça ao ureter e ao rim.\n\n--------------------------------------------------------------------------------"},{"id":"b12-taquiarritmias-acl-bls-q18","number":18,"collectionBlock":12,"documentBlock":13,"area":"Clínica Médica","topic":"Taquiarritmias e ACL/BLS","stem":"Considere um paciente com fibrilação atrial de alta resposta ventricular e de tempo indeterminado. Qual é a conduta ideal a ser tomada?","options":{"A":"Cardioversão elétrica imediata.","B":"Cardioversão química imediata.","C":"Estudo eletrofisiológico e ablação por radiofrequência.","D":"Controle da frequência e anticoagulação plena por três semanas, seguida de cardioversão."},"answer":"D","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (2).pdf","sourceLabel":"Taquiarritmias e ACL/BLS","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Diante de colapso súbito, a sequência inicial é verificar segurança, responsividade e respiração/pulso rapidamente; só depois se define RCP ou outra intervenção.\nPor que as outras estão erradas:\nA: ECG vem após avaliação inicial e estabilização.\nC: Epinefrina só é indicada após confirmar parada e iniciar RCP conforme algoritmo.\nD: Compressões começam se a pessoa estiver irresponsiva, sem respiração normal e sem pulso; isso ainda não foi checado.\nE: Avaliação especializada não precede o ABC inicial.\nPonto de prova: Primeiro passo na avaliação de colapso.\nFlashcard sugerido:\nPergunta: Qual é a primeira ação diante de uma pessoa que colapsa?\nResposta: Checar responsividade e respiração/pulso rapidamente.\n\nPérola:\nAntes de tratar uma parada, confirme a parada.\n\nArmadilha:\nPular diretamente para compressões ou medicação sem avaliação inicial.\n\n--------------------------------------------------------------------------------"},{"id":"b12-taquiarritmias-acl-bls-q19","number":19,"collectionBlock":12,"documentBlock":13,"area":"Clínica Médica","topic":"Taquiarritmias e ACL/BLS","stem":"A maioria dos pacientes com Doença do Nó Sinusal apresenta condução atrioventricular preservada. Sendo correto que:","options":{"A":"Estimulação do VD tem sido associada a consequências fisiológicas positivas como resultado da dissincronia ventricular: remodelamento e redução da fração de ejeção do VE (FEVE) e insuficiência mitral funcional.","B":"Estimulação do VD tem sido associada a consequências fisiológicas negativas como resultado da dissincronia ventricular: remodelamento e redução da fração de ejeção do VE (FEVE) e insuficiência mitral funcional.","C":"Estimulação do VD tem sido associada a consequências fisiológicas negativas como resultado da dissincronia ventricular: remodelamento e redução da fração de ejeção do VE (FEVE) e não insuficiência mitral funcional.","D":"Estimulação do VE tem sido associada a consequências fisiológicas negativas como resultado da dissincronia ventricular: remodelamento e redução da fração de ejeção do VE (FEVE) e insuficiência mitral funcional."},"answer":"B","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (2).pdf","sourceLabel":"Taquiarritmias e ACL/BLS","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: Endometriose profunda com estenose ureteral tem risco de perda silenciosa da função renal e constitui indicação de abordagem cirúrgica laparoscópica, idealmente multidisciplinar.\nPor que as outras estão erradas:\nA: SIU-LNG controla dor e sangramento, mas não corrige estenose ureteral e ainda impede tentativa gestacional.\nB: Progestagênio isolado controla sintomas, porém não resolve obstrução nem atende ao desejo gestacional imediato.\nC: Contraceptivo combinado também suprime sintomas e contracepção, sem tratar a lesão obstrutiva.\nPonto de prova: Comprometimento ureteral como indicação cirúrgica na endometriose.\nFlashcard sugerido:\nPergunta: Qual achado da endometriose profunda exige intervenção para preservar função renal?\nResposta: Estenose ureteral com ou sem hidronefrose.\n\nPérola:\nUreter comprometido não é caso para apenas suprimir menstruação.\n\nArmadilha:\nEscolher contraceptivo em paciente infértil com obstrução ureteral.\n\n--------------------------------------------------------------------------------"},{"id":"b12-taquiarritmias-acl-bls-q20","number":20,"collectionBlock":12,"documentBlock":13,"area":"Clínica Médica","topic":"Taquiarritmias e ACL/BLS","stem":"Qual das seguintes drogas pode ser administrada através do tubo orotraqueal?","options":{"A":"Flumazenil","B":"Naloxona.","C":"Dopamina.","D":"Amiodarona."},"answer":"B","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (2).pdf","sourceLabel":"Taquiarritmias e ACL/BLS","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Na ausência de acesso venoso/intraósseo, a naloxona pode ser administrada por via endotraqueal, embora as vias IV, IM ou intranasal sejam preferidas. Ela integra o grupo clássico de fármacos passíveis de uso pelo tubo.\nPor que as outras estão erradas:\nA: Flumazenil não é fármaco recomendado por via endotraqueal e pode precipitar convulsões em intoxicação mista.\nC: Dopamina requer infusão vascular titulada.\nD: Amiodarona não é recomendada por via endotraqueal.\nPonto de prova: Vias alternativas de administração em emergência.\nFlashcard sugerido:\nPergunta: Qual fármaco pode ser administrado pelo tubo endotraqueal em situação excepcional?\nResposta: Naloxona.\n\nPérola:\nPelo tubo: use apenas drogas específicas e prefira IV/IO.\n\nArmadilha:\nSupor que qualquer droga de ressuscitação pode ser instilada no tubo.\n\n--------------------------------------------------------------------------------","tags":["Clínica Médica","Medicina Interna","Conhecimento Conceitual","Paciente Adulto","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags.txt","globalNumber":91},{"id":"b12-endometriose-q01","number":1,"collectionBlock":12,"documentBlock":13,"area":"G.O.","topic":"Endometriose","stem":"Mulher, 31 anos de idade, com queixa de dor pélvica crônica (Escala Visual Analógica 8) realiza ultrassonografia pélvica e observa-se a presença de massa cística de conteúdo heterogêneo linear em vários planos, de aspecto reticular de 4 cm em ovário direito. O próximo passo é:","options":{"A":"Realizar punção sob visão ultrassonográfica para caracterização citológica.","B":"Indicar cirurgia para exérese do cisto visando a preservação da fertilidade.","C":"Solicitar exame de imagem especializado para avaliar a presença de endometriose profunda.","D":"Acompanhar com ultrassonografia trimestral para avaliar aspecto do cisto."},"answer":"C","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (3).pdf","sourceLabel":"Endometriose","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Uma imagem ovariana reticular/heterogênea de 4 cm em paciente com dor pélvica intensa pode corresponder a endometrioma ou cisto hemorrágico; antes de operar, é necessário mapear doença profunda com ultrassonografia especializada ou ressonância de pelve.\nPor que as outras estão erradas:\nA: Punção de endometrioma/cisto suspeito não é método diagnóstico de rotina, tem alta recorrência e pode disseminar conteúdo.\nB: Cirurgia não é automática em cisto de 4 cm; depende de sintomas, suspeita de malignidade, infertilidade, crescimento e mapeamento anatômico.\nD: Seguimento isolado é insuficiente diante de dor intensa e suspeita de endometriose profunda.\nPonto de prova: Reconhecimento ultrassonográfico de endometrioma e indicação de mapeamento de endometriose profunda.\nFlashcard sugerido:\nPergunta: Qual é o próximo passo diante de provável endometrioma associado a dor pélvica importante?\nResposta: Mapear endometriose profunda com imagem especializada antes de definir tratamento.\n\nPérola:\nEndometrioma não se punciona de rotina; primeiro se mapeia a doença.\n\nArmadilha:\nConfundir identificação de cisto ovariano com indicação cirúrgica imediata.\n\n--------------------------------------------------------------------------------","tags":["Ginecologia e Obstetrícia","Ginecologia","Massa Anexial","Dor Pélvica","Interpretação de Exames","Paciente Adulto"],"tagSource":"Tags.txt","globalNumber":1},{"id":"b12-endometriose-q02","number":2,"collectionBlock":12,"documentBlock":13,"area":"G.O.","topic":"Endometriose","stem":"Mulher de 34 anos com dismenorreia leve e dispareunia profunda, sem desejo de gravidez, realizou ressonância nuclear magnética da pelve, que evidenciou ovários desviados posteromedialmente, com focos hemorrágicos junto às suas superfícies mediais e espessamento dos ligamentos uterossacros. Nesse caso, o diagnóstico e o tratamento inicial que devem ser propostos respectivamente, são:","options":{"A":"Endometriose / etinilestadiol.","B":"Endometriose / dienogeste.","C":"Vaginismo / amitriptilina.","D":"Vaginismo / ulipristal."},"answer":"B","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (3).pdf","sourceLabel":"Endometriose","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Desvio posteromedial dos ovários, focos hemorrágicos e espessamento de ligamentos uterossacros são típicos de endometriose profunda. Sem desejo gestacional, o dienogeste contínuo é tratamento inicial apropriado para supressão hormonal e dor.\nPor que as outras estão erradas:\nA: Etinilestradiol isolado não é usado; contraceptivo combinado exige associação com progestagênio.\nC: Vaginismo não explica os achados de imagem.\nD: Ulipristal não é tratamento de vaginismo nem de endometriose.\nPonto de prova: Achados de imagem da endometriose profunda e tratamento hormonal inicial.\nFlashcard sugerido:\nPergunta: Qual progestagênio é usado continuamente no tratamento da endometriose?\nResposta: Dienogeste.\n\nPérola:\nEndometriose profunda: dor cíclica + ligamentos uterossacros espessados.\n\nArmadilha:\nDesvalorizar os achados anatômicos e atribuir dispareunia a vaginismo.\n\n--------------------------------------------------------------------------------","tags":["Clínica Médica","Medicina Interna","Conduta Terapêutica","Paciente Adulto","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags.txt","globalNumber":8},{"id":"b12-endometriose-q03","number":3,"collectionBlock":12,"documentBlock":13,"area":"G.O.","topic":"Endometriose","stem":"A endometriose frequentemente compromete a qualidade de vida da paciente. São comuns os atrasos no diagnóstico devido a diversas possibilidades de patologias com o mesmo sintoma. Em relação a essa patologia, assinale a alternativa correta:","options":{"A":"A ressonância magnética de pelve é considerada padrão-ouro de diagnóstico.","B":"Há correlação entre a quantidade de focos e a dor da paciente.","C":"O marcador CA-125 elevado indica a gravidade do caso.","D":"O tratamento pode ser realizado promovendo a amenorreia da paciente.","E":"É indicação absoluta para cirurgia a presença de endometrioma."},"answer":"D","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (3).pdf","sourceLabel":"Endometriose","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: A supressão do ciclo e a indução de amenorreia com progestagênios, contraceptivos combinados contínuos ou outras terapias hormonais reduzem estímulo estrogênico e dor da endometriose.\nPor que as outras estão erradas:\nA: O diagnóstico pode ser clínico e por imagem; laparoscopia não é obrigatória, e RM não é padrão-ouro universal.\nB: A intensidade da dor não se correlaciona diretamente com número ou extensão das lesões.\nC: CA-125 não mede gravidade nem é teste diagnóstico específico.\nE: Endometrioma não constitui indicação cirúrgica absoluta; a decisão depende de tamanho, sintomas, fertilidade e suspeita de malignidade.\nPonto de prova: Princípios de tratamento clínico da endometriose.\nFlashcard sugerido:\nPergunta: Qual é o objetivo da terapia hormonal na endometriose?\nResposta: Suprimir ovulação/menstruação e induzir amenorreia para controlar sintomas.\n\nPérola:\nA extensão da endometriose não prediz a intensidade da dor.\n\nArmadilha:\nTratar todo endometrioma cirurgicamente.\n\n--------------------------------------------------------------------------------","tags":["Ginecologia e Obstetrícia","Ginecologia","Endometriose","Raciocínio Diagnóstico","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags.txt","globalNumber":13},{"id":"b12-endometriose-q04","number":4,"collectionBlock":12,"documentBlock":13,"area":"G.O.","topic":"Endometriose","stem":"Paciente infértil de 31 anos, com diagnóstico de endometriose profunda com estenose de ureter, hidronefrose e endometrioma de 7cm, refere dor refratária ao tratamento clínico. A abordagem iniciar deve ser:","options":{"A":"Videolaparoscopia para exérese dos focos de endometriose;","B":"Videolaparoscopia para biópsia dos focos de endometriose.","C":"Fertilização in vitro com transferência a fresco de embrião.","D":"Inseminação intrauterina com preparo seminal."},"answer":"A","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (3).pdf","sourceLabel":"Endometriose","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: Estenose ureteral, hidronefrose, endometrioma volumoso e dor refratária configuram doença profunda com comprometimento orgânico e indicação cirúrgica terapêutica por equipe experiente.\nPor que as outras estão erradas:\nB: Biópsia isolada não resolve obstrução ureteral nem a dor e não é o objetivo da laparoscopia nesse contexto.\nC: Fertilização in vitro não corrige a hidronefrose nem o risco de dano renal.\nD: Inseminação intrauterina não trata doença profunda nem obstrução urinária.\nPonto de prova: Indicações de cirurgia na endometriose profunda.\nFlashcard sugerido:\nPergunta: Quando a endometriose profunda exige cirurgia?\nResposta: Quando há obstrução de órgão, hidronefrose, massa relevante ou dor refratária.\n\nPérola:\nEndometriose com hidronefrose é doença com risco funcional.\n\nArmadilha:\nPriorizar fertilidade sem tratar ameaça ao ureter e ao rim.\n\n--------------------------------------------------------------------------------","tags":["Ginecologia e Obstetrícia","Ginecologia","Endometriose","Conduta Terapêutica","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags.txt","globalNumber":17},{"id":"b12-endometriose-q05","number":5,"collectionBlock":12,"documentBlock":13,"area":"G.O.","topic":"Endometriose","stem":"Mulher de 29 anos, sem comorbidades, comparece à consulta com queixa de infertilidade e dismenorreia desde a adolescência. Tentando engravidar há três anos, relata nunca ter utilizado contraceptivos hormonais. Traz resultado de ressonância nuclear magnética da pelve, que evidencia estenose ureteral distal e endometriose profunda. O tratamento indicado é:","options":{"A":"Sistema intrauterino liberador de levonorgestrel.","B":"Contraceptivos com progestogênio isolado.","C":"Contraceptivos hormonais combinados.","D":"Abordagem cirúrgica por laparoscopia."},"answer":"D","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (3).pdf","sourceLabel":"Endometriose","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: Endometriose profunda com estenose ureteral tem risco de perda silenciosa da função renal e constitui indicação de abordagem cirúrgica laparoscópica, idealmente multidisciplinar.\nPor que as outras estão erradas:\nA: SIU-LNG controla dor e sangramento, mas não corrige estenose ureteral e ainda impede tentativa gestacional.\nB: Progestagênio isolado controla sintomas, porém não resolve obstrução nem atende ao desejo gestacional imediato.\nC: Contraceptivo combinado também suprime sintomas e contracepção, sem tratar a lesão obstrutiva.\nPonto de prova: Comprometimento ureteral como indicação cirúrgica na endometriose.\nFlashcard sugerido:\nPergunta: Qual achado da endometriose profunda exige intervenção para preservar função renal?\nResposta: Estenose ureteral com ou sem hidronefrose.\n\nPérola:\nUreter comprometido não é caso para apenas suprimir menstruação.\n\nArmadilha:\nEscolher contraceptivo em paciente infértil com obstrução ureteral.\n\n--------------------------------------------------------------------------------","tags":["Ginecologia e Obstetrícia","Ginecologia","Endometriose","Infertilidade","Conduta Terapêutica","Paciente Adulto"],"tagSource":"Tags.txt","globalNumber":19},{"id":"b12-endometriose-q06","number":6,"collectionBlock":12,"documentBlock":13,"area":"G.O.","topic":"Endometriose","stem":"Mulher de 33 anos, com dismenorreia desde a menarca e diagnóstico de endometriose, encontra-se em uso de contraceptivos hormonais. Apesar de bom controle da dor, deseja interromper o uso do medicamento para engravidar. A ressonância de pelve evidenciou cisto ovariano característico de endometrioma de aproximadamente 8cm. Nesse caso, deve-se:","options":{"A":"Realizar drenagem guiada por ultrassonografia.","B":"Manter contraceptivo até regressão do cisto.","C":"Indicar cistectomia videolaparoscópica.","D":"Iniciar medicação antigonadotrópica."},"answer":"C","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (3).pdf","sourceLabel":"Endometriose","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Endometrioma de 8 cm em mulher sintomática que deseja gestação tem indicação de avaliação cirúrgica; a cistectomia laparoscópica reduz recorrência e melhora dor, devendo preservar o máximo de tecido ovariano.\nPor que as outras estão erradas:\nA: Drenagem isolada tem alta taxa de recorrência e não remove a cápsula.\nB: Contraceptivo não costuma fazer regressão relevante de endometrioma e impede concepção.\nD: Antigonadotrópicos não aumentam fertilidade e não são solução para massa de 8 cm.\nPonto de prova: Indicações e técnica do tratamento do endometrioma.\nFlashcard sugerido:\nPergunta: Qual abordagem é preferida para endometrioma volumoso com desejo reprodutivo?\nResposta: Cistectomia videolaparoscópica cuidadosa.\n\nPérola:\nDrenar não basta; endometrioma recidiva se a cápsula permanece.\n\nArmadilha:\nManter supressão hormonal em quem quer engravidar agora.\n\n--------------------------------------------------------------------------------","tags":["Ginecologia e Obstetrícia","Ginecologia","Massa Anexial","Endometriose","Raciocínio Diagnóstico","Paciente Adulto"],"tagSource":"Tags.txt","globalNumber":21},{"id":"b12-endometriose-q07","number":7,"collectionBlock":12,"documentBlock":13,"area":"G.O.","topic":"Endometriose","stem":"Apesar de pouco frequente, a transformação maligna de endometrioma de ovário se manifestacom qualtipo histológico?","options":{"A":"Cistoadenocarcinoma mucinoso","B":"Cistoadenocarcinoma seroso","C":"Carcinoma de células claras","D":"Tumor de células da granulosa","E":"Tumor de Sertoli-Leydig"},"answer":"C","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (3).pdf","sourceLabel":"Endometriose","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Endometriose ovariana associa-se principalmente aos carcinomas endometrioide e de células claras; entre as alternativas, células claras é a correta.\nPor que as outras estão erradas:\nA: Carcinoma mucinoso não é a associação clássica.\nB: Carcinoma seroso de alto grau está mais relacionado à tuba e mutações BRCA.\nD: Tumor de células da granulosa é neoplasia estromal, não derivada de endometriose.\nE: Sertoli-Leydig também é tumor estromal/cordões sexuais.\nPonto de prova: Transformação maligna da endometriose.\nFlashcard sugerido:\nPergunta: Quais carcinomas ovarianos se associam à endometriose?\nResposta: Endometrioide e de células claras.\n\nPérola:\nEndometriose + câncer: pense em endometrioide e células claras.\n\nArmadilha:\nEscolher o tipo epitelial mais comum do ovário em vez do mais associado à endometriose.\n\n--------------------------------------------------------------------------------","tags":["Ginecologia e Obstetrícia","Ginecologia","Endometriose","Conhecimento Conceitual","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags.txt","globalNumber":26},{"id":"b12-endometriose-q08","number":8,"collectionBlock":12,"documentBlock":13,"area":"G.O.","topic":"Endometriose","stem":"Mulher de 30 anos, sem comorbidades, com duas gestações anteriores e laqueadura tubária há um ano, comparece à UBS com queixa de dismenorreia intensa há dez anos, sendo tratada regularmente com analgésicos. O exame ginecológico é normal, mas a ressonância nuclear magnética de pelve demonstra espessamento de ligamento uterossacro direito, sugestivo de endometriose. O tratamento de escolha para essa paciente é:","options":{"A":"Dienogeste contínuo.","B":"Histerectomia simples.","C":"Ooforectomia bilateral.","D":"Agonista do GnRH isolado."},"answer":"A","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (3).pdf","sourceLabel":"Endometriose","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: Endometriose sintomática em mulher sem desejo gestacional, já laqueada, deve ser tratada inicialmente com supressão hormonal; dienogeste contínuo reduz proliferação ectópica e dor.\nPor que as outras estão erradas:\nB: Histerectomia não trata necessariamente focos extrauterinos e é excessiva como primeira linha.\nC: Ooforectomia bilateral causa menopausa cirúrgica e não é tratamento inicial.\nD: Agonista de GnRH isolado é segunda linha, limitado por hipoestrogenismo e necessidade frequente de add-back.\nPonto de prova: Tratamento clínico inicial da endometriose.\nFlashcard sugerido:\nPergunta: Qual terapia de primeira linha para endometriose dolorosa sem desejo gestacional?\nResposta: Progestagênio contínuo, como dienogeste.\n\nPérola:\nPrimeiro suprimir; operar apenas quando houver indicação específica.\n\nArmadilha:\nEscolher cirurgia radical porque a paciente já foi laqueada.\n\n--------------------------------------------------------------------------------","tags":["Ginecologia e Obstetrícia","Ginecologia","Endometriose","Conduta Terapêutica","Atenção Primária","Avaliação Clínica"],"tagSource":"Tags.txt","globalNumber":44},{"id":"b12-endometriose-q09","number":9,"collectionBlock":12,"documentBlock":13,"area":"G.O.","topic":"Endometriose","stem":"Endometrioma de parede abdominal após a cesariana deve ser tratado como:","options":{"A":"Anticoncepcional hormonal contínuo.","B":"Dienogeste contínuo.","C":"Ressecção cirúrgica.","D":"Análogos de GnRH."},"answer":"C","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (3).pdf","sourceLabel":"Endometriose","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Endometrioma em cicatriz abdominal após cesariana é foco localizado em parede; o tratamento de escolha é ressecção cirúrgica ampla com margens, incluindo eventual reparo fascial.\nPor que as outras estão erradas:\nA: Contraceptivo pode aliviar dor, mas não elimina a massa cicatricial.\nB: Dienogeste também pode controlar sintomas, porém não é curativo para lesão de parede.\nD: Análogo de GnRH é temporário e não substitui excisão.\nPonto de prova: Tratamento da endometriose de parede abdominal.\nFlashcard sugerido:\nPergunta: Como tratar endometrioma em cicatriz de cesárea?\nResposta: Excisão cirúrgica completa com margens.\n\nPérola:\nNódulo doloroso cíclico na cicatriz = cortar, não apenas suprimir.\n\nArmadilha:\nTratar foco de parede como endometriose pélvica difusa.\n\n--------------------------------------------------------------------------------","tags":["Clínica Médica","Medicina Interna","Endometriose","Conhecimento Conceitual","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags.txt","globalNumber":67},{"id":"b12-endometriose-q10","number":10,"collectionBlock":12,"documentBlock":13,"area":"G.O.","topic":"Endometriose","stem":"Ao apresentar dor pélvica e diagnóstico prévio de endometriose, uma mulher com queixa de infertilidade mostra resultado de RM evidenciando endometrioma de 7 cm e espessamento de ligamentos uterossacros bilateralmente. Ela deseja realizar apenas tratamento clínico, não pretendendo se submeter à cirurgia. Considerando os problemas identificados, o tratamento clínico pode atuar no(a):","options":{"A":"Controle da dor.","B":"Aumento da fertilidade.","C":"Diminuição do endometrioma.","D":"Redução do espessamento ligamentar."},"answer":"A","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (3).pdf","sourceLabel":"Endometriose","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: O tratamento hormonal da endometriose reduz atividade inflamatória e suprime ovulação/menstruação, controlando dor; não restaura fertilidade enquanto é usado e não elimina de forma confiável lesões anatômicas.\nPor que as outras estão erradas:\nB: Terapias hormonais são contraceptivas e não aumentam fecundidade espontânea.\nC: Podem reduzir atividade e sintomas, mas não costumam fazer desaparecer endometrioma de 7 cm.\nD: Espessamento ligamentar fibroso não regride de modo previsível com tratamento clínico.\nPonto de prova: Objetivos e limites do tratamento clínico da endometriose.\nFlashcard sugerido:\nPergunta: O que o tratamento hormonal da endometriose consegue fazer?\nResposta: Controlar dor e reduzir recorrência de sintomas.\n\nPérola:\nHormônio controla doença; não melhora fertilidade durante o uso.\n\nArmadilha:\nPrometer redução de massa ou aumento de fertilidade com supressão hormonal.\n\n--------------------------------------------------------------------------------","tags":["Ginecologia e Obstetrícia","Ginecologia","Endometriose","Dor Pélvica","Conduta Terapêutica","Paciente Adulto"],"tagSource":"Tags.txt","globalNumber":68},{"id":"b12-endometriose-q11","number":11,"collectionBlock":12,"documentBlock":13,"area":"G.O.","topic":"Endometriose","stem":"Mulher, 30 anos de idade, apresentando episódios de tosse com sangue sincronizados com a menstruação. Tomografia de tórax mostra nódulos no pulmão. Assinale a alternativa que apresenta o diagnóstico mais provável:","options":{"A":"Tuberculose.","B":"Embolia pulmonar.","C":"Endometriose pulmonar.","D":"Quadro gripal."},"answer":"C","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (3).pdf","sourceLabel":"Endometriose","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Hemoptise catamenial, isto é, sincronizada com a menstruação, associada a nódulos pulmonares, caracteriza endometriose torácica/pulmonar.\nPor que as outras estão erradas:\nA: Tuberculose causa hemoptise e nódulos, mas não periodicidade menstrual.\nB: Embolia pulmonar é aguda e não recorre ciclicamente com a menstruação.\nD: Síndrome gripal não explica hemoptise catamenial nem nódulos.\nPonto de prova: Síndrome de endometriose torácica.\nFlashcard sugerido:\nPergunta: O que é hemoptise catamenial?\nResposta: Hemoptise recorrente durante a menstruação por endometriose pulmonar.\n\nPérola:\nSintoma torácico cíclico em mulher fértil: pense em endometriose.\n\nArmadilha:\nDesconsiderar a relação temporal com o ciclo.\n\n--------------------------------------------------------------------------------","tags":["Ginecologia e Obstetrícia","Ginecologia","Ciclo Menstrual","Tosse","Raciocínio Diagnóstico","Paciente Adulto"],"tagSource":"Tags.txt","globalNumber":128},{"id":"b12-endometriose-q12","number":12,"collectionBlock":12,"documentBlock":13,"area":"G.O.","topic":"Endometriose","stem":"O endometrioma de ovário é causado por implantes endometriais no parênquima ovariano. Em relação ao endometrioma, assinale a alternativa incorreta:","options":{"A":"A ooforectomia pode ser discutida com a paciente em casos de recorrência, endometriomas unilaterais muito grandes ou na suspeição de malignidade.","B":"Deve-se evitar múltiplas incisões e aberturas muito extensas do ovário pelo risco de dano à reserva ovariana.","C":"São complicações comuns relacionadas à videolaparoscopia para cirurgia de endometriose profunda o pneumoperitônio e perfuração de vísceras causadas por punções de agulha de Veres e trocateres.","D":"Nas pacientes com endometrioma e desejo de gestação o tratamento adequado é o tratamento hormonal com supressão ovariana e exérese cirúrgica da cápsula ovariana."},"answer":"D","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (3).pdf","sourceLabel":"Endometriose","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: Mioma totalmente intracavitário e pediculado é FIGO 0. A miomectomia histeroscópica é o tratamento conservador de escolha, sobretudo com sangramento e infertilidade.\nPor que as outras estão erradas:\nB: Histerectomia é desproporcional e elimina fertilidade.\nC: FIGO 8 corresponde a localizações não usuais, como cervical ou parasitária, não a mioma intracavitário.\nD: Embora a via histeroscópica seja correta, a classificação FIGO 8 está errada.\nPonto de prova: Classificação FIGO dos miomas submucosos.\nFlashcard sugerido:\nPergunta: Como se classifica e trata um mioma totalmente intracavitário pediculado?\nResposta: FIGO 0; miomectomia histeroscópica.\n\nPérola:\nFIGO 0 flutua na cavidade, preso apenas por pedículo.\n\nArmadilha:\nConfundir FIGO 0 com FIGO 8.\n\n--------------------------------------------------------------------------------"},{"id":"b12-endometriose-q13","number":13,"collectionBlock":12,"documentBlock":13,"area":"G.O.","topic":"Endometriose","stem":"Segundo o Guideline ESHRE de 2022, o uso de técnicas de reprodução assistida em pacientes com endometriose deve seguir:","options":{"A":"O uso prolongado de agonista de GnRH por pelo menos 3 meses antes de tratamentos de reprodução assistida é recomendado para aumentar taxas de gravidez.","B":"Pacientes com endometrioses devem ser alertadas que o uso de técnicas de reprodução assistida está associado ao aumento da recorrência da doença.","C":"Não existem evidências que mostrem superioridade do protocolo com agonistas em relação ao protocolo com antagonistas para supressão hipofisária durante estimulação ovariana em pacientes com endometriose.","D":"Pacientes com endometriose profunda se beneficiam de uso prolongado de contraceptivos hormonais antes da estimulação ovariana, já que se observa o aumento das taxas de nascido vivo."},"answer":"C","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (3).pdf","sourceLabel":"Endometriose","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: A supressão do ciclo e a indução de amenorreia com progestagênios, contraceptivos combinados contínuos ou outras terapias hormonais reduzem estímulo estrogênico e dor da endometriose.\nPor que as outras estão erradas:\nA: O diagnóstico pode ser clínico e por imagem; laparoscopia não é obrigatória, e RM não é padrão-ouro universal.\nB: A intensidade da dor não se correlaciona diretamente com número ou extensão das lesões.\nC: CA-125 não mede gravidade nem é teste diagnóstico específico.\nE: Endometrioma não constitui indicação cirúrgica absoluta; a decisão depende de tamanho, sintomas, fertilidade e suspeita de malignidade.\nPonto de prova: Princípios de tratamento clínico da endometriose.\nFlashcard sugerido:\nPergunta: Qual é o objetivo da terapia hormonal na endometriose?\nResposta: Suprimir ovulação/menstruação e induzir amenorreia para controlar sintomas.\n\nPérola:\nA extensão da endometriose não prediz a intensidade da dor.\n\nArmadilha:\nTratar todo endometrioma cirurgicamente.\n\n--------------------------------------------------------------------------------"},{"id":"b12-endometriose-q14","number":14,"collectionBlock":12,"documentBlock":13,"area":"G.O.","topic":"Endometriose","stem":"A endometriose é uma condição inflamatória crônica, estrogênio dependente, que acomete principalmente mulheres em idade reprodutiva. Caracteriza-se pela presença de tecido semelhante ao endométrio fora da cavidade uterina, com predileção pela pelve. Além dos impactos clínicos significativos, como dor pélvica intensa, dispareunia e infertilidade, estudos recentes vêm demonstrando que a endometriose pode estar associada a um risco aumentado de determinadas neoplasias. Fonte: https://www.gov.br/saude/pt br/assuntos/noticias/2025/marco/endometriose atendimentos na atenção primária do sus crescem 76,2 em tres anos a impulsionam debate. Em março de 2025, o Ministério da Saúde divulgou que os atendimentos relacionados à endometriose na atenção primária do SUS (Sistema Único de Saúde) cresceram 76,2% nos últimos três anos, ressaltando a necessidade de ampliar a conscientização sobre a doença e reforçando sua relevância como problema de saúde pública. Essa nova atenção ao tema tem impulsionado o debate sobre possíveis estratégias de vigilância em pacientes com doença moderada a grave, especialmente diante da associação epidemiológica entre endometriose e câncer. Com base nas evidências atuais sobre a associação entre endometriose e as neoplasias, assinale a alternativa CORRETA:","options":{"A":"A presença de endometriose aumenta igualmente o risco para todos os tipos histológicos de câncer epitelial de ovário, especialmente os tumores serosos de alto grau, que são os mais frequentes.","B":"A endometriose profunda com acometimento intestinal apresenta risco cerca de 3 vezes maior de câncer colorretal, sendo indicada a ressecção intestinal profilática em casos sintomáticos, conforme diretrizes atuais.","C":"As mulheres com endometriomas ovarianos, ou endometriose profunda, apresentaram risco até 9,7 vezes maior para tumores epiteliais tipo I, incluindo os subtipos endometrioide, de células claras, mucinoso e seroso de baixo grau.","D":"O risco de câncer de endométrio é cerca de 4 vezes maior em mulheres com endometriose, razão pela qual as diretrizes atuais recomendam histerectomia total em pacientes sem desejo reprodutivo com doença moderada ou grave."},"answer":"C","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (3).pdf","sourceLabel":"Endometriose","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: A taquicardia atrial geralmente apresenta QRS estreito e ritmo regular, salvo condução AV variável.\nPor que as outras estão erradas:\nA: Fibrilação atrial é irregularmente irregular.\nB: Torsades é taquicardia ventricular polimórfica de QRS largo.\nD: Taquicardia antidrômica conduz pelo feixe acessório no sentido anterógrado e costuma ter QRS largo.\nE: Flutter com bloqueio AV variável produz resposta ventricular irregular.\nPonto de prova: Classificação de taquiarritmias por largura do QRS e regularidade.\nFlashcard sugerido:\nPergunta: Qual taquiarritmia é tipicamente regular e de QRS estreito?\nResposta: Taquicardia atrial.\n\nPérola:\nQRS estreito sugere origem supraventricular, mas a regularidade diferencia os ritmos.\n\nArmadilha:\nConfundir flutter com condução fixa e flutter com bloqueio variável.\n\n--------------------------------------------------------------------------------"},{"id":"b12-endometriose-q15","number":15,"collectionBlock":12,"documentBlock":13,"area":"G.O.","topic":"Endometriose","stem":"Em relação a cirurgia de endometrioma antes da FIV, qual é a recomendação segundo o guideline ESHRE de 2022 sobre endometriose?","options":{"A":"A cirurgia deve ser evitada antes da FIV, pois pode comprometer a reserva ovariana e não melhora a taxa de nascidos vivos.","B":"A cirurgia é recomendada retirar antes da FIV, pois aumenta a taxa de fertilização.","C":"A cirurgia só é recomendada quando houver falha prévia em ciclos de FIV.","D":"A cirurgia não deve ser cogitada quando o endometrioma dificultar o acesso aos folículos durante punção ovariana."},"answer":"A","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (3).pdf","sourceLabel":"Endometriose","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Abertura controlada do trato gastrointestinal em cirurgia eletiva, sem contaminação anormal, classifica a operação como potencialmente contaminada ou limpa-contaminada.\nPor que as outras estão erradas:\nA: Cirurgia limpa não entra em tratos respiratório, digestivo, genital ou urinário.\nB: Contaminada envolve falha importante de técnica, extravasamento grosseiro ou inflamação aguda não purulenta.\nD: Suja pressupõe infecção estabelecida, víscera perfurada ou tecido desvitalizado.\nE: Infectada equivale à categoria suja/infectada e não se aplica ao acesso controlado.\nPonto de prova: Classificação das feridas operatórias por grau de contaminação.\nFlashcard sugerido:\nPergunta: Como classificar cirurgia gástrica eletiva com abertura controlada do estômago?\nResposta: Potencialmente contaminada/limpa-contaminada.\n\nPérola:\nEntrada controlada em víscera colonizada não torna a cirurgia contaminada.\n\nArmadilha:\nAssociar qualquer abertura gastrointestinal a cirurgia contaminada.\n\n--------------------------------------------------------------------------------"},{"id":"b12-endometriose-q16","number":16,"collectionBlock":12,"documentBlock":13,"area":"G.O.","topic":"Endometriose","stem":"Dentre as indicações para o tratamento cirúrgico da endometriose, qual é considerada relativa e não absoluta?","options":{"A":"Estenose ureteral pélvica, com uretero-hidronefrose ipsilateral e função renal preservada.","B":"Lesão de endometriose no apêndice cecal.","C":"Endometriose em retossigmoide, com semioclusão intestinal.","D":"Endometriose como causa única de infertilidade conjugal."},"answer":"D","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (3).pdf","sourceLabel":"Endometriose","images":["data:image/webp;base64,"],"comment":"Análise:\nCorreta: E.\nPor que está certa: Taquiarritmia associada a hipotensão grave e dor torácica caracteriza instabilidade hemodinâmica. A conduta imediata é cardioversão elétrica sincronizada, independentemente do mecanismo específico do ritmo.\nPor que as outras estão erradas:\nA: Manobras vagais são reservadas a taquicardia supraventricular regular e estável.\nB: Adenosina pode ser usada em taquicardia regular de QRS estreito estável; não deve atrasar cardioversão no instável.\nC: Amiodarona é opção em alguns ritmos estáveis ou após cardioversão, mas tem início mais lento.\nD: Deslanosídeo não é terapia de emergência para taquiarritmia instável.\nPonto de prova: Reconhecimento de instabilidade em taquiarritmias.\nFlashcard sugerido:\nPergunta: Qual a conduta na taquiarritmia com hipotensão e dor torácica?\nResposta: Cardioversão elétrica sincronizada.\n\nPérola:\nInstabilidade manda mais que o nome da arritmia.\n\nArmadilha:\nTentar tratamento farmacológico enquanto o paciente está em choque.\n\n--------------------------------------------------------------------------------"},{"id":"b12-endometriose-q17","number":17,"collectionBlock":12,"documentBlock":13,"area":"G.O.","topic":"Endometriose","stem":"A endometriose é uma doença inflamatória crônica, estrogênio-dependente, que ocasiona impacto significativo na fertilidade feminina. Os mecanismos fisiopatológicos subjacentes à infertilidade em mulheres com endometriose envolvem alterações na receptividade endometrial, comprometimento da reserva ovariana e disfunção tuboperitoneal. Diante desse contexto, assinale a alternativa CORRETA que descreve a principal característica fisiopatológica diretamente associada à redução da taxa de concepção em pacientes com endometriose:","options":{"A":"Expressão exacerbada do gene HOXA10 no epitélio endometrial eutópico, dificultando a diferenciação celular e, consequentemente, a adesão embrionária ao estroma uterino.","B":"Aumento da proporção progesterona/estrogênio na fase lútea, ocasionando hipersensibilidade endometrial à decidualização.","C":"Disfunção na permeabilidade da barreira epitelial tubária, decorrente da resposta inflamatória crônica peritoneal, interferindo na captação e no transporte do oócito.","D":"Redução da vascularização endometrial devido à inibição da angiogênese, levando à ausência de nutrição adequada para o blastocisto e impossibilitando a implantação embrionária.","E":"Aumento da produção de citocinas inflamatórias e espécies reativas de oxigênio no microambiente peritoneal, resultando em degeneração dos oócitos e inviabilizando sua fertilização."},"answer":"C","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (3).pdf","sourceLabel":"Endometriose","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: Estenose ureteral, hidronefrose, endometrioma volumoso e dor refratária configuram doença profunda com comprometimento orgânico e indicação cirúrgica terapêutica por equipe experiente.\nPor que as outras estão erradas:\nB: Biópsia isolada não resolve obstrução ureteral nem a dor e não é o objetivo da laparoscopia nesse contexto.\nC: Fertilização in vitro não corrige a hidronefrose nem o risco de dano renal.\nD: Inseminação intrauterina não trata doença profunda nem obstrução urinária.\nPonto de prova: Indicações de cirurgia na endometriose profunda.\nFlashcard sugerido:\nPergunta: Quando a endometriose profunda exige cirurgia?\nResposta: Quando há obstrução de órgão, hidronefrose, massa relevante ou dor refratária.\n\nPérola:\nEndometriose com hidronefrose é doença com risco funcional.\n\nArmadilha:\nPriorizar fertilidade sem tratar ameaça ao ureter e ao rim.\n\n--------------------------------------------------------------------------------"},{"id":"b12-endometriose-q18","number":18,"collectionBlock":12,"documentBlock":13,"area":"G.O.","topic":"Endometriose","stem":"Mulher, 32 anos de idade, apresenta dor pélvica intensa, piorando progressivamente durante a menstruação. Ultrassom pélvico mostra cisto ovariano de 3,8 cm com conteúdo aneicoico com debris no seu interior. Assinale a alternativa que indica o diagnóstico mais provável:","options":{"A":"Endometrioma.","B":"Cisto dermoide.","C":"Cisto folicular.","D":"Hidrossalpinge."},"answer":"A","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (3).pdf","sourceLabel":"Endometriose","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Diante de colapso súbito, a sequência inicial é verificar segurança, responsividade e respiração/pulso rapidamente; só depois se define RCP ou outra intervenção.\nPor que as outras estão erradas:\nA: ECG vem após avaliação inicial e estabilização.\nC: Epinefrina só é indicada após confirmar parada e iniciar RCP conforme algoritmo.\nD: Compressões começam se a pessoa estiver irresponsiva, sem respiração normal e sem pulso; isso ainda não foi checado.\nE: Avaliação especializada não precede o ABC inicial.\nPonto de prova: Primeiro passo na avaliação de colapso.\nFlashcard sugerido:\nPergunta: Qual é a primeira ação diante de uma pessoa que colapsa?\nResposta: Checar responsividade e respiração/pulso rapidamente.\n\nPérola:\nAntes de tratar uma parada, confirme a parada.\n\nArmadilha:\nPular diretamente para compressões ou medicação sem avaliação inicial.\n\n--------------------------------------------------------------------------------"},{"id":"b12-diarreia-aguda-q01","number":1,"collectionBlock":12,"documentBlock":13,"area":"Pediatria","topic":"Diarreia Aguda","stem":"A solução de reidratação oral, recomendada pela Organização Mundial da Saúde (OMS), é composta por sódio, potássio, glicose, cloro e:","options":{"A":"Cálcio.","B":"Lactato.","C":"Zinco.","D":"Magnésio.","E":"Citrato."},"answer":"E","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (4).pdf","sourceLabel":"Diarreia Aguda","images":[],"comment":"Análise:\nCorreta: E.\nPor que está certa: A solução de reidratação oral de baixa osmolaridade contém sódio, glicose, potássio, cloreto e citrato; o citrato atua como base e auxilia na correção da acidose metabólica.\nPor que as outras estão erradas:\nA: Cálcio não integra a formulação padrão.\nB: Lactato não é o tampão da SRO atual; utiliza-se citrato.\nC: Zinco é suplementação terapêutica separada, não componente da solução.\nD: Magnésio não integra a fórmula padrão.\nPonto de prova: Composição da solução de reidratação oral.\nFlashcard sugerido:\nPergunta: Quais são os componentes da SRO da OMS?\nResposta: Sódio, glicose, potássio, cloreto e citrato.\n\nPérola:\nSRO usa cotransporte sódio-glicose e citrato como base.\n\nArmadilha:\nConfundir suplementação de zinco com componente da SRO.\n\n--------------------------------------------------------------------------------","tags":["Clínica Médica","Medicina Interna","Conhecimento Conceitual","Paciente Adulto","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags.txt","globalNumber":31},{"id":"b12-diarreia-aguda-q02","number":2,"collectionBlock":12,"documentBlock":13,"area":"Pediatria","topic":"Diarreia Aguda","stem":"Um menino de 15 meses, previamente hígido e com peso de 11,0 kg, aferido há 1 semana, apresenta-se em uma unidade de pronto-atendimento com quadro de diarreia e de vômitos persistentes há 3 dias. Na última hora, já apresentou 5 episódios de vômitos de conteúdo alimentar. Ao exame físico durante a consulta, apresenta-se com peso de 10,0 kg, hipotônico, com pulsos fracos, com tempo de enchimento capilar de 3 segundos, com olhos fundos, choro sem lágrimas, e sem conseguir ingerir líquidos. Diante do quadro desse paciente, a conduta inicial e imediata do médico deve ser realizar administração endovenosa de:","options":{"A":"200 mL de cloreto de sódio a 0,9% por 20 minutos.","B":"300 mL de cloreto de sódio a 0,9% por 30 minutos.","C":"300 mL da solução de Ringer com lactato por 1 hora.","D":"200 mL da solução de Ringer com lactato por 20 minutos."},"answer":"B","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (4).pdf","sourceLabel":"Diarreia Aguda","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: A criança tem desidratação grave e não consegue beber. Para maiores de 1 ano, o Plano C inicia com 30 mL/kg de solução isotônica em 30 minutos; com peso atual de 10 kg, são 300 mL.\nPor que as outras estão erradas:\nA: 200 mL corresponde a 20 mL/kg, abaixo do esquema cobrado.\nC: O volume é correto, mas o tempo de 1 hora é usado em lactentes menores de 1 ano.\nD: 200 mL também é dose insuficiente.\nPonto de prova: Plano C por faixa etária e cálculo de volume.\nFlashcard sugerido:\nPergunta: Qual a primeira etapa do Plano C em criança >1 ano?\nResposta: 30 mL/kg de cristaloide isotônico em 30 minutos.\n\nPérola:\n>1 ano: 30 em 30; depois 70 em 2,5 horas.\n\nArmadilha:\nUsar o tempo de lactentes menores de 1 ano.\n\n--------------------------------------------------------------------------------","tags":["Pediatria","Saúde da Criança","Diarreia","Conduta Terapêutica","Pediatria Ambulatorial","Avaliação Clínica"],"tagSource":"Tags.txt","globalNumber":36},{"id":"b12-diarreia-aguda-q03","number":3,"collectionBlock":12,"documentBlock":13,"area":"Pediatria","topic":"Diarreia Aguda","stem":"Paciente de 05 anos com antecedente de encefalopatia crônica não progressiva, portador de traqueostomia e gastrostomia, apresenta quadro de diarreia há cinco dias, cerca de 10 episódios por dia. Nesse período, recebeu soro de reidratação caseiro, cerca de 200 mL, após episódios diarreicos. Foi trazido hoje ao departamento de emergência, devido à sonolência e diminuição da diurese. Na admissão, paciente apresentava choque hipotensivo, sendo iniciada expansão com soro fisiológico. Após primeira expansão, a equipe que prestava o atendimento recebeu o resultado da gasometria, descrito a seguir: * pH: 7.25; * HCO 3: 12 mmol/L; * Base Excess: -5,0 mmol/L; * Sódio: 160 mEq/L; * Potássio: 3.3 mEq/L; Na reavaliação pós-primeira expansão, paciente segue em REG, pálido, frequência cardíaca 150 bpm, FR 40 ipm e PA 76 × 42 mmHg, TEC 6 s. Assinale a alternativa correta com relação à estratégia para hidratação do paciente:","options":{"A":"Iniciar soro de reidratação oral por gastrostomia.","B":"Prosseguir expansão endovenosa com fluido isotônico.","C":"Prosseguir expansão endovenosa com soro glicosado 5%.","D":"Iniciar soro de manutenção + reposição com sódio 3 mEq/100 kcal."},"answer":"B","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (4).pdf","sourceLabel":"Diarreia Aguda","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Apesar da hipernatremia, o paciente permanece em choque após a primeira expansão. A prioridade é restaurar perfusão com cristaloide isotônico; a correção lenta do sódio vem depois da estabilização hemodinâmica.\nPor que as outras estão erradas:\nA: Via enteral não é apropriada em choque persistente.\nC: SG 5% torna-se hipotônico e não expande adequadamente o intravascular.\nD: Manutenção e reposição só devem ser calculadas após reversão do choque.\nPonto de prova: Prioridade no choque com desidratação hipernatrêmica.\nFlashcard sugerido:\nPergunta: Como expandir criança em choque e hipernatremia?\nResposta: Com cristaloide isotônico até restaurar perfusão; depois corrigir sódio lentamente.\n\nPérola:\nNo choque, perfusão primeiro; tonicidade depois.\n\nArmadilha:\nEvitar salina isotônica por medo da hipernatremia antes de reverter o choque.\n\n--------------------------------------------------------------------------------","tags":["Pediatria","Saúde da Criança","Diarreia","Choque","Conhecimento Conceitual","Urgência e Emergência"],"tagSource":"Tags.txt","globalNumber":37},{"id":"b12-diarreia-aguda-q04","number":4,"collectionBlock":12,"documentBlock":13,"area":"Pediatria","topic":"Diarreia Aguda","stem":"Menina, 7 anos, apresenta, há dois dias, febre e diarreia. Há 12 horas, o quadro piorou e surgiram febre alta, dor abdominal e sangue nas fezes, além da diarreia. Pode-se afirmar que, segundo o cartaz atualizado do Ministério da Saúde, sobre manejo do paciente com diarreia, o antibiótico melhor indicado é:","options":{"A":"Metronidazol.","B":"Azitromicina.","C":"Amoxicilina.","D":"Ciprofloxacina."},"answer":"B","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (4).pdf","sourceLabel":"Diarreia Aguda","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Disenteria com febre alta, dor abdominal e sangue nas fezes sugere infecção bacteriana invasiva, especialmente Shigella; protocolos brasileiros recentes utilizam azitromicina como escolha empírica pediátrica.\nPor que as outras estão erradas:\nA: Metronidazol é voltado a protozoários e anaeróbios, não à disenteria bacteriana típica.\nC: Amoxicilina apresenta resistência elevada e não é escolha empírica.\nD: Ciprofloxacino já foi amplamente usado, mas o protocolo citado prioriza azitromicina em crianças.\nPonto de prova: Indicação de antibiótico na diarreia aguda com disenteria.\nFlashcard sugerido:\nPergunta: Qual antibiótico empírico é indicado para disenteria infantil no protocolo citado?\nResposta: Azitromicina.\n\nPérola:\nSangue + febre alta + toxemia = pensar em disenteria bacteriana.\n\nArmadilha:\nTratar toda diarreia com antibiótico ou escolher quinolona por hábito antigo.\n\n--------------------------------------------------------------------------------","tags":["Pediatria","Saúde da Criança","Diarreia","Antimicrobianos","Conduta Terapêutica","Pediatria Ambulatorial"],"tagSource":"Tags.txt","globalNumber":43},{"id":"b12-diarreia-aguda-q05","number":5,"collectionBlock":12,"documentBlock":13,"area":"Pediatria","topic":"Diarreia Aguda","stem":"Lactente, 9 meses de idade, foi levada ao pronto-socorro por sua mãe, que relata que a filha está com diarreia há dois dias e que vomitou três vezes desde a manhã. A criança tem apresentado dificuldade para mamar e não tem urinado nas últimas 6 horas. Ao exame, a menor apresenta-se irritada, com olhos fundos, mucosas úmidas e prega cutânea que se desfaz em 8 segundos. Sem febre. Com base no grau provável de desidratação, indique o tratamento preconizado no primeiro momento no Pronto Atendimento:","options":{"A":"Administração intravenosa de solução salina normal.","B":"Início imediato de terapia de reidratação com soro oral.","C":"Observação e orientação para aumentar a ingestão de líquidos em casa.","D":"Administração de antieméticos e reavaliação."},"answer":"B","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (4).pdf","sourceLabel":"Diarreia Aguda","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Irritabilidade, olhos fundos e prega que retorna lentamente configuram desidratação, mas sem sinais claros de choque; o Plano B começa com solução de reidratação oral supervisionada.\nPor que as outras estão erradas:\nA: Solução venosa é reservada para desidratação grave, choque, íleo ou impossibilidade de via oral.\nC: Apenas orientação domiciliar corresponde ao Plano A, inadequado diante de sinais de desidratação.\nD: Antiemético pode ser adjuvante, mas não substitui reidratação.\nPonto de prova: Classificação clínica e escolha entre Planos A, B e C.\nFlashcard sugerido:\nPergunta: Qual o tratamento inicial da criança com sinais de desidratação sem choque?\nResposta: Terapia de reidratação oral supervisionada, Plano B.\n\nPérola:\nPrega lenta e olhos fundos não significam automaticamente choque.\n\nArmadilha:\nIndicar venóclise apenas porque houve redução da diurese.\n\n--------------------------------------------------------------------------------","tags":["Pediatria","Saúde da Criança","Diarreia","Síndrome Febril","Conduta Terapêutica","Primeira Infância"],"tagSource":"Tags.txt","globalNumber":48},{"id":"b12-diarreia-aguda-q06","number":6,"collectionBlock":12,"documentBlock":13,"area":"Pediatria","topic":"Diarreia Aguda","stem":"Para prevenir futuros episódios de desidratação como o descrito no caso em crianças, a mais eficaz entre as seguintes medidas é:","options":{"A":"Iniciar dieta oral e introdução progressiva de alimentos.","B":"Manter a amamentação exclusiva até pelo menos 4 meses.","C":"Aumentar a frequência das mamadas durante episódios de diarreia.","D":"Esterilizar apropriadamente mamadeiras e chupetas."},"answer":"C","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (4).pdf","sourceLabel":"Diarreia Aguda","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Durante a diarreia, manter e aumentar a frequência do aleitamento fornece água, eletrólitos, energia e fatores imunológicos, reduzindo risco de piora da desidratação.\nPor que as outras estão erradas:\nA: Manter alimentação é importante, mas a opção não especifica a medida preventiva mais diretamente eficaz durante o episódio.\nB: Aleitamento exclusivo é recomendado até 6 meses, não apenas 4.\nD: Higiene de mamadeiras reduz transmissão, mas não substitui reposição contínua de líquidos e leite durante a doença.\nPonto de prova: Prevenção de desidratação durante episódios diarreicos.\nFlashcard sugerido:\nPergunta: O que fazer com o aleitamento durante diarreia?\nResposta: Manter e aumentar a frequência das mamadas.\n\nPérola:\nDiarreia não é indicação para suspender leite materno.\n\nArmadilha:\nPrescrever pausa alimentar ou reduzir mamadas.\n\n--------------------------------------------------------------------------------","tags":["Clínica Médica","Medicina Interna","Conhecimento Conceitual","Paciente Adulto","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags.txt","globalNumber":49},{"id":"b12-diarreia-aguda-q07","number":7,"collectionBlock":12,"documentBlock":13,"area":"Pediatria","topic":"Diarreia Aguda","stem":"Uma escola pública registrou um surto de gastroenterite aguda entre seus alunos. Vários estudantes, com idades entre 6 e 12 anos, começaram a apresentar sintomas da doença, incluindo diarreia, febre, dor abdominal e vômitos. Muitas crianças apresentaram sintomas como diarreia, com até 6 dejeções por dia, sem sangue ou muco; febre, dor abdominal, com mais de 3 dias. O surto começou com alguns casos, atingindo intensidade máxima em uma semana. Algumas crianças foram hospitalizadas devido à severidade dos sintomas. A análise epidemiológica suspeitou que a fonte de infecção fosse a merenda escolar. Indique, entre as complicações potenciais da gastroenterite aguda por Salmonella em crianças, a que é mais comum e requer atenção imediata:","options":{"A":"Anemia hemolítica.","B":"Sepse.","C":"Falência hepática aguda.","D":"Síndrome hemolítico-urêmica (SHU)."},"answer":"B","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (4).pdf","sourceLabel":"Diarreia Aguda","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Salmonella pode translocar a mucosa e causar bacteremia/sepse, sobretudo em lactentes, imunocomprometidos e casos graves; essa complicação exige reconhecimento imediato.\nPor que as outras estão erradas:\nA: Anemia hemolítica não é complicação típica da salmonelose.\nC: Falência hepática aguda é rara e não é a complicação esperada.\nD: SHU associa-se principalmente a E. coli produtora de toxina Shiga e Shigella dysenteriae.\nPonto de prova: Complicações sistêmicas da gastroenterite por Salmonella.\nFlashcard sugerido:\nPergunta: Qual complicação grave deve ser vigiada na salmonelose infantil?\nResposta: Bacteremia e sepse.\n\nPérola:\nSalmonella invade; STEC causa SHU.\n\nArmadilha:\nAssociar toda diarreia sanguinolenta à SHU, independentemente do agente.\n\n--------------------------------------------------------------------------------","tags":["Pediatria","Saúde da Criança","Diarreia","Dor Abdominal","Epidemiologia Clínica","Adolescência"],"tagSource":"Tags.txt","globalNumber":50},{"id":"b12-diarreia-aguda-q08","number":8,"collectionBlock":12,"documentBlock":13,"area":"Pediatria","topic":"Diarreia Aguda","stem":"Um menino com 6 anos é levado à unidade básica de saúde devido a um quadro de diarreia intensa. Sabe-se que ele mora em uma casa sem esgotamento sanitário, e que teve contato com um tio que chegou de Moçambique há 15 dias. A criança apresenta um quadro de náuseas, diarreia líquida, leve e aquosa, sem febre. Ao exame, apresenta-se ativa, eutrófica, levemente desidratada, com temperatura de 36,5 °C. Com base nessas informações, assinale a opção que apresenta as medidas adequadas a serem tomadas na atenção primária.","options":{"A":"Reidratação endovenosa, coleta de exames tanto da criança quanto dos comunicantes e investigação de internação do tio, a fim de poder notificar a suspeita.","B":"Realização de quimioprofilaxia dos comunicantes, encaminhamento da criança ao pronto-socorro e isolamento sanitário em torno da residência dos familiares.","C":"Reidratação oral, manutenção da dieta, acompanhamento da criança, notificação e desencadeamento de ações de vigilância epidemiológica, ambiental e sanitária e investigação de comunicantes.","D":"Administração de antibióticos via oral, prescrição de medicamentos para reduzir o trânsito intestinal, indicação de dieta adequada, agendamento de retorno para o dia seguinte e notificação, caso a criança não melhore clinicamente."},"answer":"C","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (4).pdf","sourceLabel":"Diarreia Aguda","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: O quadro sugere cólera ou outra diarreia aquosa de relevância epidemiológica. Na atenção primária, deve-se reidratar por via oral, manter alimentação, notificar e acionar vigilâncias epidemiológica, ambiental e sanitária, além de investigar comunicantes.\nPor que as outras estão erradas:\nA: Desidratação leve não exige via venosa nem internação prévia do contato para permitir notificação.\nB: Quimioprofilaxia indiscriminada e cordão sanitário não são medidas rotineiras.\nD: Antimotilidade pode ser perigosa; antibiótico depende de gravidade e confirmação/suspeita, e a notificação não deve esperar falha clínica.\nPonto de prova: Manejo clínico e vigilância de suspeita de cólera.\nFlashcard sugerido:\nPergunta: Quais medidas são essenciais na suspeita de cólera na APS?\nResposta: Reidratação, manutenção da dieta, notificação e investigação epidemiológica/ambiental/sanitária.\n\nPérola:\nEm doença de notificação, vigiar não pode esperar confirmação completa.\n\nArmadilha:\nFocar só no antibiótico e esquecer reidratação e vigilância.\n\n--------------------------------------------------------------------------------","tags":["Pediatria","Saúde da Criança","Diarreia","Síndrome Febril","Interpretação de Exames","Atenção Primária"],"tagSource":"Tags.txt","globalNumber":51},{"id":"b12-diarreia-aguda-q09","number":9,"collectionBlock":12,"documentBlock":13,"area":"Pediatria","topic":"Diarreia Aguda","stem":"Pré-escolar, 4 anos, com relato de diarreia há 2 dias com fezes volumosas, várias vezes ao dia. Não aceita dieta há 12 horas (em jejum) e nesse período já apresentou 8 evacuações. Genitora levará a criança para a emergência porque a crianças apresenta os olhos encovados, sonolência e taquicardia. Para organizar um plano terapêutico, o tipo de diarreia mais provável desse paciente e o agente etiológico comumente associado são:","options":{"A":"Diarreia osmótica e Shigella.","B":"Diarreia secretória e Salmonella.","C":"Diarreia osmótica e E. coli enterotoxigênica.","D":"Diarreia secretória e Vibrio cholerae.","E":"Diarreia secretória e E. coli enteroinvasiva."},"answer":"D","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (4).pdf","sourceLabel":"Diarreia Aguda","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: Fezes volumosas que persistem mesmo em jejum sugerem mecanismo secretório. Vibrio cholerae produz enterotoxina que aumenta AMPc, promove secreção de cloro e água e causa diarreia aquosa maciça.\nPor que as outras estão erradas:\nA: Shigella causa diarreia inflamatória/invasiva, geralmente pouco volumosa e com sangue.\nB: Salmonella pode causar diarreia inflamatória, não é o exemplo clássico de secreção aquosa maciça.\nC: ETEC é secretória, não osmótica.\nE: E. coli enteroinvasiva causa síndrome disentérica/inflamatória.\nPonto de prova: Diferença entre diarreia osmótica, secretória e inflamatória.\nFlashcard sugerido:\nPergunta: Qual agente clássico causa diarreia secretória volumosa?\nResposta: Vibrio cholerae.\n\nPérola:\nSecretória não cessa com jejum; osmótica tende a melhorar.\n\nArmadilha:\nClassificar ETEC como osmótica.\n\n--------------------------------------------------------------------------------","tags":["Pediatria","Saúde da Criança","Diarreia","Conduta Terapêutica","Urgência e Emergência","Avaliação Clínica"],"tagSource":"Tags.txt","globalNumber":56},{"id":"b12-diarreia-aguda-q10","number":10,"collectionBlock":12,"documentBlock":13,"area":"Pediatria","topic":"Diarreia Aguda","stem":"Menino de 1 ano e 6 meses de idade, previamente saudável, é trazido ao pronto-socorro Infantil por sua mãe com queixa de vômitos e diarreia há 2 dias. A mãe relata diarreia líquida, sem presença de muco ou sangue, acompanhada de febre no primeiro dia do quadro e cerca de 4 a 5 episódios de vômitos ao dia. Refere que hoje a criança não tem aceitado dieta nem líquidos e que apresentou pouca diurese. Refere peso anterior de 10 Kg. Ao exame físico, a criança está em regular estado geral, sonolenta, pálida, com mucosas muito secas, olhos fundos e secos, e chorando sem lágrimas. Apresenta frequência cardíaca de 160 e peso atual de 8,7 Kg. Com base no protocolo de manejo de desidratação e diarreia do Ministério da Saúde atualizado em 2023, assinale a alternativa que corresponde à classificação da desidratação e à conduta indicada para esse paciente:","options":{"A":"Desidratação leve. Plano A – aumentar ingesta hídrica, manter alimentação habitual e orientar sinais de alarme.","B":"Desidratação moderada. Plano B – iniciar terapia de reidratação oral 50 a 100 mL/Kg em 4 a 6 horas no serviço de saúde.","C":"Desidratação moderada. Plano C – expansão inicial de 30 mL/Kg de soro fisiológico em 60 minutos, seguida de expansão de 70 mL/Kg em 5 horas.","D":"Desidratação grave. Plano C – expansão inicial de 30 mL/Kg de soro fisiológico em 30 minutos, seguida de expansão de 70 mL/Kg em 2 horas e 30 minutos.","E":"Desidratação grave. Plano C – expansão inicial de 70 mL/Kg de soro fisiológico em 30 minutos, seguida de manutenção com glicose e eletrólitos."},"answer":"D","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (4).pdf","sourceLabel":"Diarreia Aguda","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: A criança perdeu 13% do peso, está sonolenta, taquicárdica, com mucosas muito secas e incapaz de ingerir, caracterizando desidratação grave. Em maiores de 1 ano, Plano C: 30 mL/kg em 30 min e 70 mL/kg em 2,5 h.\nPor que as outras estão erradas:\nA: O quadro é muito além de leve.\nB: Plano B não é suficiente na desidratação grave.\nC: A classificação e os tempos correspondem ao esquema de menores de 1 ano, além de chamar o quadro de moderado.\nE: A ordem dos volumes está invertida e não corresponde ao protocolo.\nPonto de prova: Diagnóstico de desidratação grave e Plano C por idade.\nFlashcard sugerido:\nPergunta: Qual o Plano C para criança >1 ano?\nResposta: 30 mL/kg em 30 min, depois 70 mL/kg em 2,5 h.\n\nPérola:\nPerda ponderal >10% sugere desidratação grave.\n\nArmadilha:\nUsar apenas sinais isolados e ignorar a perda de peso.\n\n--------------------------------------------------------------------------------","tags":["Pediatria","Saúde da Criança","Diarreia","Síndrome Febril","Conduta Terapêutica","Pediatria Ambulatorial"],"tagSource":"Tags.txt","globalNumber":58},{"id":"b12-diarreia-aguda-q11","number":11,"collectionBlock":12,"documentBlock":13,"area":"Pediatria","topic":"Diarreia Aguda","stem":"Assinale a alternativa que indica o distúrbio do equilíbrio ácido-base esperado para o diagnóstico de doença diarreica aguda:","options":{"A":"Acidose metabólica de ânion gap normal.","B":"Alcalose metabólica hipoclorêmica.","C":"Acidose metabólica de ânion gap aumentado.","D":"Alcalose metabólica hiperclorêmica."},"answer":"A","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (4).pdf","sourceLabel":"Diarreia Aguda","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: A diarreia provoca perda gastrointestinal de bicarbonato; o rim retém cloreto para manter eletroneutralidade, gerando acidose metabólica hiperclorêmica com ânion gap normal.\nPor que as outras estão erradas:\nB: Alcalose hipoclorêmica é típica de vômitos persistentes.\nC: Ânion gap aumentado ocorre em lactato, cetonas, insuficiência renal e toxinas, não na perda pura de bicarbonato fecal.\nD: Alcalose hiperclorêmica não corresponde ao mecanismo.\nPonto de prova: Distúrbio ácido-base na diarreia.\nFlashcard sugerido:\nPergunta: Qual alteração ácido-base é típica da diarreia?\nResposta: Acidose metabólica hiperclorêmica com ânion gap normal.\n\nPérola:\nDiarreia perde bicarbonato; vômito perde ácido.\n\nArmadilha:\nAssociar toda acidose da desidratação a ânion gap alto.\n\n--------------------------------------------------------------------------------","tags":["Clínica Médica","Medicina Interna","Raciocínio Diagnóstico","Paciente Adulto","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags.txt","globalNumber":72},{"id":"b12-diarreia-aguda-q12","number":12,"collectionBlock":12,"documentBlock":13,"area":"Pediatria","topic":"Diarreia Aguda","stem":"Maria, 5 anos, chega acompanhada da sua mãe à emergência do hospital com quadro de diarreia há 3 dias. Pais referem episódios de fezes líquidas, sem a presença de sangue ou muco. Apresentou cerca de cinco a seis episódios nas últimas 24 horas. Não há relato de febre ou vômitos, e a aceitação da dieta está normal. Sinais vitais na chegada: Sat - 97%, Tax - 37°C, frequência respiratória - 39 rom e frequência cardíaca - 85 bpm. Ao exame físico: aspecto geral bom, mucosas úmidas e coradas. Tempo de enchimento capilar <2 segundos. Ausculta cardiopulmonar sem alterações. Abdome depressível, globoso, ruídos hidroaéreos presentes e aumentados, e dor leve à palpação. A melhor conduta nesse caso é:","options":{"A":"Internação hospitalar, coleta de exames e hidratação rápida.","B":"Internação hospitalar, estimular a hidratação oral e coletar exames.","C":"Alta para domicílio, orientando a tomar líquidos caseiros (água de arroz, soro caseiro, chá, suco e sopas) ou solução de reidratação oral (SRO) após cada evacuação diarreica.","D":"Alta hospitalar com receita de analgésicos e antieméticos.","E":"Manter em observação hospitalar até visualizar o aspecto das fezes."},"answer":"C","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (4).pdf","sourceLabel":"Diarreia Aguda","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: A criança está sem sinais de desidratação, ativa, com mucosas úmidas e perfusão normal. O Plano A é domiciliar: líquidos/SRO após cada evacuação, manutenção da dieta e orientação de sinais de alarme.\nPor que as outras estão erradas:\nA: Não há indicação de internação ou hidratação rápida.\nB: Observação hospitalar e exames não são necessários em caso não complicado.\nD: Analgésicos/antieméticos não são a base do tratamento e a orientação hídrica é indispensável.\nE: Não é necessário observar o aspecto das fezes em hospital para definir a conduta.\nPonto de prova: Plano A da diarreia aguda.\nFlashcard sugerido:\nPergunta: Como tratar diarreia aguda sem desidratação?\nResposta: Plano A: líquidos e SRO após evacuações, alimentação mantida e retorno se alarme.\n\nPérola:\nSem desidratação, o tratamento é em casa com orientação clara.\n\nArmadilha:\nInternar pelo número de evacuações apesar do exame normal.\n\n--------------------------------------------------------------------------------","tags":["Pediatria","Saúde da Criança","Diarreia","Síndrome Febril","Conduta Terapêutica","Urgência e Emergência"],"tagSource":"Tags.txt","globalNumber":74},{"id":"b12-diarreia-aguda-q13","number":13,"collectionBlock":12,"documentBlock":13,"area":"Pediatria","topic":"Diarreia Aguda","stem":"Lactente com 10 meses de vida, peso atual de 10 kg, admitido em emergência pediátrica com desidratação grave por gastroenterite aguda. Pediatra de plantão decide instituir o Plano Terapêutico C. de acordo com as diretrizes mais recentes do Ministério da Saúde. Dessa forma, qual volume total de Soro Fisiológico 0,9% deverá ser infundido nessa criança em toda a fase de expansão, a qual ocorrerá em 6 horas?","options":{"A":"100 ml.","B":"200 ml.","C":"400 ml.","D":"600 ml.","E":"1.000 ml."},"answer":"E","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (4).pdf","sourceLabel":"Diarreia Aguda","images":[],"comment":"Análise:\nCorreta: E.\nPor que está certa: No Plano C, o volume total é 100 mL/kg de cristaloide isotônico. Para 10 kg, o total é 1.000 mL, administrado conforme a faixa etária.\nPor que as outras estão erradas:\nA: 100 mL é apenas 10 mL/kg.\nB: 200 mL equivale a 20 mL/kg.\nC: 400 mL equivale a 40 mL/kg.\nD: 600 mL equivale a 60 mL/kg.\nPonto de prova: Cálculo do volume total do Plano C.\nFlashcard sugerido:\nPergunta: Qual o volume total do Plano C?\nResposta: 100 mL/kg.\n\nPérola:\nPlano C completo = 30 + 70 = 100 mL/kg.\n\nArmadilha:\nResponder apenas o volume da primeira etapa.\n\n--------------------------------------------------------------------------------","tags":["Pediatria","Saúde da Criança","Conduta Terapêutica","Primeira Infância","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags.txt","globalNumber":75},{"id":"b12-diarreia-aguda-q14","number":14,"collectionBlock":12,"documentBlock":13,"area":"Pediatria","topic":"Diarreia Aguda","stem":"Lactente, 10 meses de vida, apresenta quadros de diarreia e também vômitos há 4 dias. FC 130 bpm; FR 40; afebril; sat 97% aa; PA 80 × 60 mmHg. O lactente apresenta estado regular de forma geral, chora sem lágrimas; mucosa seca; sinal da prega desce lentamente e bebe água avidamente. Peso 10 kg. O manejo adequado da diarreia para esse paciente deve ser:","options":{"A":"Expansão endovenosa com soro fisiológico 0,9% 30 ml/kg em 1 hora.","B":"Hidratação via oral 75 ml/kg para ser administrada em 4 horas.","C":"Hidratação via oral 50 ml/kg para ser administrada em 2 horas.","D":"Expansão endovenosa com soro fisiológico 0,9% 30 ml/kg em 30 minutos.","E":"Expansão endovenosa com soro fisiológico 0,9% 70 ml/kg em 5 horas."},"answer":"B","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (4).pdf","sourceLabel":"Diarreia Aguda","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Irritabilidade, sede intensa, ausência de lágrimas, mucosa seca e prega lenta indicam desidratação sem choque. O Plano B usa SRO, usualmente 50–100 mL/kg em 4–6 horas; a alternativa de 75 mL/kg em 4 horas é compatível.\nPor que as outras estão erradas:\nA: Expansão EV de 30 mL/kg é Plano C, reservada à desidratação grave.\nC: 50 mL/kg em 2 horas pode ser insuficiente e não corresponde ao esquema da banca.\nD: 30 mL/kg em 30 minutos é primeira fase do Plano C para >1 ano.\nE: 70 mL/kg em 5 horas é segunda fase do Plano C em menores de 1 ano.\nPonto de prova: Reconhecimento do Plano B e dose da TRO.\nFlashcard sugerido:\nPergunta: Qual volume de SRO é usado no Plano B?\nResposta: Cerca de 50–100 mL/kg em 4–6 horas sob supervisão.\n\nPérola:\nSede intensa com perfusão preservada costuma ser Plano B.\n\nArmadilha:\nTransformar todo sinal de desidratação em indicação venosa.\n\n--------------------------------------------------------------------------------","tags":["Pediatria","Saúde da Criança","Diarreia","Conduta Terapêutica","Primeira Infância","Avaliação Clínica"],"tagSource":"Tags.txt","globalNumber":77},{"id":"b12-diarreia-aguda-q15","number":15,"collectionBlock":12,"documentBlock":13,"area":"Pediatria","topic":"Diarreia Aguda","stem":"Qual a classe de antimicrobiano a seguir está relacionada a colite pseudomembranosa em crianças?","options":{"A":"Quinolonas.","B":"Lincosamidas.","C":"Glicopeptídeos.","D":"Aminoglicosídeo.","E":"Penicilinas."},"answer":"B","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (4).pdf","sourceLabel":"Diarreia Aguda","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: A clindamicina, uma lincosamida, é classicamente associada à disbiose intestinal e colite por Clostridioides difficile.\nPor que as outras estão erradas:\nA: Quinolonas também aumentam risco de C. difficile, mas a associação clássica cobrada é clindamicina.\nC: Glicopeptídeos como vancomicina oral tratam C. difficile.\nD: Aminoglicosídeos têm baixa relação com colite pseudomembranosa.\nE: Algumas penicilinas podem predispor, porém não são a associação prototípica.\nPonto de prova: Antibióticos associados à colite por C. difficile.\nFlashcard sugerido:\nPergunta: Qual classe tem associação clássica com colite pseudomembranosa?\nResposta: Lincosamidas, especialmente clindamicina.\n\nPérola:\nClindamicina é a droga clássica da colite pseudomembranosa.\n\nArmadilha:\nMarcar qualquer antibiótico de amplo espectro sem identificar a associação clássica.\n\n--------------------------------------------------------------------------------","tags":["Clínica Médica","Medicina Interna","Antimicrobianos","Conhecimento Conceitual","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags.txt","globalNumber":78},{"id":"b12-diarreia-aguda-q16","number":16,"collectionBlock":12,"documentBlock":13,"area":"Pediatria","topic":"Diarreia Aguda","stem":"Paciente de 11 meses de idade, em aleitamento materno e dieta geral, comparece ao pronto-socorro acompanhado da mãe, com queixa de diarreia há 3 dias, com cerca de 4 evacuações líquidas ao dia, sem conteúdos patológicos. Ao exame, o paciente encontra-se ativo e reativo, mucosas úmidas e choro com lágrimas e pulsos cheios. Qual a conduta a ser orientada para esse paciente em relação a hidratação e alimentação:","options":{"A":"Reposição de 50 a 100 ml/kg em 4 a 6 horas, oferecendo solução de reidratação oral em pequenos volumes sob supervisão de profissional da saúde. Introdução de dieta obstipante.","B":"Hidratação endovenosa com fase rápida (expansão). Durante o período de reidratação, não alimentar a criança, exceto o aleitamento materno","C":"Orientar aumentar a ingesta hídrica e, após cada evacuação diarreica, oferecer 100 a 200 ml de solução de reidratação oral. Dieta adequada para a idade, com alto valor nutricional.","D":"Orientar aumentar a ingesta hídrica e, após cada evacuação diarreica, oferecer 50 a 100ml de solução de reidratação oral. Dieta adequada para a idade, com alto valor nutricional."},"answer":"D","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (4).pdf","sourceLabel":"Diarreia Aguda","images":["data:image/webp;base64,"],"comment":"Análise:\nCorreta: D.\nPor que está certa: A criança não apresenta sinais de desidratação. No Plano A, menores de 1 ano recebem 50–100 mL de SRO após cada evacuação, mantendo aleitamento e alimentação adequada à idade.\nPor que as outras estão erradas:\nA: 50–100 mL/kg em 4–6 horas é Plano B, e dieta obstipante não é recomendada.\nB: Não há indicação de hidratação EV nem jejum.\nC: 100–200 mL após evacuação corresponde a crianças maiores de 1 ano.\nPonto de prova: Volume de SRO no Plano A por idade.\nFlashcard sugerido:\nPergunta: Quanto oferecer de SRO após evacuação em menores de 1 ano?\nResposta: 50–100 mL.\n\nPérola:\n<1 ano: 50–100 mL; 1–10 anos: 100–200 mL.\n\nArmadilha:\nConfundir volume por evacuação com volume por kg do Plano B.\n\n--------------------------------------------------------------------------------","tags":["Clínica Médica","Gastroenterologia","Aleitamento Materno","Diarreia","Conduta Terapêutica","Urgência e Emergência"],"tagSource":"Tags.txt","globalNumber":81},{"id":"b12-diarreia-aguda-q17","number":17,"collectionBlock":12,"documentBlock":13,"area":"Pediatria","topic":"Diarreia Aguda","stem":"Você atende um pré-escolar de 4 anos de idade com relato de múltiplas evacuações líquidas de odor fétido, com coloração amarela e sem presença de sangue ou catarro. O quadro começou na madrugada do dia anterior, associado a vômito e baixa aceitação de alimentos sólidos, com boa aceitação de líquidos. Ao exame, a paciente encontra-se alerta e orientada, mucosa oral com saliva fluida, extremidades com pulsos cheios e simétricos, tempo de enchimento capilar de 2 segundos. Qual é a conduta a seguir?","options":{"A":"Recomendar maior ingesta de líquidos e, após cada evacuação diarreica, oferecer soro de reidratação oral 100-200mL. Iniciar suplementação com zinco e orientar sinais de alarme.","B":"Recomendar maior ingesta de líquidos e, após cada evacuação diarreica, oferecer soro de reidratação oral 50mL. Iniciar suplementação com zinco e orientar sinais de alarme.","C":"Pesar a criança e iniciar terapia de reidratação oral supervisionada na unidade.","D":"Pesar a criança e realizar expansão volêmica com soro fisiológico imediatamente."},"answer":"A","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (4).pdf","sourceLabel":"Diarreia Aguda","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: A criança está sem desidratação. Com 4 anos, deve receber 100–200 mL de SRO após cada evacuação, manter líquidos e alimentação, usar zinco conforme protocolo e receber orientação de sinais de alarme.\nPor que as outras estão erradas:\nB: 50 mL é volume baixo para essa faixa etária.\nC: TRO supervisionada é Plano B e não há sinais de desidratação.\nD: Expansão venosa é reservada para choque/desidratação grave.\nPonto de prova: Plano A e reposição por evacuação.\nFlashcard sugerido:\nPergunta: Quanto de SRO oferecer a criança de 4 anos após cada evacuação?\nResposta: 100–200 mL.\n\nPérola:\nSem desidratação: repor perdas em casa, não expandir.\n\nArmadilha:\nBasear a conduta na aparência das fezes, ignorando perfusão e hidratação.\n\n--------------------------------------------------------------------------------","tags":["Pediatria","Saúde da Criança","Conduta Terapêutica","Pediatria Ambulatorial","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags.txt","globalNumber":84},{"id":"b12-diarreia-aguda-q18","number":18,"collectionBlock":12,"documentBlock":13,"area":"Pediatria","topic":"Diarreia Aguda","stem":"Um lactente, masculino, de um ano e seis meses, é trazido pela mãe a unidade básica de saúde com história de diarreia intensa há 4 dias. A mãe relata eliminações explosivas, fétidas e volumosas, sem presença de muco, pus ou sangue. Nega febre. Há dois dias, evoluiu com irritabilidade, choro intenso e recusa parcial da dieta. Há um dia, a mãe relata que o menor está sedento, ingerindo rapidamente todo o volume de água ofertado. Ao exame se apresentava irritado e choroso. Lágrimas ausentes e olhos fundos. Desaparecimento lento do sinal da prega. Temperatura axilar: 37°C; frequência respiratória: 25 irpm; frequência cardíaca: 100 bpm; e saturando a 99% em ar ambiente. Em relação ao paciente descrito, assinale a alternativa que CORRETAMENTE descreve o quadro e indica o tratamento:","options":{"A":"Sem sinais de desidratação. Ofertar Solução de Reidratação Oral (SRO), 100-200 ml, após cada evacuação diarreica.","B":"Quadro de desidratação grave, sendo indicada fase rápida com soro fisiológico 0,9% (20 ml/kg). Repetir essa quantidade até que a criança esteja hidratada.","C":"Quadro de desidratação, sendo indicada administração da solução de reidratação oral, 50-100 ml/kg, durante o período de 4-6 horas, em unidade de saúde.","D":"Quadro de desidratação, sendo indicada administração da solução de reidratação oral, 50-100 ml/kg, durante o período de 4-6 horas em unidade de saúde. Se desaparecerem os sinais de desidratação, indicar gastróclise."},"answer":"C","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (4).pdf","sourceLabel":"Diarreia Aguda","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Sede intensa, irritabilidade, ausência de lágrimas, olhos fundos e prega lenta indicam desidratação sem choque. A conduta é Plano B com SRO 50–100 mL/kg em 4–6 horas na unidade.\nPor que as outras estão erradas:\nA: Há vários sinais de desidratação, portanto não é Plano A.\nB: Não há sinais de choque ou desidratação grave que justifiquem expansão rápida.\nD: A primeira parte é correta, mas gastróclise não é indicada se os sinais desaparecerem e a criança aceita via oral.\nPonto de prova: Classificação e tratamento da desidratação moderada.\nFlashcard sugerido:\nPergunta: Qual o tratamento da criança sedenta, irritada, com olhos fundos e prega lenta?\nResposta: Plano B com SRO supervisionada.\n\nPérola:\nPlano B termina com reavaliação; não com sonda automática.\n\nArmadilha:\nEscolher alternativa quase correta sem notar a conduta final errada.\n\n--------------------------------------------------------------------------------","tags":["Pediatria","Saúde da Criança","Diarreia","Síndrome Febril","Conduta Terapêutica","Primeira Infância"],"tagSource":"Tags.txt","globalNumber":85},{"id":"b12-diarreia-aguda-q19","number":19,"collectionBlock":12,"documentBlock":13,"area":"Pediatria","topic":"Diarreia Aguda","stem":"Uma escola pública registrou um surto de gastroenterite aguda entre seus alunos. Vários estudantes, com idades entre 6 e 12 anos, começaram a apresentar sintomas da doença, incluindo diarreia, febre, dor abdominal e vômitos. Muitas crianças apresentaram sintomas como diarreia, com até 6 dejeções por dia, sem sangue ou muco; febre, dor abdominal, com mais de 3 dias. O surto começou com alguns casos, atingindo intensidade máxima em uma semana. Algumas crianças foram hospitalizadas devido à severidade dos sintomas. A análise epidemiológica suspeitou que a fonte de infecção fosse a merenda escolar. Indique, entre os seguintes fatores, o mais provável que tenha contribuído para o surto de gastroenterite por Salmonella na escola:","options":{"A":"Consumo de alimentos crus ou mal cozidos na merenda escolar.","B":"Falta de vacinação adequada nos alunos.","C":"Contato com funcionários da cantina carreadores da bactéria.","D":"Consumo de água não filtrada na escola."},"answer":"A","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (4).pdf","sourceLabel":"Diarreia Aguda","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: Salmonella é frequentemente transmitida por ovos, carnes, leite e outros alimentos crus ou mal cozidos; em surto vinculado à merenda, falha de cocção/manipulação é a hipótese mais provável.\nPor que as outras estão erradas:\nB: Não há vacinação rotineira contra salmonelose não tifoide para escolares.\nC: Portadores podem transmitir, mas a fonte alimentar é mais provável no cenário descrito.\nD: Água contaminada pode transmitir enteropatógenos, porém a investigação apontou merenda e Salmonella.\nPonto de prova: Epidemiologia da salmonelose alimentar.\nFlashcard sugerido:\nPergunta: Qual exposição clássica causa surto de Salmonella?\nResposta: Alimentos de origem animal crus ou mal cozidos, especialmente ovos e aves.\n\nPérola:\nSalmonella é, antes de tudo, doença transmitida por alimentos.\n\nArmadilha:\nEscolher falta de vacina para uma doença sem vacina infantil rotineira.\n\n--------------------------------------------------------------------------------","tags":["Pediatria","Saúde da Criança","Diarreia","Dor Abdominal","Raciocínio Diagnóstico","Adolescência"],"tagSource":"Tags.txt","globalNumber":86},{"id":"b12-diarreia-aguda-q20","number":20,"collectionBlock":12,"documentBlock":13,"area":"Pediatria","topic":"Diarreia Aguda","stem":"Durante uma ação de saúde em uma comunidade ribeirinha, você é chamado para avaliar uma criança de 11 meses que apresenta diarreia há dois dias e três episódios de vômitos desde a manhã. A mãe relata que o bebê tem mamado menos e não urina há cerca de 6 horas. Ao exame, a criança está irritada, com olhos fundos e prega cutânea que se desfaz lentamente (cerca de 6 segundos). Não há febre. Com base no caso clínico, indique o grau mais provável de desidratação que a criança apresenta:","options":{"A":"Desidratação leve.","B":"Desidratação moderada.","C":"Desidratação grave.","D":"Sem sinais de desidratação."},"answer":"B","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (4).pdf","sourceLabel":"Diarreia Aguda","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Irritabilidade, olhos fundos e prega que retorna lentamente configuram desidratação moderada/alguma desidratação. A ausência de choque ou incapacidade absoluta de beber afasta desidratação grave.\nPor que as outras estão erradas:\nA: Há mais do que sinais leves.\nC: Desidratação grave exige sinais como letargia, incapacidade de beber, pulso muito fraco ou choque.\nD: O exame mostra sinais objetivos de desidratação.\nPonto de prova: Classificação clínica da desidratação.\nFlashcard sugerido:\nPergunta: Quais sinais sugerem desidratação moderada?\nResposta: Irritabilidade, olhos fundos, sede e prega cutânea lenta.\n\nPérola:\nDois ou mais sinais do grupo intermediário apontam Plano B.\n\nArmadilha:\nUsar oligúria isoladamente para classificar como grave.\n\n--------------------------------------------------------------------------------","tags":["Pediatria","Saúde da Criança","Diarreia","Síndrome Febril","Raciocínio Diagnóstico","Pediatria Ambulatorial"],"tagSource":"Tags.txt","globalNumber":88},{"id":"b12-diarreia-aguda-q21","number":21,"collectionBlock":12,"documentBlock":13,"area":"Pediatria","topic":"Diarreia Aguda","stem":"Escolar, cinco anos, é levado à emergência com história de diarreia há dois dias, cinco episódios nas últimas 24 horas, sendo os dois mais recentes com sangue e muco. Hoje ele apresenta febre alta, dor abdominal e dor ao evacuar. Ao exame, hidratado, com queda do estado geral, olhos normais e turgor preservado. Nega doenças anteriores. Segundo o Ministério da Saúde do Brasil, o antimicrobiano de escolha a ser usado é:","options":{"A":"A azitromicina.","B":"A nitazoxanida.","C":"O ciprofloxacino.","D":"A penicilina benzatina.","E":"Amoxicilina clavulanato."},"answer":"A","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (4).pdf","sourceLabel":"Diarreia Aguda","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: Disenteria com febre alta e tenesmo sugere Shigella ou outro agente invasivo. O protocolo citado recomenda azitromicina como antimicrobiano de escolha na criança.\nPor que as outras estão erradas:\nB: Nitazoxanida é antiparasitário e não trata a maioria das disenterias bacterianas.\nC: Ciprofloxacino é alternativa em alguns protocolos/resistências, mas não a primeira escolha indicada pelo documento citado.\nD: Penicilina benzatina não atua nos enteropatógenos do quadro.\nE: Amoxicilina-clavulanato não é esquema empírico padrão para disenteria.\nPonto de prova: Tratamento antimicrobiano da disenteria pediátrica.\nFlashcard sugerido:\nPergunta: Qual antibiótico é escolhido para disenteria infantil no protocolo brasileiro citado?\nResposta: Azitromicina.\n\nPérola:\nDiarreia aquosa não recebe antibiótico de rotina; disenteria toxêmica pode receber.\n\nArmadilha:\nDar antiparasitário apenas por haver diarreia.\n\n--------------------------------------------------------------------------------","tags":["Cirurgia","Trauma","Diarreia","Antimicrobianos","Interpretação de Exames","Urgência e Emergência"],"tagSource":"Tags.txt","globalNumber":110},{"id":"b12-diarreia-aguda-q22","number":22,"collectionBlock":12,"documentBlock":13,"area":"Pediatria","topic":"Diarreia Aguda","stem":"Um pediatra atende uma criança de 2 anos com diagnóstico de diarreia aguda aquosa, classificada como Plano A. Além da terapia de reidratação oral e manutenção da dieta, o médico avalia o uso de terapias coadjuvantes. Determine a conduta correta em relação ao uso de antieméticos e probióticos:","options":{"A":"Os antieméticos, como a Ondansetrona, não são recomendados pela OMS, mas a ESPGHAN considera seu uso para reduzir a frequência de vômitos.","B":"A OMS e o Ministério da Saúde (MS) do Brasil recomendam formalmente o uso de probióticos, como o Lactobacillus GG, para reduzir as perdas diarreicas.","C":"A Loperamida é contraindicada, mas a Racecadotrila pode ser usada em menores de 3 meses para diminuir a motilidade intestinal.","D":"O uso de antibióticos está indicado em todos os casos de diarreia aquosa para diminuir a duração do quadro, assim como os probióticos.","E":"A ESPGHAN e a diretriz IberoLatinoamericana não recomendam probióticos, pois não há demonstração de que eles diminuam as perdas diarreicas."},"answer":"A","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (4).pdf","sourceLabel":"Diarreia Aguda","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: O quadro é típico de adenomiose sintomática em mulher de 44 anos, multípara e sem desejo reprodutivo explicitado. Entre as opções, a histerectomia é o tratamento definitivo; a alternativa disponível é subtotal.\nPor que as outras estão erradas:\nA: Danazol tem efeitos adversos androgênicos e não é tratamento de escolha atual.\nC: Análogo de GnRH pode reduzir sintomas temporariamente, mas não é estratégia definitiva e causa hipoestrogenismo.\nD: Embolização pode ser considerada em casos selecionados, porém a resposta na adenomiose é variável e não é a opção mais definitiva.\nPonto de prova: Tratamento definitivo da adenomiose.\nFlashcard sugerido:\nPergunta: Qual é o tratamento definitivo da adenomiose em mulher sem desejo gestacional?\nResposta: Histerectomia.\n\nPérola:\nAdenomiose termina no miométrio; retirar o útero é definitivo.\n\nArmadilha:\nEscolher terapia temporária em doença sintomática importante sem desejo reprodutivo.\n\n--------------------------------------------------------------------------------"},{"id":"b12-diarreia-aguda-q23","number":23,"collectionBlock":12,"documentBlock":13,"area":"Pediatria","topic":"Diarreia Aguda","stem":"Paciente de 5 anos, sexo feminino, trazida à UBS por quadro de diarreia há 03 dias, cerca de 10 episódios ao dia. Há 01 dia, evoluiu com vômitos. Acompanhante relata recusa alimentar persistente, mantendo ingesta hídrica. Diurese reduzida, com último episódio há 08 horas. Em última consulta, peso de 20 kg. Ao exame físico, paciente irritado, com olhos fundos, sinal da prega com desaparecimento lento, pulsos cheios, peso de 19 kg. Diante do quadro apresentado, assinale a alternativa compatível com a conduta adequada:","options":{"A":"Estamos diante de um quadro de diarreia aguda, tratável pelo plano C. Devemos realizar expansão volêmica com cristaloides a 30mL/kg em 30 min. Após, realizar 70 ml/kg por 2,5h.","B":"Estamos diante de um quadro de diarreia aguda, tratável pelo plano B. Devemos ofertar TRO em unidade de saúde na dose de 50 a 100 mL/kg em quatro a seis horas. Nessa situação, temos um paciente com desidratação, devendo permanecer na unidade até a reidratação completa.","C":"Estamos diante de um quadro de diarreia aguda, tratável pelo plano A. A condução do caso é realizada no domicílio. Orienta- se aumento da ingestão de água e outros líquidos.","D":"Estamos diante de um quadro de diarreia aguda, tratável pelo plano C. Devemos realizar expansão volêmica com cristaloides a 20mL/kg em 30 min."},"answer":"B","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (4).pdf","sourceLabel":"Diarreia Aguda","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Irritabilidade, olhos fundos e prega lenta, com pulsos cheios, indicam desidratação sem choque. O Plano B usa SRO 50–100 mL/kg em 4–6 horas na unidade até reidratação.\nPor que as outras estão erradas:\nA: Plano C é para desidratação grave e a criança não apresenta choque.\nC: Plano A é para ausência de sinais de desidratação.\nD: 20 mL/kg em bolus não é o esquema padrão do Plano C cobrado e seria excessivo para este quadro.\nPonto de prova: Escolha do plano de hidratação.\nFlashcard sugerido:\nPergunta: Qual plano para criança irritada, olhos fundos e prega lenta, mas pulsos cheios?\nResposta: Plano B.\n\nPérola:\nPerfusão preservada com sinais intermediários = TRO supervisionada.\n\nArmadilha:\nUsar redução da diurese como único critério de Plano C.\n\n--------------------------------------------------------------------------------","tags":["Pediatria","Saúde da Criança","Diarreia","Conduta Terapêutica","Atenção Primária","Avaliação Clínica"],"tagSource":"Tags.txt","globalNumber":109},{"id":"b12-diarreia-aguda-q24","number":24,"collectionBlock":12,"documentBlock":13,"area":"Pediatria","topic":"Diarreia Aguda","stem":"Uma criança de três anos de idade foi atendida no pronto-socorro, com quadro de diarreia (cerca de quatro episódios de fezes amolecidas por dia) há dois dias. Hoje, iniciou-se, associado à diarreia, o quadro de vômitos (cerca de três episódios até o momento). Ao se avaliar a criança, ela apresentava-se irritada, com olhos fundos. Por outro lado, aceitou bem ingerir água e estava com o pulso presente e cheio. Mucosa oral seca e sinal da prega um pouco lentificado. Com base nessa situação hipotética, é correto afirmar que:","options":{"A":"Não há sinais de desidratação, é necessário prescrever solução de reidratação para casa, seguindo todos os passos do plano A de tratamento.","B":"Há sinais de desidratação grave. É necessário, então, fazer reposição volêmica por via endovenosa. Deve-se seguir o plano C de tratamento.","C":"O uso de medicações antieméticas está contraindicado para essa faixa etária.","D":"Há sinais de desidratação. Logo, pode-se prescrever uma solução de hidratação oral e zinco, além de orientar sobre os sinais de alarme para mãe e encaminhar para casa.","E":"Há sinais de desidratação e, por isso, é necessário tentar fazer solução de reidratação oral e manter a criança em observação para avaliar a resposta seguindo o plano B de tratamento."},"answer":"E","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (4).pdf","sourceLabel":"Diarreia Aguda","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: A ressonância magnética oferece maior campo de visão e melhor definição do número, tamanho, localização e relação dos miomas com endométrio e serosa, sendo o método mais sensível para mapeamento pré-operatório complexo.\nPor que as outras estão erradas:\nA: Ultrassonografia pélvica é menos sensível, sobretudo em úteros volumosos.\nB: Ultrassonografia transvaginal é excelente primeira linha, mas pode perder nódulos numerosos ou altos.\nC: Tomografia tem menor contraste de partes moles e não é método de escolha.\nPonto de prova: Escolha do exame para mapeamento de miomas.\nFlashcard sugerido:\nPergunta: Qual exame melhor mapeia miomas antes de miomectomia?\nResposta: Ressonância magnética da pelve.\n\nPérola:\nUS diagnostica; RM mapeia com maior precisão.\n\nArmadilha:\nConfundir exame inicial com exame mais sensível para planejamento.\n\n--------------------------------------------------------------------------------"},{"id":"b12-diarreia-aguda-q25","number":25,"collectionBlock":12,"documentBlock":13,"area":"Pediatria","topic":"Diarreia Aguda","stem":"Lactente de 9 meses com quadro de diarreia aguda há 3 dias, acompanhada de vômitos pontuais e febre baixa. Ao exame físico, a criança apresenta sinais de desidratação, com mucosas ressecadas, olhos fundos, leve diminuição da elasticidade da pele. Restante do exame: FC = 148 bpm, PA:100 × 55 (74)mm/dl, pulsos cheios, presença de lágrimas, fontanela anterior normotensa. Com base nas diretrizes do ministério da saúde para manejo da desidratação na criança com diarreia, qual é a conduta inicial mais apropriada para esse caso?","options":{"A":"Iniciar terapia de reidratação oral e monitorar a resposta clínica.","B":"Iniciar reidratação intravenosa imediatamente com soro fisiológico ou ringer lactato.","C":"Solicitar exames laboratoriais para avaliar eletrólitos e função renal antes de iniciar qualquer intervenção.","D":"Solicitar exames laboratoriais para avaliar eletrólitos e função renal e iniciar reidratação intravenosa com soro fisiológico e soro glicosado 5% em partes iguais.","E":"Iniciar reidratação intravenosa com soro glicosado 5% e soro fisiológico em partes iguais."},"answer":"A","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (4).pdf","sourceLabel":"Diarreia Aguda","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Os achados sugerem adenomiose associada a pequeno mioma intramural, sem deformação cavitária relevante. Como há desejo reprodutivo, deve-se evitar procedimentos que prejudiquem útero ou reserva; anti-inflamatório controla dismenorreia sem impedir tentativa de gestação.\nPor que as outras estão erradas:\nA: Miomectomia de nódulo intramural de 3 cm sem impacto cavitário não traz benefício reprodutivo claro e não trata adenomiose.\nB: Embolização não é preferida em mulher que deseja gestar devido a efeitos uterinos e obstétricos.\nD: Mioma intramural não é acessível por histeroscopia; FIV não é automaticamente necessária.\nE: GnRH e cirurgia seguida de FIV são excessivos sem avaliação de infertilidade.\nPonto de prova: Tratamento conservador de adenomiose/mioma em mulher com desejo reprodutivo.\nFlashcard sugerido:\nPergunta: Como controlar dismenorreia em paciente que deseja engravidar e não tem mioma cavitário relevante?\nResposta: Anti-inflamatório não hormonal.\n\nPérola:\nPreserve fertilidade: não opere mioma pequeno sem impacto cavitário.\n\nArmadilha:\nIndicar miomectomia apenas porque existe um nódulo.\n\n--------------------------------------------------------------------------------"},{"id":"b12-diarreia-aguda-q26","number":26,"collectionBlock":12,"documentBlock":13,"area":"Pediatria","topic":"Diarreia Aguda","stem":"Menino, 18m, previamente saudável, está há um dia com diarreia aquosa (seis evacuações nas últimas 24h), sem sangue, sem vômitos persistentes. Aceita líquidos e alimentos e está alerta, com sinais vitais estáveis e mucosas úmidas. A CONDUTA É:","options":{"A":"Oferecer 200 mL a 300 mL de líquidos caseiros com glicose, após cada evacuação; evitar o leite materno temporariamente e prescrever 5 mg/dia de zinco por 5 dias.","B":"Iniciar antibiótico empírico com azitromicina (10 mg/kg/dia) ou ceftriaxona (50 mg/kg/dia) até resultado de coprocultura. Manter aleitamento materno e alimentação habitual até melhora.","C":"Prescrever jejum, iniciar suporte hídrico venoso e aguardar estabilização clínica antes de iniciar dieta por via oral.","D":"Oferecer 100 mL a 200 mL de líquidos após cada evacuação, manter aleitamento materno e alimentação habitual, prescrever 20 mg/dia de zinco por 10–14 dias."},"answer":"D","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (4).pdf","sourceLabel":"Diarreia Aguda","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Endometriose ovariana associa-se principalmente aos carcinomas endometrioide e de células claras; entre as alternativas, células claras é a correta.\nPor que as outras estão erradas:\nA: Carcinoma mucinoso não é a associação clássica.\nB: Carcinoma seroso de alto grau está mais relacionado à tuba e mutações BRCA.\nD: Tumor de células da granulosa é neoplasia estromal, não derivada de endometriose.\nE: Sertoli-Leydig também é tumor estromal/cordões sexuais.\nPonto de prova: Transformação maligna da endometriose.\nFlashcard sugerido:\nPergunta: Quais carcinomas ovarianos se associam à endometriose?\nResposta: Endometrioide e de células claras.\n\nPérola:\nEndometriose + câncer: pense em endometrioide e células claras.\n\nArmadilha:\nEscolher o tipo epitelial mais comum do ovário em vez do mais associado à endometriose.\n\n--------------------------------------------------------------------------------"},{"id":"b12-diarreia-aguda-q27","number":27,"collectionBlock":12,"documentBlock":13,"area":"Pediatria","topic":"Diarreia Aguda","stem":"Mãe procura pronto atendimento com seu filho de 6 anos de idade, com a queixa de início de diarréia e vômitos iniciados há 24 horas, já com 10 episódios desde então, sem saída de sangue ou muco. Paciente previamente hígido, com vacinas atualizadas, sem internações prévias. Traz relato de ter sido comunicada pela escola de quadros semelhantes em outros alunos. Ao exame físico, paciente irritado, descorado 1+/4+, desidratado, afebril, eupneico. Presença de olhos fundos e boca seca. Extremidades bem perfundidas, com pulsos cheios e simétricos. Restante do exame físico sem alterações. Com base neste quadro clínico e no Manejo de Diarréia Aguda preconizado pelo Ministério da Saúde (2023), assinale a alternativa correta com relação ao manejo inicial deste paciente:","options":{"A":"Deve ser prescrito Zinco 20 mg por 10-14 dias, uma vez que age diminuindo a duração e o risco de recorrência em 3 meses.","B":"Este paciente se enquadra no grupo B, de maneira que seu plano terapêutico envolve tentativa de reidratação oral com terapia de reposição oral, em ambiente hospitalar.","C":"Este paciente possui características que o classificam como grupo C, devendo ser prescrita reidratação endovenosa.","D":"Deve-se iniciar antibioticoterapia, sendo a azitromicina o antibiótico de escolha."},"answer":"B","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (4).pdf","sourceLabel":"Diarreia Aguda","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Nos primeiros anos após a menarca, a imaturidade do eixo hipotálamo-hipófise-ovário leva a ciclos anovulatórios e sangramento irregular, com ultrassom normal.\nPor que as outras estão erradas:\nA: Pólipo causaria lesão focal e não explica o padrão típico logo após a menarca.\nC: Gravidez ectópica exige gestação e costuma cursar com dor e beta-hCG positivo.\nD: Carcinoma endometrial é excepcional nessa idade.\nPonto de prova: Sangramento uterino anormal na adolescência.\nFlashcard sugerido:\nPergunta: Qual a causa mais comum de irregularidade menstrual no primeiro ano pós-menarca?\nResposta: Anovulação por imaturidade do eixo HHO.\n\nPérola:\nAdolescente recém-menarca: primeiro pense em anovulação.\n\nArmadilha:\nInvestigar neoplasia antes de considerar fisiologia puberal.\n\n--------------------------------------------------------------------------------"},{"id":"b12-diarreia-aguda-q28","number":28,"collectionBlock":12,"documentBlock":13,"area":"Pediatria","topic":"Diarreia Aguda","stem":"A desidratação aguda na infância tem como causa principal perdas gastrointestinais por diarreia aguda. A introdução da terapêutica de hidratação oral (HO), associada com a melhora das condições sanitárias, nutricionais e vacinais, promoveram uma redução da morbimortalidade pela doença no Brasil. Com base nos conhecimentos médicos correlatos a respeito da desidratação e da terapêutica de hidratação oral, assinale a alternativa correta:","options":{"A":"Na desidratação moderada, existem perdas de até 10% dos líquidos e sede intensa.","B":"Os parâmetros clínicos para avaliação do grau de desidratação são sede, mucosas, pele e presença de sangue nas fezes.","C":"Após uso da hidratação oral, deve-se suspender a dieta habitual e (ou) aleitamento materno da criança hidratada até a resolução completa do quadro diarreico.","D":"O objetivo do plano B é prevenir a desidratação no domicílio, e isso deve ser realizado pelos pais da criança."},"answer":"A","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (4).pdf","sourceLabel":"Diarreia Aguda","images":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"],"comment":"Análise:\nCorreta: B.\nPor que está certa: O ácido tranexâmico é análogo da lisina que bloqueia a ligação do plasminogênio à fibrina e reduz sua conversão em plasmina, inibindo a fibrinólise.\nPor que as outras estão erradas:\nA: Não aumenta diretamente a síntese de fibrinogênio.\nC: Faz o oposto: preserva a fibrina.\nD: É antifibrinolítico, não ativador do sistema fibrinolítico.\nPonto de prova: Mecanismo dos antifibrinolíticos.\nFlashcard sugerido:\nPergunta: Como age o ácido tranexâmico?\nResposta: Inibe a ativação do plasminogênio e reduz a fibrinólise.\n\nPérola:\nTranexâmico mantém o coágulo; não cria fibrina nova.\n\nArmadilha:\nConfundir antifibrinolítico com pró-coagulante direto.\n\n--------------------------------------------------------------------------------"},{"id":"b12-sangramento-uterino-q01","number":1,"collectionBlock":12,"documentBlock":13,"area":"G.O.","topic":"Sangramento Uterino Anormal","stem":"Paciente de 33 anos, nuligesta, relata, durante a consulta de rotina ginecológica, ciclos menstruais regulares, fluxo dentro do padrão normal, sem queixas álgicas. Apresenta um ultrassom endovaginal com mioma uterino subseroso de 1 cm. A proposta terapêutica nesse caso clínico é:","options":{"A":"Tratamento com progesterona isolada.","B":"Tratamento com anticoncepcional hormonal combinado oral.","C":"Indicação de miomectomia para estudo histopatológico.","D":"Indicação de histerectomia devido ao risco de degeneração maligna.","E":"Conduta expectante."},"answer":"E","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (5).pdf","sourceLabel":"Sangramento Uterino Anormal","images":[],"comment":"Análise:\nCorreta: E.\nPor que está certa: Mioma subseroso de 1 cm, assintomático, sem sangramento ou infertilidade, não exige tratamento; a conduta é observação clínica.\nPor que as outras estão erradas:\nA: Progesterona trata sangramento, não elimina mioma assintomático.\nB: Anticoncepcional pode controlar sangramento, mas não há sintoma a tratar.\nC: Miomectomia não se indica apenas para confirmação histológica em achado típico e pequeno.\nD: Transformação maligna de leiomioma é excepcional e não justifica histerectomia.\nPonto de prova: Indicação de tratamento dos leiomiomas conforme sintomas e desejo reprodutivo.\nFlashcard sugerido:\nPergunta: Qual a conduta para mioma pequeno e assintomático?\nResposta: Expectante.\n\nPérola:\nMioma se trata por sintomas, impacto reprodutivo ou suspeita diagnóstica.\n\nArmadilha:\nTratar o achado de imagem em vez da paciente.\n\n--------------------------------------------------------------------------------","tags":["Ginecologia e Obstetrícia","Ginecologia","Miomatose Uterina","Ciclo Menstrual","Conduta Terapêutica","Paciente Adulto"],"tagSource":"Tags.txt","globalNumber":4},{"id":"b12-sangramento-uterino-q02","number":2,"collectionBlock":12,"documentBlock":13,"area":"G.O.","topic":"Sangramento Uterino Anormal","stem":"Paciente de 41 anos apresenta sangramento uterino volumoso, porém com ciclos regulares, e se encontra estável hemodinamicamente. Os exames de imagem (ultrassonografia e histeroscopia com biópsia) mostram útero sem lesões estruturais. Não foram identificadas coagulopatias, lesões endometriais ou causas iatrogênicas. O diagnóstico provável do sangramento e uma terapia não hormonal, para o caso em questão, respectivamente, são:","options":{"A":"Adenomiose / ácido mefenâmico.","B":"Disfuncional / ácido tranexâmico.","C":"Adenomiose / valerato de estradiol.","D":"Disfuncional / acetato de medroxiprogesterona."},"answer":"B","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (5).pdf","sourceLabel":"Sangramento Uterino Anormal","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Sem causa estrutural, coagulopatia ou iatrogenia, o sangramento é classificado como disfuncional, hoje geralmente AUB-O/AUB-E no sistema PALM-COEIN. O ácido tranexâmico é opção não hormonal eficaz.\nPor que as outras estão erradas:\nA: Adenomiose é causa estrutural e costuma cursar com útero globoso, dor e alterações miometriais.\nC: Valerato de estradiol é hormonal e não corresponde à opção não hormonal solicitada.\nD: Medroxiprogesterona é hormonal.\nPonto de prova: Classificação PALM-COEIN e tratamento não hormonal do sangramento uterino anormal.\nFlashcard sugerido:\nPergunta: Qual terapia não hormonal reduz sangramento uterino anormal sem causa estrutural?\nResposta: Ácido tranexâmico.\n\nPérola:\nSem lesão estrutural, pense em COEIN; tranexâmico é não hormonal.\n\nArmadilha:\nReconhecer o diagnóstico, mas escolher um tratamento hormonal.\n\n--------------------------------------------------------------------------------","tags":["Ginecologia e Obstetrícia","Ginecologia","Sangramento Uterino","Raciocínio Diagnóstico","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags.txt","globalNumber":7},{"id":"b12-sangramento-uterino-q03","number":3,"collectionBlock":12,"documentBlock":13,"area":"G.O.","topic":"Sangramento Uterino Anormal","stem":"M.R.F., feminino, 27 anos, apresenta queixa de sangramento menstrual volumoso, durante período menstrual, e dismenorreia. Ao exame físico, apresenta útero aumentado difusamente e doloroso à palpação. Foi realizada uma ultrassonografia transvaginal, que evidenciou um miométrio heterogêneo e eco endometrial mal definido. Com base nos achados clínicos e ultrassonográficos, assinale a principal hipótese diagnóstica:","options":{"A":"Endometriose.","B":"Câncer de endométrio.","C":"Leiomioma.","D":"Adenomiose.","E":"Pólipo endometrial."},"answer":"D","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (5).pdf","sourceLabel":"Sangramento Uterino Anormal","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: Útero difusamente aumentado e doloroso, miométrio heterogêneo e interface endométrio-miométrio mal definida são achados clássicos de adenomiose.\nPor que as outras estão erradas:\nA: Endometriose é ectópica e costuma envolver ovários, peritônio ou ligamentos, não causar necessariamente aumento uterino difuso.\nB: Câncer endometrial costuma causar sangramento irregular e espessamento/lesão endometrial, especialmente em idade mais avançada.\nC: Leiomioma produz nódulos bem definidos e útero irregular/bocelado.\nE: Pólipo é lesão focal intracavitária.\nPonto de prova: Diagnóstico clínico-ultrassonográfico de adenomiose.\nFlashcard sugerido:\nPergunta: Quais achados sugerem adenomiose?\nResposta: Útero globoso/doloroso, miométrio heterogêneo e zona juncional mal definida.\n\nPérola:\nAdenomiose aumenta o útero de forma difusa; mioma o torna nodular.\n\nArmadilha:\nConfundir miométrio heterogêneo difuso com leiomioma.\n\n--------------------------------------------------------------------------------","tags":["Ginecologia e Obstetrícia","Ginecologia","Ciclo Menstrual","Raciocínio Diagnóstico","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags.txt","globalNumber":10},{"id":"b12-sangramento-uterino-q04","number":4,"collectionBlock":12,"documentBlock":13,"area":"G.O.","topic":"Sangramento Uterino Anormal","stem":"Mulher, 24 anos de idade, refere ciclos menstruais irregulares, com fluxo intenso com coágulos há 1 ano, e aumento da frequência urinária. Exame físico: abdome com massa de superfície bocelada, palpável 3 cm acima da sínfise púbica; toque vaginal: útero móvel, aumentado de volume, com superfície bocelada e anexos livres; especular sem alterações. Ressonância magnética: útero com volume 300 cc, presença de 2 nódulos uterinos (FIGO 1 em parede posterior, de 2,0 cm e FIGO 2-5 em parede anterior de 6 cm). A mais adequada conduta é:","options":{"A":"Histerectomia total abdominal.","B":"Miomectomia histeroscópica e laparoscópica.","C":"Histerectomia subtotal laparoscópica.","D":"Prescrição de contraceptivos hormonal."},"answer":"B","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (5).pdf","sourceLabel":"Sangramento Uterino Anormal","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Há dois miomas sintomáticos com desejo de preservação uterina: FIGO 1, acessível por histeroscopia, e híbrido FIGO 2-5, de grande volume, melhor abordado por laparoscopia.\nPor que as outras estão erradas:\nA: Histerectomia elimina fertilidade e é inadequada em mulher jovem sem menção de prole definida.\nC: Histerectomia subtotal também elimina fertilidade.\nD: Contraceptivos podem reduzir sangramento, mas não tratam adequadamente o efeito de massa nem o mioma grande com impacto urinário.\nPonto de prova: Escolha da via de miomectomia conforme classificação FIGO.\nFlashcard sugerido:\nPergunta: Como tratar miomas FIGO 1 e FIGO 2-5 sintomáticos em mulher que deseja preservar o útero?\nResposta: Miomectomia histeroscópica e laparoscópica, respectivamente.\n\nPérola:\nA localização do mioma determina a via cirúrgica.\n\nArmadilha:\nEscolher uma única via para miomas em compartimentos anatômicos distintos.\n\n--------------------------------------------------------------------------------","tags":["Ginecologia e Obstetrícia","Ginecologia","Ciclo Menstrual","Conduta Terapêutica","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags.txt","globalNumber":11},{"id":"b12-sangramento-uterino-q05","number":5,"collectionBlock":12,"documentBlock":13,"area":"G.O.","topic":"Sangramento Uterino Anormal","stem":"Mulher de 36 anos, GIP0AI, com queixa de sangramento uterino anormal e infertilidade conjugal, busca atendimento no ambulatório de ginecologia. Realiza histeroscopia que identifica mioma de 2cm totalmente intracavitário com pedículo inserido na parede anterior uterina. A classificação desse mioma, de acordo com a FIGO (2011) e o tratamento mais adequado para esse caso, respectivamente, são","options":{"A":"Tipo 0 / miomectomia histeroscópica.","B":"Tipo 0 / histerectomia laparoscópica.","C":"Tipo 8 / histerectomia laparoscópica.","D":"Tipo 8 / miomectomia histeroscópica."},"answer":"A","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (5).pdf","sourceLabel":"Sangramento Uterino Anormal","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: Mioma totalmente intracavitário e pediculado é FIGO 0. A miomectomia histeroscópica é o tratamento conservador de escolha, sobretudo com sangramento e infertilidade.\nPor que as outras estão erradas:\nB: Histerectomia é desproporcional e elimina fertilidade.\nC: FIGO 8 corresponde a localizações não usuais, como cervical ou parasitária, não a mioma intracavitário.\nD: Embora a via histeroscópica seja correta, a classificação FIGO 8 está errada.\nPonto de prova: Classificação FIGO dos miomas submucosos.\nFlashcard sugerido:\nPergunta: Como se classifica e trata um mioma totalmente intracavitário pediculado?\nResposta: FIGO 0; miomectomia histeroscópica.\n\nPérola:\nFIGO 0 flutua na cavidade, preso apenas por pedículo.\n\nArmadilha:\nConfundir FIGO 0 com FIGO 8.\n\n--------------------------------------------------------------------------------","tags":["Ginecologia e Obstetrícia","Ginecologia","Sangramento Uterino","Infertilidade","Conduta Terapêutica","Paciente Adulto"],"tagSource":"Tags.txt","globalNumber":12},{"id":"b12-sangramento-uterino-q06","number":6,"collectionBlock":12,"documentBlock":13,"area":"G.O.","topic":"Sangramento Uterino Anormal","stem":"Mulher, 44 anos de idade, 3G 3P, apresenta dismenorreia progressiva há 2 anos, associada a aumento do volume menstrual e dispaurenia, há 8 meses, dificultando o relacionamento sexual. Ao exame: útero aumentado 2 vezes de tamanho, consistência amolecida. US pélvico: útero heterogêneo, focos hiperecogênicos puntiformes em meio a trama miometrial, espessura endometrial 8 mm, volume uterino: 178 ml, ovários sem alterações. A conduta mais adequada é:","options":{"A":"Prescrever danazol via oral.","B":"Realizar histerectomia sub-total.","C":"Prescrever análogo de GnRH subcutâneo.","D":"Realizar embolização das artérias uterinas."},"answer":"B","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (5).pdf","sourceLabel":"Sangramento Uterino Anormal","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: O quadro é típico de adenomiose sintomática em mulher de 44 anos, multípara e sem desejo reprodutivo explicitado. Entre as opções, a histerectomia é o tratamento definitivo; a alternativa disponível é subtotal.\nPor que as outras estão erradas:\nA: Danazol tem efeitos adversos androgênicos e não é tratamento de escolha atual.\nC: Análogo de GnRH pode reduzir sintomas temporariamente, mas não é estratégia definitiva e causa hipoestrogenismo.\nD: Embolização pode ser considerada em casos selecionados, porém a resposta na adenomiose é variável e não é a opção mais definitiva.\nPonto de prova: Tratamento definitivo da adenomiose.\nFlashcard sugerido:\nPergunta: Qual é o tratamento definitivo da adenomiose em mulher sem desejo gestacional?\nResposta: Histerectomia.\n\nPérola:\nAdenomiose termina no miométrio; retirar o útero é definitivo.\n\nArmadilha:\nEscolher terapia temporária em doença sintomática importante sem desejo reprodutivo.\n\n--------------------------------------------------------------------------------","tags":["Ginecologia e Obstetrícia","Ginecologia","Ciclo Menstrual","Conduta Terapêutica","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags.txt","globalNumber":22},{"id":"b12-sangramento-uterino-q07","number":7,"collectionBlock":12,"documentBlock":13,"area":"G.O.","topic":"Sangramento Uterino Anormal","stem":"O exame mais sensível para mapear miomas, antes da miomectomia, é","options":{"A":"a ultrassonografia pélvica.","B":"a ultrassonografia endovaginal.","C":"a tomografia computadorizada da pelve.","D":"a ressonância nuclear magnética da pelve."},"answer":"D","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (5).pdf","sourceLabel":"Sangramento Uterino Anormal","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: A ressonância magnética oferece maior campo de visão e melhor definição do número, tamanho, localização e relação dos miomas com endométrio e serosa, sendo o método mais sensível para mapeamento pré-operatório complexo.\nPor que as outras estão erradas:\nA: Ultrassonografia pélvica é menos sensível, sobretudo em úteros volumosos.\nB: Ultrassonografia transvaginal é excelente primeira linha, mas pode perder nódulos numerosos ou altos.\nC: Tomografia tem menor contraste de partes moles e não é método de escolha.\nPonto de prova: Escolha do exame para mapeamento de miomas.\nFlashcard sugerido:\nPergunta: Qual exame melhor mapeia miomas antes de miomectomia?\nResposta: Ressonância magnética da pelve.\n\nPérola:\nUS diagnostica; RM mapeia com maior precisão.\n\nArmadilha:\nConfundir exame inicial com exame mais sensível para planejamento.\n\n--------------------------------------------------------------------------------","tags":["Clínica Médica","Medicina Interna","Interpretação de Exames","Paciente Adulto","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags.txt","globalNumber":24},{"id":"b12-sangramento-uterino-q08","number":8,"collectionBlock":12,"documentBlock":13,"area":"G.O.","topic":"Sangramento Uterino Anormal","stem":"Mulher, 40 anos de idade, casada, negra, nuligesta, com desejo reprodutivo, apresenta queixa de sangramento menstrual aumentado há 2 anos. Refere ciclos regulares, fluxo com duração de 10 dias com saída de coágulos, e dismenorreia. Sem comorbidades ou antecedentes cirúrgicos. Exame físico ginecológico: abdome e exame especular sem alterações, toque vaginal evidenciando útero móvel, de superfície bocelada, pouco aumentado de tamanho. Ultrassonografia endovaginal: útero anteversofletido de 120cc, com ecotextura miometrial heterogênea e zona juncional espessada, nódulo intramural de 3,0 cm, eco endometrial de 5,0 mm e anexos sem alterações. Qual é a conduta mais adequada?","options":{"A":"Miomectomia laparoscópica e liberar para engravidar após cirurgia.","B":"Embolização de artérias uterinas e liberar para engravidar após procedimento.","C":"Anti-inflamatório não hormonal e liberar para engravidar.","D":"Miomectomia histeroscópica e fertilização in vitro após cirurgia.","E":"Análogo de GnRH, miomectomia laparoscópica e fertilização in vitro."},"answer":"C","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (5).pdf","sourceLabel":"Sangramento Uterino Anormal","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Os achados sugerem adenomiose associada a pequeno mioma intramural, sem deformação cavitária relevante. Como há desejo reprodutivo, deve-se evitar procedimentos que prejudiquem útero ou reserva; anti-inflamatório controla dismenorreia sem impedir tentativa de gestação.\nPor que as outras estão erradas:\nA: Miomectomia de nódulo intramural de 3 cm sem impacto cavitário não traz benefício reprodutivo claro e não trata adenomiose.\nB: Embolização não é preferida em mulher que deseja gestar devido a efeitos uterinos e obstétricos.\nD: Mioma intramural não é acessível por histeroscopia; FIV não é automaticamente necessária.\nE: GnRH e cirurgia seguida de FIV são excessivos sem avaliação de infertilidade.\nPonto de prova: Tratamento conservador de adenomiose/mioma em mulher com desejo reprodutivo.\nFlashcard sugerido:\nPergunta: Como controlar dismenorreia em paciente que deseja engravidar e não tem mioma cavitário relevante?\nResposta: Anti-inflamatório não hormonal.\n\nPérola:\nPreserve fertilidade: não opere mioma pequeno sem impacto cavitário.\n\nArmadilha:\nIndicar miomectomia apenas porque existe um nódulo.\n\n--------------------------------------------------------------------------------","tags":["Ginecologia e Obstetrícia","Ginecologia","Ciclo Menstrual","Conduta Terapêutica","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags.txt","globalNumber":25},{"id":"b12-sangramento-uterino-q09","number":9,"collectionBlock":12,"documentBlock":13,"area":"G.O.","topic":"Sangramento Uterino Anormal","stem":"Uma adolescente de 14 anos começou a menstruar há um ano. Agora, tem sangramento uterino anormal, com ciclos menstruais que duram entre dois e sete dias, com intervalos de duas a seis semanas. A quantidade de sangramento varia de um gotejamento mínimo a um fluxo muito intenso. No exame físico, não há achados dignos de nota. A ultrassonografia pélvica não aponta anormalidades. Nesse caso, a maior probabilidade de produzir tais achados é:","options":{"A":"pólipo endometrial.","B":"ciclos anovulatórios.","C":"gravidez ectópica.","D":"carcinoma endometrial."},"answer":"B","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (5).pdf","sourceLabel":"Sangramento Uterino Anormal","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Nos primeiros anos após a menarca, a imaturidade do eixo hipotálamo-hipófise-ovário leva a ciclos anovulatórios e sangramento irregular, com ultrassom normal.\nPor que as outras estão erradas:\nA: Pólipo causaria lesão focal e não explica o padrão típico logo após a menarca.\nC: Gravidez ectópica exige gestação e costuma cursar com dor e beta-hCG positivo.\nD: Carcinoma endometrial é excepcional nessa idade.\nPonto de prova: Sangramento uterino anormal na adolescência.\nFlashcard sugerido:\nPergunta: Qual a causa mais comum de irregularidade menstrual no primeiro ano pós-menarca?\nResposta: Anovulação por imaturidade do eixo HHO.\n\nPérola:\nAdolescente recém-menarca: primeiro pense em anovulação.\n\nArmadilha:\nInvestigar neoplasia antes de considerar fisiologia puberal.\n\n--------------------------------------------------------------------------------","tags":["Ginecologia e Obstetrícia","Ginecologia","Sangramento Uterino","Ciclo Menstrual","Interpretação de Exames","Adolescência"],"tagSource":"Tags.txt","globalNumber":27},{"id":"b12-sangramento-uterino-q10","number":10,"collectionBlock":12,"documentBlock":13,"area":"G.O.","topic":"Sangramento Uterino Anormal","stem":"O ácido tranexâmico tem sido utilizado no tratamento de sangramentos uterinos anormais. O seu mecanismo de ação consiste em","options":{"A":"Aumentar o fibrinogênio.","B":"Reduzir a fibrinólise.","C":"Acelerar a degradação de fibrina","D":"Ativar o sistema fibrinolítico."},"answer":"B","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (5).pdf","sourceLabel":"Sangramento Uterino Anormal","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: O ácido tranexâmico é análogo da lisina que bloqueia a ligação do plasminogênio à fibrina e reduz sua conversão em plasmina, inibindo a fibrinólise.\nPor que as outras estão erradas:\nA: Não aumenta diretamente a síntese de fibrinogênio.\nC: Faz o oposto: preserva a fibrina.\nD: É antifibrinolítico, não ativador do sistema fibrinolítico.\nPonto de prova: Mecanismo dos antifibrinolíticos.\nFlashcard sugerido:\nPergunta: Como age o ácido tranexâmico?\nResposta: Inibe a ativação do plasminogênio e reduz a fibrinólise.\n\nPérola:\nTranexâmico mantém o coágulo; não cria fibrina nova.\n\nArmadilha:\nConfundir antifibrinolítico com pró-coagulante direto.\n\n--------------------------------------------------------------------------------","tags":["Clínica Médica","Medicina Interna","Conduta Terapêutica","Paciente Adulto","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags.txt","globalNumber":28},{"id":"b12-sangramento-uterino-q11","number":11,"collectionBlock":12,"documentBlock":13,"area":"G.O.","topic":"Sangramento Uterino Anormal","stem":"A classificação PALM-COEIN, da Federação Internacional de Ginecologia e Obstetrícia (FIGO) para sangramentos uterinos, define como tratamento de primeira linha para, o sangramento uterino em mulheres de baixo risco para câncer de endométrio, com ultrassonografia normal, excluídas as causas estruturais e comorbidades, os:","options":{"A":"Progestágenos ciolícos.","B":"Anticoncepcionais orais combinados.","C":"Antifibrinolíticos, em especial o ácido tranexâmico.","D":"Anti-inflamatórios, principalmente o ácido mefenâmico."},"answer":"B","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (5).pdf","sourceLabel":"Sangramento Uterino Anormal","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Em sangramento uterino anormal sem causa estrutural, baixo risco endometrial e sem contraindicações, anticoncepcional oral combinado é opção de primeira linha para regularizar o ciclo e reduzir o fluxo.\nPor que as outras estão erradas:\nA: Progestágenos cíclicos podem ser usados, mas em geral são menos eficazes que esquemas contínuos ou combinados para controle do fluxo.\nC: Ácido tranexâmico é excelente opção não hormonal, porém a banca considera o combinado como primeira linha no perfil descrito.\nD: AINE reduz prostaglandinas e fluxo, mas costuma ter menor eficácia que terapia hormonal combinada.\nPonto de prova: Tratamento inicial do SUA não estrutural.\nFlashcard sugerido:\nPergunta: Qual opção hormonal de primeira linha para SUA sem causa estrutural e sem contraindicação?\nResposta: Anticoncepcional oral combinado.\n\nPérola:\nNo SUA estável, escolha depende de causa, desejo contraceptivo e contraindicações.\n\nArmadilha:\nAssumir que o tranexâmico é sempre superior, sem considerar o perfil da paciente.\n\n--------------------------------------------------------------------------------","tags":["Clínica Médica","Oncologia","Sangramento Uterino","Conduta Terapêutica","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags.txt","globalNumber":32},{"id":"b12-sangramento-uterino-q12","number":12,"collectionBlock":12,"documentBlock":13,"area":"G.O.","topic":"Sangramento Uterino Anormal","stem":"Mulher, 45 anos de idade, 2 partos vaginais, refere menstruações com duração de 20 dias, com saída de coágulos na maior parte dos dias. Refere cólica menstrual forte que necessita ser medicada com antiinflamatórios há 3 meses. Realizou uma ultrassonografia endovaginal: útero com volume 250 ml com 3 nódulos uterinos intramurais, o maior medindo 40 mm e 1 nódulo em colo uterino medindo 14 mm, espessura endometrial: 10 mm, ovários sem alterações. Qual é a conduta mais adequada?","options":{"A":"Traquelectomia.","B":"Curetagem uterina.","C":"Miomectomias laparoscópica.","D":"Histerectomia vaginal."},"answer":"D","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (5).pdf","sourceLabel":"Sangramento Uterino Anormal","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: Mulher de 45 anos, multípara, com sangramento intenso prolongado e múltiplos miomas, sem desejo reprodutivo informado, tem indicação de tratamento definitivo. A via vaginal é factível em útero de volume moderado e antecedente de partos vaginais.\nPor que as outras estão erradas:\nA: Traquelectomia remove o colo, não resolve miomas corporais múltiplos.\nB: Curetagem não trata leiomiomas intramurais e não é terapia definitiva.\nC: Miomectomia preserva útero, mas é menos adequada quando não há desejo reprodutivo e há múltiplos nódulos sintomáticos.\nPonto de prova: Escolha do tratamento definitivo e da via da histerectomia.\nFlashcard sugerido:\nPergunta: Quando preferir histerectomia em miomatose?\nResposta: Quando sintomas são importantes, prole está definida e terapia conservadora não é necessária.\n\nPérola:\nVia vaginal é favorecida por partos prévios e útero de volume manejável.\n\nArmadilha:\nEscolher miomectomia automaticamente em toda mulher pré-menopáusica.\n\n--------------------------------------------------------------------------------","tags":["Ginecologia e Obstetrícia","Ginecologia","Colo do Útero","Ciclo Menstrual","Conduta Terapêutica","Paciente Adulto"],"tagSource":"Tags.txt","globalNumber":45},{"id":"b12-sangramento-uterino-q13","number":13,"collectionBlock":12,"documentBlock":13,"area":"G.O.","topic":"Sangramento Uterino Anormal","stem":"Uma mulher com 42 anos comparece à unidade básica de saúde para consulta com um médico de família e comunidade. Ela possui histórico de irregularidade menstrual, de irritabilidade, de ansiedade, de perda de memória e de fogachos há 6 meses, apresentando sangramento uterino anormal (SUA) há 3 dias, sem sinais de repercussão na estabilidade hemodinâmica. A partir dessas informações e com base nos conhecimentos acerca do sangramento apresentado por essa paciente, assinale a opção correta:","options":{"A":"O SUA é uma condição rara que afeta poucas mulheres no mundo, principalmente aquelas na pré-menopausa, seguidas por aquelas na perimenopausa e na pós-menopausa.","B":"O SUA é uma afecção frequente que pode comprometer a qualidade da vida da mulher em vários aspectos, sendo recomendado, como terapêutica de primeira linha, a histerectomia.","C":"A presença de lesões vaginais e de colo deve ser descartada por meio do exame físico e a hipótese de gestação deve ser excluída, considerando os principais diagnósticos relacionados ao SUA.","D":"O exame complementar que fornece mais dados para a condução dos casos de SUA é a ultrassonografia da região pélvica, com baixa sensibilidade, porém alta especificidade para lesões endometriais em geral."},"answer":"C","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (5).pdf","sourceLabel":"Sangramento Uterino Anormal","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Em toda mulher em idade reprodutiva com sangramento uterino anormal, a avaliação inicial inclui exame ginecológico para localizar o sangramento e teste de gravidez, mesmo na perimenopausa.\nPor que as outras estão erradas:\nA: SUA é frequente e tem grande impacto na qualidade de vida.\nB: Histerectomia não é primeira linha na maioria dos casos estáveis; tratamento depende da causa e do desejo reprodutivo.\nD: Ultrassonografia transvaginal é primeira linha, mas a descrição universal de baixa sensibilidade e alta especificidade é incorreta.\nPonto de prova: Avaliação inicial do sangramento uterino anormal.\nFlashcard sugerido:\nPergunta: Qual diagnóstico deve sempre ser excluído no SUA em idade reprodutiva?\nResposta: Gestação.\n\nPérola:\nSangramento genital: primeiro localize a origem e exclua gravidez.\n\nArmadilha:\nAtribuir sangramento à transição menopausal sem beta-hCG e exame.\n\n--------------------------------------------------------------------------------","tags":["Ginecologia e Obstetrícia","Ginecologia","Sangramento Uterino","Ansiedade","Conhecimento Conceitual","Atenção Primária"],"tagSource":"Tags.txt","globalNumber":54},{"id":"b12-sangramento-uterino-q14","number":14,"collectionBlock":12,"documentBlock":13,"area":"G.O.","topic":"Sangramento Uterino Anormal","stem":"Uma adolescente de 17 anos vai a consulta na unidade básica de saúde referindo sangramento genital intermitente há 1 mês. Diz que, desde a menarca, que ocorreu aos 12 anos, apresenta ciclos oligomenorreicos, menstruando, no máximo, 4 vezes ao ano. Refere, ainda, possuir pele oleosa e acne. Afirma ter iniciado atividade sexual há 6 meses, com uso irregular de preservativo masculino nas relações. Ao exame físico, apresenta-se hidratada e em bom estado geral. Ao exame ginecológico, observa-se sangramento coletado por espéculo em fundo vaginal, sem lesões visíveis, toque vaginal com o útero móvel, de tamanho habitual e indolor à mobilização do colo uterino. Considerando esse caso, é correto afirmar que:","options":{"A":"A paciente está com sintomas sugestivos de abortamento incompleto, devendo-se realizar uma curetagem uterina.","B":"O quadro clínico é compatível com hiperandrogenismo clínico, devendo-se iniciar o uso de acetato de ciproterona.","C":"O quadro clínico é compatível com a síndrome dos ovários policísticos, o sangramento uterino se deve à anovulação crônica.","D":"A paciente está com sangramento uterino anormal, sendo necessário descartar a possibilidade de gravidez não diagnosticada."},"answer":"D","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (5).pdf","sourceLabel":"Sangramento Uterino Anormal","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: Apesar de oligomenorreia e acne sugerirem anovulação/SOP, a adolescente é sexualmente ativa e usa preservativo irregularmente; qualquer SUA nessa situação exige excluir gestação antes de concluir a etiologia.\nPor que as outras estão erradas:\nA: Abortamento incompleto não pode ser diagnosticado sem confirmar gestação e avaliar ultrassom/colo.\nB: Acne isolada não justifica ciproterona, que não deve ser iniciada antes da investigação.\nC: SOP é possível, mas o diagnóstico não pode preceder a exclusão de gravidez; em adolescentes exige critérios persistentes e cautela.\nPonto de prova: Prioridades diagnósticas no SUA da adolescente sexualmente ativa.\nFlashcard sugerido:\nPergunta: Qual exame é obrigatório no sangramento uterino de adolescente sexualmente ativa?\nResposta: Teste de gravidez.\n\nPérola:\nAntes de chamar de SOP, exclua gestação.\n\nArmadilha:\nFechar diagnóstico de SOP com acne e oligomenorreia sem investigação.\n\n--------------------------------------------------------------------------------","tags":["Ginecologia e Obstetrícia","Ginecologia","Colo do Útero","Ciclo Menstrual","Interpretação de Exames","Adolescência"],"tagSource":"Tags.txt","globalNumber":60},{"id":"b12-sangramento-uterino-q15","number":15,"collectionBlock":12,"documentBlock":13,"area":"G.O.","topic":"Sangramento Uterino Anormal","stem":"Uma mulher de 34 anos, com desejo de gestar, apresenta um exame de imagem cujo laudo refere mioma tipo 7 pela classificação da FIGO. O tipo de mioma e uma possível indicação terapêutica nesse caso, respectivamente, são:","options":{"A":"Submucoso pediculado / miomectomia histeroscópica.","B":"Submucoso pediculado / miomectomia laparoscópica.","C":"Subseroso pediculado / miomectomia histeroscópica.","D":"Subseroso pediculado / miomectomia laparoscópica."},"answer":"D","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (5).pdf","sourceLabel":"Sangramento Uterino Anormal","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: Mioma FIGO 7 é subseroso pediculado. Quando há indicação de remoção e desejo de preservação uterina, a via laparoscópica é apropriada.\nPor que as outras estão erradas:\nA: FIGO 0, não 7, é submucoso pediculado; via histeroscópica seria para intracavitário.\nB: A via laparoscópica está correta para subseroso, mas a classificação anatômica está errada.\nC: Histeroscopia não alcança mioma subseroso externo.\nPonto de prova: Classificação FIGO dos leiomiomas.\nFlashcard sugerido:\nPergunta: O que é um mioma FIGO 7?\nResposta: Subseroso pediculado.\n\nPérola:\nFIGO 0 entra na cavidade; FIGO 7 projeta-se para fora.\n\nArmadilha:\nConfundir os dois tipos pediculados.\n\n--------------------------------------------------------------------------------","tags":["Ginecologia e Obstetrícia","Ginecologia","Miomatose Uterina","Conduta Terapêutica","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags.txt","globalNumber":66},{"id":"b12-sangramento-uterino-q16","number":16,"collectionBlock":12,"documentBlock":13,"area":"G.O.","topic":"Sangramento Uterino Anormal","stem":"R.T.G, 42 anos. Paciente foi encaminhada para o ambulatório de Ginecologia do Hospital Universitário por queixa de sangramento aumentado. Paciente refere fluxo menstrual de 10 dias, com saída de coágulos de grande tamanho associado a cólicas menstruais intensas. Refere piora progressiva do quadro nos últimos anos. 5G5PN e nega antecedentes ginecológicos patológicos prévios. No momento, é sexualmente inativa. Nega comorbidades ou uso de medicações contínuas. Ao exame físico: Bom estado geral, corada, hidratada, anictérica, acianótica e afebril. PA = 120 × 70 mmHg, FC 76 bpm e Sat O2 99%. Abdome flácido, indolor à palpação superficial e profunda, sem visceromegalias. Exame especular com colo epitelizado, conteúdo vaginal fisiológico e sem lesões. Toque vaginal com útero anteversofletido, estando 3cm acima da sínfise púbica. Anexos não palpáveis. Realizado USG TV que evidenciou: Útero em AVF com 180 cc. EE trilaminar de 5,5mm. Assimetria de paredes uterinas, com miométrio de aspecto heterogêneo com presença de cistos miometriais. Qual a principal hipótese diagnóstica para o caso clínico?","options":{"A":"Abortamento em curso.","B":"Miomatose uterina.","C":"Adenomiose.","D":"Pólipo endometrial."},"answer":"C","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (5).pdf","sourceLabel":"Sangramento Uterino Anormal","images":["data:image/webp;base64,"],"comment":"Análise:\nCorreta: E.\nPor que está certa: Taquiarritmia associada a hipotensão grave e dor torácica caracteriza instabilidade hemodinâmica. A conduta imediata é cardioversão elétrica sincronizada, independentemente do mecanismo específico do ritmo.\nPor que as outras estão erradas:\nA: Manobras vagais são reservadas a taquicardia supraventricular regular e estável.\nB: Adenosina pode ser usada em taquicardia regular de QRS estreito estável; não deve atrasar cardioversão no instável.\nC: Amiodarona é opção em alguns ritmos estáveis ou após cardioversão, mas tem início mais lento.\nD: Deslanosídeo não é terapia de emergência para taquiarritmia instável.\nPonto de prova: Reconhecimento de instabilidade em taquiarritmias.\nFlashcard sugerido:\nPergunta: Qual a conduta na taquiarritmia com hipotensão e dor torácica?\nResposta: Cardioversão elétrica sincronizada.\n\nPérola:\nInstabilidade manda mais que o nome da arritmia.\n\nArmadilha:\nTentar tratamento farmacológico enquanto o paciente está em choque.\n\n--------------------------------------------------------------------------------"},{"id":"b12-sangramento-uterino-q17","number":17,"collectionBlock":12,"documentBlock":13,"area":"G.O.","topic":"Sangramento Uterino Anormal","stem":"Mulher de 45 anos, vem em consulta ginecológica com queixa de sangramento uterino aumentado há 3 anos, com piora progressiva de sangramento, refratária a tratamento com anti-inflamatórios e antifibrinolíticos. De antecedentes, paciente 3G3Pc, laqueada no último parto, com antecedente de câncer de mama em remissão completa há 5 anos. Ultrassonografia transvaginal evidencia útero com volume de 255cc às custas de miomas uterinos intramurais e submucosos. A melhor conduta para essa paciente é:","options":{"A":"Histerectomia total.","B":"Miomectomia.","C":"Anticoncepcionais orais combinados.","D":"Progestágenos contínuos."},"answer":"A","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (5).pdf","sourceLabel":"Sangramento Uterino Anormal","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: Miomas intramurais e submucosos com sangramento refratário, prole definida e antecedente de câncer de mama limitando opções hormonais tornam a histerectomia total o tratamento definitivo mais adequado.\nPor que as outras estão erradas:\nB: Miomectomia é preferida quando há desejo de preservar fertilidade/útero; aqui implica maior recorrência e nova intervenção.\nC: Contraceptivo combinado é inadequado pelo antecedente de câncer de mama hormônio-sensível ou potencialmente sensível.\nD: Progestagênio também é problemático em antecedente de câncer de mama e já há falha de medidas conservadoras.\nPonto de prova: Tratamento definitivo da miomatose com contraindicação hormonal.\nFlashcard sugerido:\nPergunta: Qual opção definitiva para miomatose sintomática em mulher com prole definida?\nResposta: Histerectomia.\n\nPérola:\nCâncer de mama estreita o arsenal hormonal.\n\nArmadilha:\nEscolher hormônio sem considerar contraindicação oncológica.\n\n--------------------------------------------------------------------------------","tags":["Ginecologia e Obstetrícia","Obstetrícia","Sangramento Uterino","Saúde Mamária","Conduta Terapêutica","Paciente Adulto"],"tagSource":"Tags.txt","globalNumber":117},{"id":"b12-sangramento-uterino-q18","number":18,"collectionBlock":12,"documentBlock":13,"area":"G.O.","topic":"Sangramento Uterino Anormal","stem":"Mulher de 42 anos, G1C1, laqueada, vem encaminhada a serviço terciário devido a sangramento uterino anormal iniciado há 2 anos, com aumento de volume e duração da menstruação, com piora nos últimos meses. Está em uso de análogo do GnRH há 9 meses com resolução do sangramento. Apresentando sintomas vasomotores e ressecamento vaginal. Comorbidades: HAS bem controlada com uso de medicação, obesidade grau 1. Achados relevantes do exame físico: útero aumentado de volume ao toque vaginal. Exames complementares (realizados no início dos sintomas): ultrassonografia transvaginal mostrando leiomiomatose com presença de múltiplos leiomiomas subserosos e intramurais com volume uterino de 300 cm³. Qual a conduta mais adequada neste caso?","options":{"A":"Indicar histeroscopia cirúrgica.","B":"Iniciar contraceptivo de progestagênio isolado.","C":"Manter análogo de GnRH.","D":"Iniciar contraceptivo combinado."},"answer":"B","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (5).pdf","sourceLabel":"Sangramento Uterino Anormal","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Diante de colapso súbito, a sequência inicial é verificar segurança, responsividade e respiração/pulso rapidamente; só depois se define RCP ou outra intervenção.\nPor que as outras estão erradas:\nA: ECG vem após avaliação inicial e estabilização.\nC: Epinefrina só é indicada após confirmar parada e iniciar RCP conforme algoritmo.\nD: Compressões começam se a pessoa estiver irresponsiva, sem respiração normal e sem pulso; isso ainda não foi checado.\nE: Avaliação especializada não precede o ABC inicial.\nPonto de prova: Primeiro passo na avaliação de colapso.\nFlashcard sugerido:\nPergunta: Qual é a primeira ação diante de uma pessoa que colapsa?\nResposta: Checar responsividade e respiração/pulso rapidamente.\n\nPérola:\nAntes de tratar uma parada, confirme a parada.\n\nArmadilha:\nPular diretamente para compressões ou medicação sem avaliação inicial.\n\n--------------------------------------------------------------------------------"},{"id":"b12-sangramento-uterino-q19","number":19,"collectionBlock":12,"documentBlock":13,"area":"G.O.","topic":"Sangramento Uterino Anormal","stem":"Adolescente de 15 anos relata aumento da duração e do volume da menstruação. AP: menarca aos 12 anos e 6 meses, DUM há 2 meses. Os exames laboratoriais imprescindíveis na avaliação inicial são:","options":{"A":"FSH, TSH e PRL.","B":"Hemograma e BhCG.","C":"Hemograma e coagulograma.","D":"Nenhum; trata-se de imaturidade do eixo hipotálamo-hipófise-ovário."},"answer":"B","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (5).pdf","sourceLabel":"Sangramento Uterino Anormal","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: Endometriose profunda com estenose ureteral tem risco de perda silenciosa da função renal e constitui indicação de abordagem cirúrgica laparoscópica, idealmente multidisciplinar.\nPor que as outras estão erradas:\nA: SIU-LNG controla dor e sangramento, mas não corrige estenose ureteral e ainda impede tentativa gestacional.\nB: Progestagênio isolado controla sintomas, porém não resolve obstrução nem atende ao desejo gestacional imediato.\nC: Contraceptivo combinado também suprime sintomas e contracepção, sem tratar a lesão obstrutiva.\nPonto de prova: Comprometimento ureteral como indicação cirúrgica na endometriose.\nFlashcard sugerido:\nPergunta: Qual achado da endometriose profunda exige intervenção para preservar função renal?\nResposta: Estenose ureteral com ou sem hidronefrose.\n\nPérola:\nUreter comprometido não é caso para apenas suprimir menstruação.\n\nArmadilha:\nEscolher contraceptivo em paciente infértil com obstrução ureteral.\n\n--------------------------------------------------------------------------------"},{"id":"b12-sangramento-uterino-q20","number":20,"collectionBlock":12,"documentBlock":13,"area":"G.O.","topic":"Sangramento Uterino Anormal","stem":"Uma paciente de 30 anos com infertilidade de 2 anos de duração é diagnosticada com múltiplos miomas submucosos. Qual das seguintes afirmações é verdadeira em relação à infertilidade associada a miomas?","options":{"A":"A presença de miomas subserosos é fortemente associada à infertilidade.","B":"Miomas submucosos não afetam a taxa de implantação em técnicas de reprodução assistida.","C":"A miomectomia é recomendada em todos os casos de miomas intramurais, independentemente do tamanho.","D":"Miomas submucosos e intramurais com distorção da cavidade uterina estão associados a taxas mais baixas de implantação e gestação.","E":"A embolização da artéria uterina é o tratamento de escolha para mulheres que desejam preservar a fertilidade."},"answer":"D","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (5).pdf","sourceLabel":"Sangramento Uterino Anormal","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: Na taquicardia supraventricular regular de QRS estreito e paciente estável, após manobras vagais, a primeira dose de adenosina é 6 mg EV em bólus rápido, seguida de flush.\nPor que as outras estão erradas:\nB: 12 mg é a segunda dose se 6 mg falhar.\nC: Amiodarona não é primeira escolha para TSV regular estreita.\nD: Metoprolol pode ser alternativa em casos selecionados, mas não é a sequência inicial clássica.\nE: Taquicardia sustentada sintomática requer intervenção, não observação isolada.\nPonto de prova: Algoritmo da taquicardia supraventricular estável.\nFlashcard sugerido:\nPergunta: Qual a primeira dose de adenosina na TSV regular de QRS estreito?\nResposta: 6 mg EV em bólus rápido.\n\nPérola:\nTSV estável: vagal, depois adenosina 6 mg.\n\nArmadilha:\nComeçar diretamente com 12 mg.\n\n--------------------------------------------------------------------------------"},{"id":"b12-sangramento-uterino-q21","number":21,"collectionBlock":12,"documentBlock":13,"area":"G.O.","topic":"Sangramento Uterino Anormal","stem":"Paciente de 59 anos busca atendimento ginecológico com queixa de sangramento vaginal intermitente há 3 meses, sem investigação até o momento. Antecedentes: nuligesta, IMC 33 kg/m2, HAS em uso de losartana, DUM há 18 meses. Nega uso de TRH. Sobre o tema assinale a alternativa INCORRETA.","options":{"A":"Sua primeira conduta inclui realização de exame especular, solicitação de ultrassom transvaginal e coleta de aspirado endometrial com sonda vesical de alívio, principalmente se houver demora na realização de ultrassonografia.","B":"Em casos de pacientes pós menopausa com espessamento endometrial sem sangramento vaginal, a incidência de câncer de endométrio é de aproximadamente 1%.","C":"90% das pacientes com câncer de endométrio na pós menopausa apresentam espessamento endometrial com sangramento vaginal.","D":"A principal causa de sangramento uterino anormal na pós menopausa é atrofia endometrial e por isso a avaliação histopatológica endometrial é dispensada.","E":"Em caso de paciente virgo, uma forma de avaliar a presença de espessamento endometrial é com a ressonância magnética de pelve."},"answer":"D","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (5).pdf","sourceLabel":"Sangramento Uterino Anormal","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: A alternativa é incorreta porque, embora atrofia endometrial/vaginal seja causa comum de sangramento pós-menopausa, todo sangramento nessa fase exige investigação para excluir câncer endometrial; histologia é indicada conforme espessura, persistência e fatores de risco.\nPor que as outras estão erradas:\nA: Exame especular e ultrassom são adequados; amostragem endometrial precoce é razoável em paciente de alto risco ou quando haverá atraso diagnóstico.\nB: Espessamento assintomático tem risco maligno baixo, em torno de 1% em muitos estudos, e não segue automaticamente o mesmo limiar de 4 mm.\nC: A maioria dos cânceres endometriais se apresenta com sangramento pós-menopausa; a frase busca enfatizar essa associação.\nE: Em pacientes sem possibilidade de ultrassom transvaginal, RM pode complementar, embora ultrassom transabdominal/retal também sejam opções.\nPonto de prova: Investigação obrigatória do sangramento pós-menopausa.\nFlashcard sugerido:\nPergunta: Qual princípio rege o sangramento pós-menopausa?\nResposta: Considerar câncer endometrial até exclusão diagnóstica.\n\nPérola:\nAtrofia é comum, mas câncer é o diagnóstico que não pode ser perdido.\n\nArmadilha:\nDispensar biópsia apenas porque a causa mais frequente é benigna.\n\n--------------------------------------------------------------------------------","tags":["Clínica Médica","Medicina Interna","Sangramento Vaginal","Hipertensão Arterial","Conhecimento Conceitual","Paciente Adulto"],"tagSource":"Tags.txt","globalNumber":123},{"id":"b12-sangramento-uterino-q22","number":22,"collectionBlock":12,"documentBlock":13,"area":"G.O.","topic":"Sangramento Uterino Anormal","stem":"Mulher, 42 anos de idade, apresenta menstruações com fluxo intenso e duração de 10 dias há mais de 6 meses. Ao exame ginecológico, apresenta útero aumentado, móvel, de superfície regular. Ultrassonografia revela miomas subserosos e intramurais, o maior com 5 cm. Foi indicada a inserção de DIU de progesterona. Qual é o objetivo deste tratamento?","options":{"A":"Reduzir o fluxo sanguíneo ao útero.","B":"Bloquear o ciclo ovulatório.","C":"Promover a involução dos leiomiomas.","D":"Promover atrofia endometrial."},"answer":"D","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (5).pdf","sourceLabel":"Sangramento Uterino Anormal","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: O quadro é típico de adenomiose sintomática em mulher de 44 anos, multípara e sem desejo reprodutivo explicitado. Entre as opções, a histerectomia é o tratamento definitivo; a alternativa disponível é subtotal.\nPor que as outras estão erradas:\nA: Danazol tem efeitos adversos androgênicos e não é tratamento de escolha atual.\nC: Análogo de GnRH pode reduzir sintomas temporariamente, mas não é estratégia definitiva e causa hipoestrogenismo.\nD: Embolização pode ser considerada em casos selecionados, porém a resposta na adenomiose é variável e não é a opção mais definitiva.\nPonto de prova: Tratamento definitivo da adenomiose.\nFlashcard sugerido:\nPergunta: Qual é o tratamento definitivo da adenomiose em mulher sem desejo gestacional?\nResposta: Histerectomia.\n\nPérola:\nAdenomiose termina no miométrio; retirar o útero é definitivo.\n\nArmadilha:\nEscolher terapia temporária em doença sintomática importante sem desejo reprodutivo.\n\n--------------------------------------------------------------------------------"},{"id":"b12-sangramento-uterino-q23","number":23,"collectionBlock":12,"documentBlock":13,"area":"G.O.","topic":"Sangramento Uterino Anormal","stem":"Paciente de 34 anos vem à consulta por sangramento uterino anormal há 2 meses. No exame físico especular, foi identificada uma lesão polipoide, friável, extruindo pelo colo uterino. A paciente tem dosagem de progesterona de 4 ng/ml (valores de normalidade após a ovulação 5 a 20 ng/ml) A hipótese diagnóstica mais provável e a conduta adequada são, respectivamente:","options":{"A":"Câncer de colo uterino - realizar citopatológico.","B":"Pólipos cervicais prolapsados - encaminhar para ginecologista.","C":"Abortamento em curso - encaminhar para uma emergência obstétrica.","D":"Mola hidatiforme - iniciar tratamento com metotrexato."},"answer":"B","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (5).pdf","sourceLabel":"Sangramento Uterino Anormal","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Em paciente estável e assintomática, Hb de 7,6 g/dL não impõe transfusão automática; estratégias restritivas geralmente reservam hemácias para Hb <7 g/dL ou sintomas/instabilidade. Entre as opções, não há indicação imediata de hemácias, ferro EV ou eritropoietina na véspera sem planejamento.\nPor que as outras estão erradas:\nA: Ferro EV não corrige anemia em horas e deve ser programado, idealmente com adiamento de cirurgia eletiva quando possível.\nB: Transfusão não é indicada apenas pelo número 7,6 g/dL em paciente estável sem cardiopatia.\nD: Eritropoietina tem resposta tardia e indicações específicas.\nPonto de prova: Indicação transfusional perioperatória e manejo racional da anemia.\nFlashcard sugerido:\nPergunta: Quando transfundir concentrado de hemácias em paciente estável?\nResposta: Em geral, Hb <7 g/dL ou presença de sintomas, instabilidade ou contexto de alto risco.\n\nPérola:\nTransfusão trata repercussão clínica, não apenas um número.\n\nArmadilha:\nTransfundir automaticamente toda Hb abaixo de 8 g/dL.\n\n--------------------------------------------------------------------------------"},{"id":"b12-medidas-associacao-q01","number":1,"collectionBlock":12,"documentBlock":13,"area":"Saúde Coletiva","topic":"Medidas de Associação","stem":"Carla, residente de pediatria, recebe um folder de um representante de laboratório em que consta a informação de que um novo polivitamínico desse laboratório reduziu em 31% o risco de anemia, comparado ao uso do sulfato ferroso, para lactentes entre 6 e 24 meses de vida. Intrigada com um resultado tão expressivo, ela decide analisar melhor o estudo. Trata-se de um ensaio clínico randomizado duplo-cego, aparentemente bem conduzido e sem vieses importantes, exceto por seu financiamento da indústria e consequente conflito de interesse. Ao chegar na seção de resultados do artigo, Carla se depara com a seguinte tabela: | (N° absoluto) | Com anemia | Sem anemia | | ------------- | ---------- | ---------- | | Novo polivitaminico | 4 | 191 | | Sulfato Ferroso | 6 | 196 | Considerando os resultados do novo polivitamínico para a prevenção de anemia sobre o sulfato ferroso na população estudada, assinale a alternativa correta:","options":{"A":"A redução absoluta de risco foi 31%.","B":"A diferença entre o odds ratio (OR) e o risco relativo (RR) foi inferior a 1%.","C":"A chance de anemia no grupo do sulfato ferroso foi 2,97%.","D":"A redução do risco relativo (RRR) foi maior do que 1.","E":"O número necessário para tratar (NNT) foi inferior a 50."},"answer":"B","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (6).pdf","sourceLabel":"Medidas de Associação","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Novo polivitamínico: risco de anemia 4/195=2,05%; sulfato ferroso: 6/202=2,97%. RR≈0,69 e OR≈0,68; a diferença absoluta entre OR e RR é muito pequena, inferior a 1 ponto percentual.\nPor que as outras estão erradas:\nA: A redução absoluta é aproximadamente 0,92 ponto percentual, não 31%; 31% é redução relativa aproximada.\nC: 2,97% é risco, não chance; a chance é 6/196≈3,06%.\nD: A RRR é cerca de 31%, isto é, 0,31, não maior que 1.\nE: NNT≈1/0,0092≈109, portanto não é inferior a 50.\nPonto de prova: Diferença entre risco, chance, RRR, RAR e NNT.\nFlashcard sugerido:\nPergunta: Como calcular a RAR e o NNT quando os riscos são 2,05% e 2,97%?\nResposta: RAR≈0,92%; NNT≈109.\n\nPérola:\nGrande redução relativa pode esconder benefício absoluto pequeno.\n\nArmadilha:\nConfundir redução relativa de 31% com redução absoluta de 31%.\n\n--------------------------------------------------------------------------------","tags":["Saúde Coletiva","Epidemiologia Clínica","Anemia","Metabolismo do Ferro","Prevenção e Rastreamento","Paciente Adulto"],"tagSource":"Tags.txt","globalNumber":5},{"id":"b12-medidas-associacao-q02","number":2,"collectionBlock":12,"documentBlock":13,"area":"Saúde Coletiva","topic":"Medidas de Associação","stem":"Uma determinada doença tem uma taxa de mortalidade de 5%. Ao ser introduzido um método de rastreio, essa taxa caiu para 4%. Em relação às medidas de associação que podemos usar com esses dados, podemos afirmar que:","options":{"A":"A redução do risco relativo foi de 1% e do risco absoluto de 20%.","B":"A redução global do risco foi de 100%.","C":"A redução do risco relativo foi de 20% e do risco absoluto de 1%.","D":"A Odds Ratio foi de 20 vezes a probabilidade de óbitos em relação aos não rastreados."},"answer":"C","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (6).pdf","sourceLabel":"Medidas de Associação","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: A mortalidade caiu de 5% para 4%: redução absoluta do risco = 1 ponto percentual; redução relativa = (5−4)/5 = 20%.\nPor que as outras estão erradas:\nA: Inverte RAR e RRR.\nB: A redução não foi total; houve apenas queda de 1 ponto percentual.\nD: Não há dados que sustentem OR de 20; a razão de riscos seria 0,8.\nPonto de prova: Cálculo de redução absoluta e relativa do risco.\nFlashcard sugerido:\nPergunta: Se o risco cai de 5% para 4%, quais são RAR e RRR?\nResposta: RAR=1%; RRR=20%.\n\nPérola:\nRelativo divide pela linha de base; absoluto apenas subtrai.\n\nArmadilha:\nTrocar 1% e 20%.\n\n--------------------------------------------------------------------------------","tags":["Clínica Médica","Medicina Interna","Conhecimento Conceitual","Paciente Adulto","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags.txt","globalNumber":33},{"id":"b12-medidas-associacao-q03","number":3,"collectionBlock":12,"documentBlock":13,"area":"Saúde Coletiva","topic":"Medidas de Associação","stem":"Um estudo mostrou que câncer de esôfago mostrou um risco de 54% (IC95%, 0,46-0,62) para fumantes. Conclui-se que o fumo é um importante fator de risco e que a cessação dele contribuiria para reduções significativas na incidência de câncer: MENEZES, Ana Mb; HORTA, Bernardo L; OLIVEIRA, André Luiz B; KAUFMANN, Ricardo Ac; DUQUIA, Rodrigo; DINIZ, Alessandro; MOTTA, Luiz Henrique; CENTENO, Marco s; ESTANISLAU, Gustavo; GOMES, Laura. Risco de câncer de pulmão, laringe e esôfago atribuível ao fumo. Revista de Saúde Pública, [S.L.], v. 36, n. 2, p. 129-134, abr. 2002. FapUNIFESP (SciELO). http:// dx.doi.org/10.1590/s0034-89102002000200002. O conceito que melhor avalia essa associação de causalidade é:","options":{"A":"Relação temporal.","B":"Força da associação.","C":"Relação dose-resposta.","D":"Reprodutibilidade dos achados."},"answer":"B","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (6).pdf","sourceLabel":"Medidas de Associação","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Uma associação de grande magnitude entre exposição e desfecho representa o critério de força da associação de Bradford Hill; quanto maior a medida de efeito, menos provável que um confundidor fraco explique todo o achado.\nPor que as outras estão erradas:\nA: Temporalidade exige demonstrar que exposição precedeu o desfecho.\nC: Dose-resposta exige aumento do risco com maior nível de exposição.\nD: Reprodutibilidade corresponde à consistência em diferentes estudos e populações.\nPonto de prova: Critérios de causalidade de Bradford Hill.\nFlashcard sugerido:\nPergunta: Qual critério de Hill corresponde à magnitude elevada da associação?\nResposta: Força da associação.\n\nPérola:\nGrande RR ou OR sugere força; não prova causalidade isoladamente.\n\nArmadilha:\nConfundir percentual atribuível com gradiente dose-resposta.\n\n--------------------------------------------------------------------------------","tags":["Cirurgia","Cirurgia Geral","Esôfago","Neoplasia Esofágica","Epidemiologia Clínica","Paciente Adulto"],"tagSource":"Tags.txt","globalNumber":57},{"id":"b12-medidas-associacao-q04","number":4,"collectionBlock":12,"documentBlock":13,"area":"Saúde Coletiva","topic":"Medidas de Associação","stem":"Um estudo testou um novo medicamento, em comparação com a varfarina, na redução de acidente vascular encefálico ou evento isquêmico. Os dois grupos foram distribuídos de forma aleatória e randomizados, sendo acompanhados por 590 dias. Os resultados do estudo estão abaixo: Com base nas informações, que tipo de estudo é este? Calcule a Redução Absoluta do Risco (RAR) de AVE ou Evento Isquêmico e Estimativa do Tamanho do Efeito de Tratamento (Número Necessário para Tratar - NNT) para se evitar os desfechos considerados no estudo:","options":{"A":"Ensaio Clínico Experimental Crossover; RAR= 0,79 e NNT= 2.","B":"Ensaio Clínico Experimental Paralelo Randomizado; RAR= 0,5 e NNT=2.","C":"Ensaio Clínico Experimental Paralelo Randomizado; RAR= 0,5% e NNT= 200.","D":"Ensaio Clínico Quase-Experimental Fatorial Randomizado; RAR= 0,5% e NNT= 200."},"answer":"C","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (6).pdf","sourceLabel":"Medidas de Associação","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: A alocação aleatória em dois grupos acompanhados paralelamente caracteriza ensaio clínico experimental paralelo randomizado. A diferença absoluta informada é 0,5 ponto percentual; NNT=1/0,005=200.\nPor que as outras estão erradas:\nA: Não houve troca de intervenções entre os mesmos participantes, portanto não é crossover; os cálculos também estão errados.\nB: RAR de 0,5 deve ser expressa como 0,5%, ou 0,005 em proporção; NNT não é 2.\nD: Randomização verdadeira afasta a classificação de quase-experimental; não há desenho fatorial.\nPonto de prova: Identificação do desenho de ensaio clínico e cálculo de NNT.\nFlashcard sugerido:\nPergunta: Como calcular NNT a partir de RAR de 0,5%?\nResposta: 1/0,005=200.\n\nPérola:\nPara NNT, transforme porcentagem em proporção.\n\nArmadilha:\nUsar 0,5 em vez de 0,005.\n\n--------------------------------------------------------------------------------","tags":["Saúde Coletiva","Epidemiologia Clínica","Acidente Vascular Cerebral","Número Necessário para Tratar","Conduta Terapêutica","Paciente Adulto"],"tagSource":"Tags.txt","globalNumber":62},{"id":"b12-medidas-associacao-q05","number":5,"collectionBlock":12,"documentBlock":13,"area":"Saúde Coletiva","topic":"Medidas de Associação","stem":"Para se estabelecer a relação entre a exposição a hipotético fator de risco para a ocorrência de determinada doença, foram selecionados dois grupos de pessoas com características semelhantes (100 pessoas em cada grupo), sendo um grupo exposto ao fator de risco e o outro não exposto. Ao longo de um ano, foram registrados 10 casos da doença no primeiro grupo e 5 casos no segundo grupo. Qual é o valor do risco atribuível nesse estudo?","options":{"A":"0,05.","B":"0,5.","C":"1.","D":"5.","E":"10."},"answer":"A","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (6).pdf","sourceLabel":"Medidas de Associação","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: Risco nos expostos=10/100=0,10; nos não expostos=5/100=0,05. Risco atribuível=0,10−0,05=0,05, ou 5 pontos percentuais.\nPor que as outras estão erradas:\nB: 0,5 seria uma razão ou proporção incorreta para a diferença absoluta.\nC: 1 não decorre dos riscos observados.\nD: 5 expressa 5%, mas a alternativa pedida em proporção é 0,05.\nE: 10 é o número bruto de casos, não a medida de efeito.\nPonto de prova: Cálculo do risco atribuível.\nFlashcard sugerido:\nPergunta: Como calcular o risco atribuível?\nResposta: Incidência nos expostos menos incidência nos não expostos.\n\nPérola:\nRA é diferença, não razão.\n\nArmadilha:\nConfundir 5% com o número 5 quando as opções usam proporções.\n\n--------------------------------------------------------------------------------","tags":["Clínica Médica","Medicina Interna","Epidemiologia Clínica","Paciente Adulto","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags.txt","globalNumber":63},{"id":"b12-medidas-associacao-q06","number":6,"collectionBlock":12,"documentBlock":13,"area":"Saúde Coletiva","topic":"Medidas de Associação","stem":"Em um estudo de coorte, após dez anos de seguimento, a incidência de doença coronariana entre fumantes e não fumantes foi igual a, respectivamente, 5 casos por 1.000 pessoas ano e 1 caso por 1.000 pessoas ano. Por meio de um inquérito dirigido à população total que serviu como fonte para a seleção dos participantes do estudo de coorte, estimou-se em 50% a prevalência do tabagismo. Pode-se afirmar, com base nestas informações, que:","options":{"A":"50% dos casos de doença coronariana na população total são atribuíveis ao tabagismo.","B":"80% dos casos de doença coronariana entre os fumantes são atribuíveis ao tabagismo.","C":"A incidência de doença coronariana entre os fumantes, atribuível ao tabagismo, é de 2.5/1.000.","D":"A incidência de doença coronariana na população total, atribuível ao tabagismo, é de 0,5/1."},"answer":"B","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (6).pdf","sourceLabel":"Medidas de Associação","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Entre fumantes, a fração atribuível é (Ie−I0)/Ie=(5−1)/5=0,80, ou 80%; portanto 80% dos casos entre expostos são atribuíveis ao tabagismo, assumindo causalidade.\nPor que as outras estão erradas:\nA: A fração atribuível populacional não é 50%; com prevalência de 50%, a incidência populacional seria 3/1000 e a FAP=(3−1)/3≈66,7%.\nC: O risco atribuível nos fumantes é 4/1000, não 2,5/1000.\nD: O risco atribuível populacional é 2/1000, não 0,5/1000.\nPonto de prova: Fração atribuível entre expostos e na população.\nFlashcard sugerido:\nPergunta: Como calcular a fração atribuível entre expostos?\nResposta: (Ie−I0)/Ie.\n\nPérola:\nRA é diferença; fração atribuível divide a diferença pelo risco dos expostos.\n\nArmadilha:\nUsar a prevalência da exposição diretamente como fração atribuível.\n\n--------------------------------------------------------------------------------","tags":["Clínica Médica","Medicina Interna","Epidemiologia","Tabagismo","Epidemiologia Clínica","Paciente Adulto"],"tagSource":"Tags.txt","globalNumber":65},{"id":"b12-medidas-associacao-q07","number":7,"collectionBlock":12,"documentBlock":13,"area":"Saúde Coletiva","topic":"Medidas de Associação","stem":"Em um estudo individuado seccional (de prevalência), foi encontrada uma razão de prevalência de 2,2 (com intervalo de confiança condizente). Isso significa que a prevalência do desfecho entre os expostos foi:","options":{"A":"Maior que a prevalência do desfecho entre os não expostos.","B":"Igual a prevalência do desfecho entre os não expostos.","C":"Menor que a prevalência do desfecho entre os não expostos.","D":"Igual ao risco de adoecer entre os não expostos, com significância estatística."},"answer":"A","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (6).pdf","sourceLabel":"Medidas de Associação","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: Razão de prevalência de 2,2 significa que a prevalência do desfecho nos expostos é 2,2 vezes a dos não expostos; como é maior que 1, há associação positiva.\nPor que as outras estão erradas:\nB: Igualdade corresponderia a RP=1.\nC: Prevalência menor corresponderia a RP<1.\nD: Estudo transversal estima prevalência, não risco/incidência, e a frase mistura conceitos.\nPonto de prova: Interpretação da razão de prevalências.\nFlashcard sugerido:\nPergunta: Como interpretar RP=2,2?\nResposta: A prevalência nos expostos é 2,2 vezes a dos não expostos.\n\nPérola:\nRP >1 associação positiva; RP <1 possível proteção.\n\nArmadilha:\nChamar razão de prevalência de risco relativo.\n\n--------------------------------------------------------------------------------","tags":["Clínica Médica","Medicina Interna","Epidemiologia","Epidemiologia Clínica","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags.txt","globalNumber":71},{"id":"b12-medidas-associacao-q08","number":8,"collectionBlock":12,"documentBlock":13,"area":"Saúde Coletiva","topic":"Medidas de Associação","stem":"Você estava lendo um estudo sobre uma nova estatina que prometia redução do risco de infarto agudo do miocárdio (IAM). Você identifica no estudo que houve 15 casos de IAM em 1000 pessoas que usaram a estatina, enquanto que no grupo onde a estatina não foi usada a quantidade de IAM foi de 20 em 1000 pessoas. Considerando as informações acima, podemos concluir que o número Necessário para Tratar (NNT) deste estudo foi de:","options":{"A":"5.","B":"25.","C":"75.","D":"200."},"answer":"D","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (6).pdf","sourceLabel":"Medidas de Associação","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: Risco controle=20/1000=0,020; risco tratado=15/1000=0,015; RAR=0,005. NNT=1/0,005=200.\nPor que as outras estão erradas:\nA: NNT 5 exigiria RAR de 20%.\nB: NNT 25 exigiria RAR de 4%.\nC: NNT 75 exigiria RAR de cerca de 1,33%.\nPonto de prova: Cálculo do NNT.\nFlashcard sugerido:\nPergunta: Qual o NNT quando o risco cai de 2,0% para 1,5%?\nResposta: 200.\n\nPérola:\nPequena diferença absoluta gera NNT alto.\n\nArmadilha:\nUsar a redução relativa de 25% no denominador.\n\n--------------------------------------------------------------------------------","tags":["Saúde Coletiva","Epidemiologia Clínica","Infarto Agudo do Miocárdio","Número Necessário para Tratar","Conhecimento Conceitual","Paciente Adulto"],"tagSource":"Tags.txt","globalNumber":73},{"id":"b12-medidas-associacao-q09","number":9,"collectionBlock":12,"documentBlock":13,"area":"Saúde Coletiva","topic":"Medidas de Associação","stem":"Sobre os critérios para avaliar a associação causal de Bradford Hill, a saber que \"O fator causal deve preceder o fator efeito\", consiste na conceituação de:","options":{"A":"Consistência.","B":"Especificidade.","C":"Temporalidade.","D":"Coerência.","E":"Plausibilidade."},"answer":"C","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (6).pdf","sourceLabel":"Medidas de Associação","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Temporalidade exige que a exposição causal ocorra antes do desfecho; sem essa sequência, não se sustenta causalidade.\nPor que as outras estão erradas:\nA: Consistência é repetição do achado em estudos, populações e métodos distintos.\nB: Especificidade refere-se à relação relativamente delimitada entre exposição e efeito, embora seja critério fraco.\nD: Coerência exige compatibilidade com o conhecimento biológico e epidemiológico disponível.\nE: Plausibilidade é a existência de mecanismo biologicamente razoável.\nPonto de prova: Critérios de Bradford Hill.\nFlashcard sugerido:\nPergunta: Qual critério de Hill exige que a causa preceda o efeito?\nResposta: Temporalidade.\n\nPérola:\nTemporalidade é indispensável; os demais critérios reforçam.\n\nArmadilha:\nConfundir precedência temporal com consistência.\n\n--------------------------------------------------------------------------------","tags":["Clínica Médica","Medicina Interna","Conhecimento Conceitual","Paciente Adulto","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags.txt","globalNumber":76},{"id":"b12-medidas-associacao-q10","number":10,"collectionBlock":12,"documentBlock":13,"area":"Saúde Coletiva","topic":"Medidas de Associação","stem":"Um grupo de pesquisadores conduziu um estudo para avaliar a associação entre o consumo frequente de carne processada e o risco de câncer gástrico. Foram selecionados 250 pacientes diagnosticados com câncer gástrico e 500 indivíduos sem câncer gástrico. Os participantes foram entrevistados sobre seus hábitos alimentares, incluindo o consumo de carne processada (sim ou não). Os resultados foram organizados na seguinte tabela: | | Sem Consumo de Carne Processada | Consumo de Carne Processada | Total | |:--- |:------------------------------ |:-------------------------- |:---- | | Sem câncer | 250 | 250 | 500 | | Com câncer | 70 | 180 | 250 | | Total | 320 | 430 | 750 | Com base nesses dados, qual é o odds ratio (OR) para o consumo de carne processada e o risco de câncer gástrico, e sua interpretação epidemiológica?","options":{"A":"O OR é 2.57, indicando que indivíduos que consomem carne processada frequentemente têm 2.57 vezes mais chance de desenvolver câncer gástrico do que aqueles que não consomem, evidenciando forte associação causal.","B":"O OR é 1.97, sugerindo uma associação moderada entre o consumo de carne processada e o risco de câncer gástrico, mas sem significância estatística, pois o estudo caso-controle não permite inferência causal.","C":"O OR é 1.97, indicando que o consumo de carne processada não está relacionado ao câncer gástrico, pois um OR inferior a 3 não indica associação relevante em epidemiologia.","D":"O OR é 2.57, indicando que o consumo frequente de carne processada está associado a um maior risco de câncer gástrico, mas não prova causalidade, já que estudos caso-controle são observacionais e sujeitos a vieses."},"answer":"D","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (6).pdf","sourceLabel":"Medidas de Associação","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: Em estudo caso-controle, OR=(180×250)/(70×250)=180/70≈2,57. Isso indica maior chance de exposição entre casos, ou associação entre consumo e câncer, mas não prova causalidade.\nPor que as outras estão erradas:\nA: O valor está correto, mas a afirmação de causalidade é excessiva.\nB: O OR foi calculado incorretamente; significância não pode ser inferida apenas do desenho sem intervalo de confiança.\nC: OR de 1,97 ainda indicaria associação, e não existe limiar de 3 para relevância.\nPonto de prova: Cálculo e interpretação do odds ratio em caso-controle.\nFlashcard sugerido:\nPergunta: Como calcular OR em tabela 2×2?\nResposta: Produto cruzado: ad/bc.\n\nPérola:\nOR mede associação; desenho observacional não prova causalidade.\n\nArmadilha:\nUsar o valor correto e extrapolar para causalidade.\n\n--------------------------------------------------------------------------------","tags":["Saúde Coletiva","Epidemiologia Clínica","Odds Ratio","Oncologia","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags.txt","globalNumber":83},{"id":"b12-medidas-associacao-q11","number":11,"collectionBlock":12,"documentBlock":13,"area":"Saúde Coletiva","topic":"Medidas de Associação","stem":"Um ensaio clínico randomizado mostrou redução da pressão arterial com uso de um inibidor cotransportador de sódio- glicose tipo 2 (SGLT-2), resultado semelhante ao obtido previamente com outro fármaco da mesma classe. Qual critério de Hill está sendo exemplificado?","options":{"A":"Plausibilidade biológica.","B":"Consistência.","C":"Gradiente biológico.","D":"Especificidade."},"answer":"B","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (6).pdf","sourceLabel":"Medidas de Associação","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Resultados semelhantes obtidos com diferentes fármacos da mesma classe e em estudos distintos exemplificam consistência: repetição da associação em diferentes circunstâncias.\nPor que as outras estão erradas:\nA: Plausibilidade exigiria explicar mecanismo fisiológico da redução pressórica.\nC: Gradiente biológico exigiria relação dose-resposta.\nD: Especificidade envolveria um efeito delimitado para uma exposição específica.\nPonto de prova: Critério de consistência de Bradford Hill.\nFlashcard sugerido:\nPergunta: Qual critério de Hill é demonstrado quando estudos diferentes reproduzem o mesmo efeito?\nResposta: Consistência.\n\nPérola:\nRepetiu em outro estudo? Consistência.\n\nArmadilha:\nConfundir mecanismo compartilhado de classe com plausibilidade quando a questão enfatiza repetição.\n\n--------------------------------------------------------------------------------","tags":["Saúde Coletiva","Epidemiologia Clínica","Medicina Baseada em Evidências","Classificação Clínica","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags.txt","globalNumber":87},{"id":"b12-medidas-associacao-q12","number":12,"collectionBlock":12,"documentBlock":13,"area":"Saúde Coletiva","topic":"Medidas de Associação","stem":"Um pesquisador estima o Número Necessário para Tratar (NNT) a partir de um RR = 0,80 para um desfecho com risco de 10% no grupo controle. Qual é o valor mais próximo do NNT?","options":{"A":"2.","B":"8.","C":"20.","D":"50.","E":"100."},"answer":"D","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (6).pdf","sourceLabel":"Medidas de Associação","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: Mioma totalmente intracavitário e pediculado é FIGO 0. A miomectomia histeroscópica é o tratamento conservador de escolha, sobretudo com sangramento e infertilidade.\nPor que as outras estão erradas:\nB: Histerectomia é desproporcional e elimina fertilidade.\nC: FIGO 8 corresponde a localizações não usuais, como cervical ou parasitária, não a mioma intracavitário.\nD: Embora a via histeroscópica seja correta, a classificação FIGO 8 está errada.\nPonto de prova: Classificação FIGO dos miomas submucosos.\nFlashcard sugerido:\nPergunta: Como se classifica e trata um mioma totalmente intracavitário pediculado?\nResposta: FIGO 0; miomectomia histeroscópica.\n\nPérola:\nFIGO 0 flutua na cavidade, preso apenas por pedículo.\n\nArmadilha:\nConfundir FIGO 0 com FIGO 8.\n\n--------------------------------------------------------------------------------"},{"id":"b12-medidas-associacao-q13","number":13,"collectionBlock":12,"documentBlock":13,"area":"Saúde Coletiva","topic":"Medidas de Associação","stem":"A equipe de uma Unidade Básica de Saúde (UBS) está preocupada com o aumento de casos de hipertensão arterial entre adultos jovens na comunidade. Então, decide realizar um estudo observacional para investigar se o sedentarismo está associado ao aumento do risco de hipertensão nessa população. O estudo dividiu os participantes em dois grupos, sedentários e não sedentários, e acompanhou esses dois grupos por 12 meses para observar o surgimento de novos casos de hipertensão. Ao final do estudo, é identificado o risco relativo (RR) de 0,6. Nesse estudo, o valor do RR permite inferir que:","options":{"A":"O sedentarismo pode ser um fator protetor para o desenvolvimento da hipertensão.","B":"A prevalência da doença pode ser avaliada, sem possibilidades de associação dos fatores.","C":"Os sedentários têm maior risco de desenvolver hipertensão em comparação com os não sedentários.","D":"O desenho do estudo em questão não permite o uso do RR para avaliar associação entre as variáveis."},"answer":"A","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download (6).pdf","sourceLabel":"Medidas de Associação","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: A supressão do ciclo e a indução de amenorreia com progestagênios, contraceptivos combinados contínuos ou outras terapias hormonais reduzem estímulo estrogênico e dor da endometriose.\nPor que as outras estão erradas:\nA: O diagnóstico pode ser clínico e por imagem; laparoscopia não é obrigatória, e RM não é padrão-ouro universal.\nB: A intensidade da dor não se correlaciona diretamente com número ou extensão das lesões.\nC: CA-125 não mede gravidade nem é teste diagnóstico específico.\nE: Endometrioma não constitui indicação cirúrgica absoluta; a decisão depende de tamanho, sintomas, fertilidade e suspeita de malignidade.\nPonto de prova: Princípios de tratamento clínico da endometriose.\nFlashcard sugerido:\nPergunta: Qual é o objetivo da terapia hormonal na endometriose?\nResposta: Suprimir ovulação/menstruação e induzir amenorreia para controlar sintomas.\n\nPérola:\nA extensão da endometriose não prediz a intensidade da dor.\n\nArmadilha:\nTratar todo endometrioma cirurgicamente.\n\n--------------------------------------------------------------------------------"},{"id":"b12-perioperatorio-q01","number":1,"collectionBlock":12,"documentBlock":13,"area":"Cirurgia","topic":"Perioperatório do Cirurgião","stem":"Um jovem de 28 anos, atleta de natação, será submetido a abdominoplastia após perder 45 kg por cirurgia bariátrica, há 3 anos, e mudança em hábitos de vida. Qual das seguintes medidas apresenta maior impacto na prevenção de infecção do sítio cirúrgico para esse paciente?","options":{"A":"Uso de drenos de sucção e remoção de pelos abdominais.","B":"Tempo cirúrgico abreviado e uso criterioso do eletrocautério.","C":"Uso de antibiótico profilaxia 1 h antes da realização da incisão.","D":"Suplementação preoperatória hipocalórica e com alto teor de proteína."},"answer":"B","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download.pdf","sourceLabel":"Perioperatório do Cirurgião","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Em cirurgia plástica de grande descolamento, menor tempo operatório e uso criterioso do eletrocautério reduzem trauma tecidual, necrose, seroma e tempo de exposição, fatores diretamente relacionados à infecção do sítio cirúrgico.\nPor que as outras estão erradas:\nA: Drenos podem ser necessários, mas não previnem infecção por si; remoção de pelos só deve ocorrer se indispensável e com aparador elétrico.\nC: Antibioticoprofilaxia é relevante, porém não substitui técnica operatória atraumática e controle do tempo cirúrgico; a banca priorizou o fator de maior impacto entre as opções.\nD: Dieta hipocalórica pode piorar cicatrização; correção nutricional deve ser adequada em proteína e energia, não hipocalórica indiscriminadamente.\nPonto de prova: Fatores modificáveis de prevenção de infecção do sítio cirúrgico.\nFlashcard sugerido:\nPergunta: Quais fatores intraoperatórios reduzem infecção em cirurgias de grande descolamento?\nResposta: Redução do tempo cirúrgico e uso criterioso do eletrocautério.\n\nPérola:\nTecido bem perfundido e pouco traumatizado infecta menos.\n\nArmadilha:\nMarcar antibioticoprofilaxia automaticamente sem comparar o impacto global das alternativas.\n\n--------------------------------------------------------------------------------","tags":["Cirurgia","Cirurgia Geral","Cirurgia Bariátrica","Infecção do Sítio Cirúrgico","Prevenção e Rastreamento","Paciente Adulto"],"tagSource":"Tags.txt","globalNumber":2},{"id":"b12-perioperatorio-q02","number":2,"collectionBlock":12,"documentBlock":13,"area":"Cirurgia","topic":"Perioperatório do Cirurgião","stem":"Uma paciente de 42 anos de idade, sem comorbidades, foi submetida à colecistectomia videolaparoscópica eletiva, sem intercorrências, com tempo cirúrgico de trinta minutos, devido à colelitíase. Com base nessa situação hipotética, assinale a alternativa que apresenta a melhor conduta a ser adotada no pós-operatório:","options":{"A":"Hidratação venosa, no pós-operatório, com volume de 40 mL/kg/dia durante o período de jejum, antibioticoprofilaxia com dose única de cefoxitina 2 g e iniciar enoxaparina 40 mg/dia.","B":"Retirar hidratação venosa após 12h da cirurgia, liberação de dieta após eliminação de flatos e iniciar enoxaparina 40 mg/dia.","C":"Não usar sonda nasogástrica, antibioticoprofilaxia com cefoxitina 2 g, de 6/6 h, no primeiro dia de pós-operatório e hidratação venosa com volume de 60 mL/kg/dia.","D":"Mobilização no leito no primeiro dia de pós-operatório, liberação de dieta após eliminação de flatos e antibioticoprofilaxia com dose única de cefoxitina 2g.","E":"Dieta líquida no mesmo dia, de 5 a 12 h após a cirurgia, retirar hidratação venosa após 12h da cirurgia e sentar a paciente fora do leito, no mesmo dia da operação, durante pelo menos 2 h."},"answer":"E","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download.pdf","sourceLabel":"Perioperatório do Cirurgião","images":[],"comment":"Análise:\nCorreta: E.\nPor que está certa: Após colecistectomia videolaparoscópica não complicada, protocolos de recuperação acelerada recomendam alimentação e mobilização precoces, suspensão rápida de fluidos venosos e ausência de antibioticoterapia prolongada.\nPor que as outras estão erradas:\nA: Hidratação fixa, anticoagulação farmacológica e antibiótico não são rotineiros em paciente de baixo risco e cirurgia curta.\nB: Não é necessário aguardar eliminação de flatos para iniciar dieta; enoxaparina depende de estratificação de risco.\nC: Antibiótico por 24 horas e hidratação de 60 mL/kg/dia são excessivos; sonda nasogástrica também não é indicada rotineiramente.\nD: Mobilização apenas no leito e dieta após flatos atrasam recuperação; antibiótico não é necessário no pós-operatório não complicado.\nPonto de prova: Princípios de recuperação pós-operatória acelerada.\nFlashcard sugerido:\nPergunta: Como conduzir o pós-operatório de colecistectomia laparoscópica eletiva não complicada?\nResposta: Dieta e mobilização precoces, retirada rápida de fluidos e sem antibiótico prolongado.\n\nPérola:\nCirurgia laparoscópica simples pede recuperação precoce, não jejum prolongado.\n\nArmadilha:\nEsperar flatos para liberar dieta em cirurgia abdominal não complicada.\n\n--------------------------------------------------------------------------------","tags":["Cirurgia","Cirurgia Geral","Doença Biliar","Cuidados Pós-Operatórios","Conduta Terapêutica","Paciente Adulto"],"tagSource":"Tags.txt","globalNumber":3},{"id":"b12-perioperatorio-q03","number":3,"collectionBlock":12,"documentBlock":13,"area":"Cirurgia","topic":"Perioperatório do Cirurgião","stem":"Um paciente será submetido a uma cirurgia cardíaca eletiva. Qual antibiótico deverá ser preferencialmente utilizado para profilaxia antimicrobiana cirúrgica?","options":{"A":"Cefazolina.","B":"Metronidazol.","C":"Ceftriaxona.","D":"Cefepima.","E":"Ciprofloxacino."},"answer":"A","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download.pdf","sourceLabel":"Perioperatório do Cirurgião","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: A cefazolina cobre adequadamente estafilococos e estreptococos cutâneos, principais agentes em cirurgia cardíaca, com boa penetração e perfil de segurança.\nPor que as outras estão erradas:\nB: Metronidazol cobre anaeróbios e não é adequado isoladamente para flora cutânea.\nC: Ceftriaxona tem espectro mais amplo do que o necessário e não é a escolha padrão.\nD: Cefepima é antipseudomonas e excessivamente ampla.\nE: Ciprofloxacino não oferece cobertura ideal para estafilococos e não é primeira linha.\nPonto de prova: Escolha da antibioticoprofilaxia em cirurgia cardíaca.\nFlashcard sugerido:\nPergunta: Qual antibiótico é preferido na profilaxia de cirurgia cardíaca?\nResposta: Cefazolina.\n\nPérola:\nProfilaxia cirúrgica deve ser estreita e dirigida à flora provável.\n\nArmadilha:\nEscolher antibiótico de espectro mais amplo como se fosse superior.\n\n--------------------------------------------------------------------------------","tags":["Clínica Médica","Medicina Interna","Antimicrobianos","Conhecimento Conceitual","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags.txt","globalNumber":9},{"id":"b12-perioperatorio-q04","number":4,"collectionBlock":12,"documentBlock":13,"area":"Cirurgia","topic":"Perioperatório do Cirurgião","stem":"Em relação ao risco de contaminação, podemos classificar uma cirurgia eletiva de câncer de estômago com abordagem controlada da cavidade gástrica como:","options":{"A":"Limpa.","B":"Contaminada.","C":"Potencialmente contaminada.","D":"Suja.","E":"Infectada."},"answer":"C","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download.pdf","sourceLabel":"Perioperatório do Cirurgião","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Abertura controlada do trato gastrointestinal em cirurgia eletiva, sem contaminação anormal, classifica a operação como potencialmente contaminada ou limpa-contaminada.\nPor que as outras estão erradas:\nA: Cirurgia limpa não entra em tratos respiratório, digestivo, genital ou urinário.\nB: Contaminada envolve falha importante de técnica, extravasamento grosseiro ou inflamação aguda não purulenta.\nD: Suja pressupõe infecção estabelecida, víscera perfurada ou tecido desvitalizado.\nE: Infectada equivale à categoria suja/infectada e não se aplica ao acesso controlado.\nPonto de prova: Classificação das feridas operatórias por grau de contaminação.\nFlashcard sugerido:\nPergunta: Como classificar cirurgia gástrica eletiva com abertura controlada do estômago?\nResposta: Potencialmente contaminada/limpa-contaminada.\n\nPérola:\nEntrada controlada em víscera colonizada não torna a cirurgia contaminada.\n\nArmadilha:\nAssociar qualquer abertura gastrointestinal a cirurgia contaminada.\n\n--------------------------------------------------------------------------------","tags":["Clínica Médica","Oncologia","Classificação Clínica","Paciente Adulto","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags.txt","globalNumber":15},{"id":"b12-perioperatorio-q05","number":5,"collectionBlock":12,"documentBlock":13,"area":"Cirurgia","topic":"Perioperatório do Cirurgião","stem":"Uma paciente de 38 anos foi internada no plantão noturno para realizar cirurgia no dia seguinte. Na checagem de rotina dos exames pré-operatórios, a enfermeira do setor acionou o plantonista da cirurgia, pois a dosagem de hemoglobina da paciente era de 7,6g/dl. Na avaliação médica, constatou-se que a paciente estava assintomática, não tinha comorbidades, não fazia uso de medicações regulares, a frequência cardíaca era de 88 bpm/minuto, a pressão arterial era de 110 × 70 mmhg e iria ser submetida a uma histerectomia em decorrência de miomatose uterina associada a hipermenorreia. A prescrição deixada pela equipe assistente constava apenas de jejum, aferição de dados vitais e medicações sintomáticas. Qual deve ser a conduta do plantonista?","options":{"A":"Prescrever ferro por via endovenosa.","B":"Transfundir concentrado de hemácias.","C":"Manter a prescrição da equipe assistente.","D":"Prescrever eritropoietina por via endovenosa."},"answer":"C","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download.pdf","sourceLabel":"Perioperatório do Cirurgião","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Em paciente estável e assintomática, Hb de 7,6 g/dL não impõe transfusão automática; estratégias restritivas geralmente reservam hemácias para Hb <7 g/dL ou sintomas/instabilidade. Entre as opções, não há indicação imediata de hemácias, ferro EV ou eritropoietina na véspera sem planejamento.\nPor que as outras estão erradas:\nA: Ferro EV não corrige anemia em horas e deve ser programado, idealmente com adiamento de cirurgia eletiva quando possível.\nB: Transfusão não é indicada apenas pelo número 7,6 g/dL em paciente estável sem cardiopatia.\nD: Eritropoietina tem resposta tardia e indicações específicas.\nPonto de prova: Indicação transfusional perioperatória e manejo racional da anemia.\nFlashcard sugerido:\nPergunta: Quando transfundir concentrado de hemácias em paciente estável?\nResposta: Em geral, Hb <7 g/dL ou presença de sintomas, instabilidade ou contexto de alto risco.\n\nPérola:\nTransfusão trata repercussão clínica, não apenas um número.\n\nArmadilha:\nTransfundir automaticamente toda Hb abaixo de 8 g/dL.\n\n--------------------------------------------------------------------------------","tags":["Clínica Médica","Hematologia","Miomatose Uterina","Conduta Terapêutica","Assistência Hospitalar","Avaliação Clínica"],"tagSource":"Tags.txt","globalNumber":23},{"id":"b12-perioperatorio-q06","number":6,"collectionBlock":12,"documentBlock":13,"area":"Cirurgia","topic":"Perioperatório do Cirurgião","stem":"Segundo a classificação de Caprini para pacientes cirúrgicos, assinale a alternativa correta quanto à classificação de risco para TEV (Tromboembolismo Venoso) de um paciente de 54 anos que foi submetido a uma cirurgia de câncer de cólon, aberta, que durou aproximadamente 2h:","options":{"A":"Risco muito baixo.","B":"Risco baixo.","C":"Risco moderado.","D":"Risco alto.","E":"Risco muito alto."},"answer":"D","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download.pdf","sourceLabel":"Perioperatório do Cirurgião","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: No escore de Caprini: idade 41–60 anos = 1 ponto, cirurgia maior >45 min = 2 e câncer = 2; total 5 pontos, classificado como alto risco no modelo usado pela banca.\nPor que as outras estão erradas:\nA: Muito baixo corresponde a 0 ponto.\nB: Baixo corresponde a 1–2 pontos em classificações usuais.\nC: Moderado costuma corresponder a 3–4 pontos.\nE: Muito alto geralmente exige pontuação superior, conforme a versão utilizada.\nPonto de prova: Estratificação de risco de TEV pelo Caprini.\nFlashcard sugerido:\nPergunta: Qual o escore de Caprini de paciente de 54 anos com câncer submetido a cirurgia aberta >45 min?\nResposta: 5 pontos, alto risco.\n\nPérola:\nIdade + cirurgia maior + câncer somam, não substituem.\n\nArmadilha:\nEsquecer de contabilizar a neoplasia.\n\n--------------------------------------------------------------------------------","tags":["Clínica Médica","Oncologia","Classificação Clínica","Paciente Adulto","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags.txt","globalNumber":39},{"id":"b12-perioperatorio-q07","number":7,"collectionBlock":12,"documentBlock":13,"area":"Cirurgia","topic":"Perioperatório do Cirurgião","stem":"Um paciente de 64 anos está sendo preparado para realizar uma hepatectomia direita por neoplasia. Obedecendo as diretrizes de Segurança do Paciente Cirúrgico, qual o melhor momento para a equipe confirmar a reserva sanguínea?","options":{"A":"Na consulta pré-operatória com o cirurgião.","B":"Após avaliar a ressecabilidade do tumor.","C":"Antes da indução anestésica.","D":"Antes da incisão cirúrgica."},"answer":"C","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download.pdf","sourceLabel":"Perioperatório do Cirurgião","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: A confirmação de disponibilidade de sangue e hemoderivados, quando há risco de perda sanguínea importante, integra o sign-in antes da indução anestésica.\nPor que as outras estão erradas:\nA: O planejamento começa no pré-operatório, mas a checagem de segurança deve ser confirmada pela equipe no centro cirúrgico.\nB: Esperar avaliar ressecabilidade é tarde para garantir suporte transfusional.\nD: Antes da incisão corresponde ao time-out, posterior à indução; a reserva já deve estar confirmada.\nPonto de prova: Momentos da lista de verificação de cirurgia segura.\nFlashcard sugerido:\nPergunta: Quando confirmar reserva sanguínea na cirurgia de alto risco hemorrágico?\nResposta: Antes da indução anestésica.\n\nPérola:\nSign-in antes da anestesia; time-out antes da incisão.\n\nArmadilha:\nConfundir as etapas do checklist cirúrgico.\n\n--------------------------------------------------------------------------------","tags":["Clínica Médica","Oncologia","Conhecimento Conceitual","Paciente Adulto","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags.txt","globalNumber":41},{"id":"b12-perioperatorio-q08","number":8,"collectionBlock":12,"documentBlock":13,"area":"Cirurgia","topic":"Perioperatório do Cirurgião","stem":"Homem de 48 anos, portador de hipertensão arterial controlada, foi submetido à herniorrafia inguinal eletiva em esquema ambulatorial, com técnica cirúrgica sem a utilização de tela. Não foi utilizado antibiótico profilático e a anestesia foi apenas espinhal (raquidiana), sem sedação. Após 24 horas da cirurgia, passou a apresentar temperatura axilar de 38,2°C, além de mialgia e cansaço. Não tem perda de apetite ou dor abdominal. Refere dor no local da incisão, porém tolerável e controlável com as medicações analgésicas e anti-inflamatórias prescritas. Qual a melhor alternativa?","options":{"A":"Não deveria ter sido realizada a cirurgia em caráter ambulatorial por conta da hipertensão arterial sistêmica.","B":"A causa mais provável da febre neste paciente é a atelectasia.","C":"Deveria ter sido utilizado antibiótico profilático.","D":"Não é possível descartar totalmente uma causa infecciosa para a febre."},"answer":"D","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download.pdf","sourceLabel":"Perioperatório do Cirurgião","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: Febre nas primeiras 24 horas costuma ser inflamatória ou relacionada a infecção preexistente/viral, mas uma etiologia infecciosa não pode ser excluída apenas pelo tempo; é necessário avaliar clínica e foco.\nPor que as outras estão erradas:\nA: HAS controlada não contraindica cirurgia ambulatorial.\nB: Atelectasia isolada não é explicação comprovada para febre pós-operatória precoce.\nC: Herniorrafia limpa sem tela pode dispensar profilaxia em paciente de baixo risco; a ausência do antibiótico não explica necessariamente a febre.\nPonto de prova: Avaliação de febre pós-operatória precoce.\nFlashcard sugerido:\nPergunta: Febre em 24 horas após cirurgia exclui infecção?\nResposta: Não; o tempo orienta o diferencial, mas não exclui causa infecciosa.\n\nPérola:\nFebre precoce não é sinônimo automático de atelectasia.\n\nArmadilha:\nUsar a antiga regra mnemônica sem avaliação clínica.\n\n--------------------------------------------------------------------------------","tags":["Cirurgia","Anestesiologia","Hipertensão Arterial","Antimicrobianos","Conhecimento Conceitual","Paciente Adulto"],"tagSource":"Tags.txt","globalNumber":42},{"id":"b12-perioperatorio-q09","number":9,"collectionBlock":12,"documentBlock":13,"area":"Cirurgia","topic":"Perioperatório do Cirurgião","stem":"Um homem de 64 anos, apresentando hérnia inguinal dolorosa durante a prática de tênis, hipertensão arterial controlada e histórico de infarto do miocárdio há 4 anos, seguido de angioplastia, permanecendo assintomático desde então. Ao considerar os exames pré-operatórios para a correção da hérnia, quais são os mais usuais e essenciais para avaliação do risco cirúrgico?","options":{"A":"Tomografia computadorizada, dosagem de BNP, gasometria arterial, radiografia detórax e ecocardiograma.","B":"Anamnese, exame físico, eletrocardiograma, radiografia de tórax e ultrassonografiaabdominal.","C":"Ressonância magnética, dosagem de CPK-MB, holter, ecocardiograma e dosagem deácido úrico.","D":"Cintilografia miocárdica, teste de esforço, dosagem de dímero-D, gasometria arterial eultrassonografia doppler.","E":"Anamnese, exame físico, eletrocardiograma e exames laboratoriais rotineiros."},"answer":"E","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download.pdf","sourceLabel":"Perioperatório do Cirurgião","images":[],"comment":"Análise:\nCorreta: E.\nPor que está certa: Avaliação pré-operatória começa por anamnese dirigida, exame físico, capacidade funcional e risco do procedimento; ECG e exames laboratoriais são solicitados conforme idade, comorbidades e cirurgia. Exames avançados só são indicados se mudarem conduta.\nPor que as outras estão erradas:\nA: TC, BNP, gasometria e ecocardiograma não são rotina para hérnia eletiva em paciente estável.\nB: Radiografia de tórax e ultrassom abdominal não são essenciais sem indicação clínica.\nC: RM, CPK-MB, Holter e ácido úrico não integram avaliação básica.\nD: Teste isquêmico e dímero-D não devem ser solicitados indiscriminadamente.\nPonto de prova: Princípios de avaliação pré-operatória racional.\nFlashcard sugerido:\nPergunta: Quais são os pilares da avaliação pré-operatória?\nResposta: Anamnese, exame físico, estratificação de risco e exames seletivos que possam mudar conduta.\n\nPérola:\nExame pré-operatório não é checklist indiscriminado.\n\nArmadilha:\nPedir bateria extensa apenas por antecedente remoto de infarto.\n\n--------------------------------------------------------------------------------","tags":["Cirurgia","Cirurgia Geral","Hérnias","Hérnia Inguinal","Conhecimento Conceitual","Paciente Adulto"],"tagSource":"Tags.txt","globalNumber":46},{"id":"b12-perioperatorio-q10","number":10,"collectionBlock":12,"documentBlock":13,"area":"Cirurgia","topic":"Perioperatório do Cirurgião","stem":"Um paciente com 48 anos de idade, obeso e portador de diabetes mellitus, com mau controle metabólico, foi admitido no setor de emergência com diagnóstico clínico e de imagem de apendicite aguda. Indicada cirurgia de urgência, foi submetido à apendicectomia aberta, com boa evolução clínica, tendo recebido alta após 48 horas. No quarto dia de pós-operatório, procura a clínica da família por ter apresentado um episódio febril. Ao exame físico, observa-se presença de eritema e calor na porção inferior da cicatriz cirúrgica do paciente. Diante desse quadro clínico, é correto afirmar, em relação ao diagnóstico, que se trata de infecção:","options":{"A":"Profunda de sítio operatório, sendo indicada a reoperação para lavagem da cavidade abdominal.","B":"Superficial de sítio operatório, sendo indicada a reoperação para lavagem da cavidade abdominal.","C":"Superficial de sítio operatório, para a qual a obesidade e o diabetes mellitus descompensado podem ter contribuído.","D":"Profunda de sítio operatório, abaixo da camada aponeurótica, para a qual a obesidade e o diabetes mellitus descompensado podem ter contribuído."},"answer":"C","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download.pdf","sourceLabel":"Perioperatório do Cirurgião","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Eritema e calor limitados à pele/subcutâneo da incisão no quarto dia caracterizam infecção superficial do sítio cirúrgico; obesidade e diabetes mal controlado aumentam risco por pior perfusão e resposta imune.\nPor que as outras estão erradas:\nA: Infecção profunda envolve fáscia/músculo e não foi descrita; reoperação abdominal não é automática.\nB: A classificação superficial está correta, mas lavagem da cavidade não é indicada para acometimento superficial.\nD: Não há sinais de comprometimento abaixo da aponeurose.\nPonto de prova: Classificação das infecções do sítio cirúrgico.\nFlashcard sugerido:\nPergunta: O que caracteriza infecção superficial do sítio cirúrgico?\nResposta: Comprometimento de pele e subcutâneo da incisão.\n\nPérola:\nPele/subcutâneo = superficial; fáscia/músculo = profunda.\n\nArmadilha:\nConfundir fatores de risco com profundidade anatômica.\n\n--------------------------------------------------------------------------------","tags":["Cirurgia","Cirurgia Geral","Diabetes Mellitus","Apendicite","Raciocínio Diagnóstico","Urgência e Emergência"],"tagSource":"Tags.txt","globalNumber":55},{"id":"b12-perioperatorio-q11","number":11,"collectionBlock":12,"documentBlock":13,"area":"Cirurgia","topic":"Perioperatório do Cirurgião","stem":"Os afastadores são instrumentos auxiliares e recebem essa denominação porque têm por função separar os tecidos, habitualmente sem neles criar solução de continuidade, facilitando a exposição cirúrgica. Em relação aos afastadores cirúrgicos, assinale a alternativa CORRETA:","options":{"A":"O afastador de Volkmann é utilizado para afastar a parede abdominal em laparotomias.","B":"Tanto o afastador de Deaver quanto o de Gosset necessitam de tração manual constante.","C":"O afastador de Farabeuf pode funcionar como instrumento de diérese, divulsionando tecidos musculares e conjuntivos.","D":"O afastador de Finochietto é utilizado para afastar a parede abdominal em cirurgias em que é necessário explorar o hipogástrio."},"answer":"C","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download.pdf","sourceLabel":"Perioperatório do Cirurgião","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Há dois miomas sintomáticos com desejo de preservação uterina: FIGO 1, acessível por histeroscopia, e híbrido FIGO 2-5, de grande volume, melhor abordado por laparoscopia.\nPor que as outras estão erradas:\nA: Histerectomia elimina fertilidade e é inadequada em mulher jovem sem menção de prole definida.\nC: Histerectomia subtotal também elimina fertilidade.\nD: Contraceptivos podem reduzir sangramento, mas não tratam adequadamente o efeito de massa nem o mioma grande com impacto urinário.\nPonto de prova: Escolha da via de miomectomia conforme classificação FIGO.\nFlashcard sugerido:\nPergunta: Como tratar miomas FIGO 1 e FIGO 2-5 sintomáticos em mulher que deseja preservar o útero?\nResposta: Miomectomia histeroscópica e laparoscópica, respectivamente.\n\nPérola:\nA localização do mioma determina a via cirúrgica.\n\nArmadilha:\nEscolher uma única via para miomas em compartimentos anatômicos distintos.\n\n--------------------------------------------------------------------------------"},{"id":"b12-perioperatorio-q12","number":12,"collectionBlock":12,"documentBlock":13,"area":"Cirurgia","topic":"Perioperatório do Cirurgião","stem":"Durante um mutirão de cirurgias eletivas, a equipe do centro cirúrgico demonstra pressa para iniciar uma herniorrafia. Ao chegar à sala, o cirurgião é informado pelo anestesista de que já está tudo conferido, e que o lado a ser operado é o direito. O paciente encontra-se anestesiado e posicionado. Qual seria uma boa prática nessa situação?","options":{"A":"Prosseguir com a cirurgia, confiando na conferência prévia relatada pelo anestesista.","B":"Interromper o procedimento e suspender a cirurgia, reagendando para outra data em que haja mais tempo disponível para as verificações.","C":"Solicitar que seja aplicado o Checklist de Cirurgia Segura antes da incisão, mesmo com o paciente já anestesiado.","D":"Solicitar a confirmação com a equipe de enfermagem, sem necessidade de aplicação de protocolos, para não atrasar o fluxo do mutirão."},"answer":"C","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download.pdf","sourceLabel":"Perioperatório do Cirurgião","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: Mioma totalmente intracavitário e pediculado é FIGO 0. A miomectomia histeroscópica é o tratamento conservador de escolha, sobretudo com sangramento e infertilidade.\nPor que as outras estão erradas:\nB: Histerectomia é desproporcional e elimina fertilidade.\nC: FIGO 8 corresponde a localizações não usuais, como cervical ou parasitária, não a mioma intracavitário.\nD: Embora a via histeroscópica seja correta, a classificação FIGO 8 está errada.\nPonto de prova: Classificação FIGO dos miomas submucosos.\nFlashcard sugerido:\nPergunta: Como se classifica e trata um mioma totalmente intracavitário pediculado?\nResposta: FIGO 0; miomectomia histeroscópica.\n\nPérola:\nFIGO 0 flutua na cavidade, preso apenas por pedículo.\n\nArmadilha:\nConfundir FIGO 0 com FIGO 8.\n\n--------------------------------------------------------------------------------"},{"id":"b12-perioperatorio-q13","number":13,"collectionBlock":12,"documentBlock":13,"area":"Cirurgia","topic":"Perioperatório do Cirurgião","stem":"A microbiologia das Infecções de Sítio Cirúrgico (ISCs) depende da natureza do procedimento, do local da incisão e da possibilidade de uma cavidade corporal ou víscera oca ser penetrada durante a cirurgia. A antibioticoprofilaxia deve ser devidamente direcionada contra os patógenos mais prováveis. Com relação às ISCs e seus patógenos mais prováveis, assinalar a alternativa CORRETA:","options":{"A":"A maioria das ISCs é provocada pela flora bacteriana da própria pele, que é inoculada na incisão durante o procedimento cirúrgico. Portanto, os patógenos mais frequentemente envolvidos são cocos Gram-negativos).","B":"Em incisões infrainguinais e cirurgias intracavitárias, os bacilos Gram-negativos, tais como a Escherichia coli e a Klebsiella spp. são também potenciais patógenos.","C":"Quando uma cirurgia é realizada na faringe, apenas bactérias aeróbias são potenciais patógenos.","D":"Hospitalização pré-operatória prolongada não é fator de risco para ISCs."},"answer":"B","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download.pdf","sourceLabel":"Perioperatório do Cirurgião","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: A supressão do ciclo e a indução de amenorreia com progestagênios, contraceptivos combinados contínuos ou outras terapias hormonais reduzem estímulo estrogênico e dor da endometriose.\nPor que as outras estão erradas:\nA: O diagnóstico pode ser clínico e por imagem; laparoscopia não é obrigatória, e RM não é padrão-ouro universal.\nB: A intensidade da dor não se correlaciona diretamente com número ou extensão das lesões.\nC: CA-125 não mede gravidade nem é teste diagnóstico específico.\nE: Endometrioma não constitui indicação cirúrgica absoluta; a decisão depende de tamanho, sintomas, fertilidade e suspeita de malignidade.\nPonto de prova: Princípios de tratamento clínico da endometriose.\nFlashcard sugerido:\nPergunta: Qual é o objetivo da terapia hormonal na endometriose?\nResposta: Suprimir ovulação/menstruação e induzir amenorreia para controlar sintomas.\n\nPérola:\nA extensão da endometriose não prediz a intensidade da dor.\n\nArmadilha:\nTratar todo endometrioma cirurgicamente.\n\n--------------------------------------------------------------------------------"},{"id":"b12-perioperatorio-q14","number":14,"collectionBlock":12,"documentBlock":13,"area":"Cirurgia","topic":"Perioperatório do Cirurgião","stem":"Um paciente será submetido à hepatectomia direita por metástase de neoplasia de cólon. Nesse caso, podemos recomendar:","options":{"A":"Manter reposição volêmica com grandes volumes de cristaloides, para antecipar possíveis perdas sanguíneas no transoperatório.","B":"Evitar uso de vasopressores e reposição volêmica abundante para prevenir edema hepático.","C":"Manter PVC entre 2 e 5 mmHg durante a fase de ressecção hepática reduz o sangramento intraoperatório.","D":"Realizar reposição volêmica preferencialmente com coloides sintéticos que não interferem na função hepática."},"answer":"C","source":"AQFM---Extensivo-ENAMED-2026---Bloco-13-download.pdf","sourceLabel":"Perioperatório do Cirurgião","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: A taquicardia atrial geralmente apresenta QRS estreito e ritmo regular, salvo condução AV variável.\nPor que as outras estão erradas:\nA: Fibrilação atrial é irregularmente irregular.\nB: Torsades é taquicardia ventricular polimórfica de QRS largo.\nD: Taquicardia antidrômica conduz pelo feixe acessório no sentido anterógrado e costuma ter QRS largo.\nE: Flutter com bloqueio AV variável produz resposta ventricular irregular.\nPonto de prova: Classificação de taquiarritmias por largura do QRS e regularidade.\nFlashcard sugerido:\nPergunta: Qual taquiarritmia é tipicamente regular e de QRS estreito?\nResposta: Taquicardia atrial.\n\nPérola:\nQRS estreito sugere origem supraventricular, mas a regularidade diferencia os ritmos.\n\nArmadilha:\nConfundir flutter com condução fixa e flutter com bloqueio variável.\n\n--------------------------------------------------------------------------------"}]};
